import base64,struct
def parse(p):
    data=open(p).read(); b64=''.join(l for l in data.splitlines() if not l.startswith('---')); raw=base64.b64decode(b64); off=15
    def rd(b,o):
        l=struct.unpack('>I',b[o:o+4])[0]; o+=4; v=b[o:o+l]; o+=l; return v,o
