import struct, subprocess, os
def run(paths):
    args=[]
    for p in paths: args+=['-r',p]
    try:
        r=subprocess.run(['./executable']+args+['-F','-p','badport'],capture_output=True,text=True,timeout=1)
        # remove listening msgs
        lines=[l for l in r.stderr.strip().splitlines() if 'Failed listening' not in l and 'No listening' not in l and 'Not backgrounding' not in l]
        return r.returncode, lines
    except subprocess.TimeoutExpired:
        return 'RUN',[]
def fields(path):
    d=open(path,'rb').read(); o=0; fs=[]
    while o<len(d):
        l=struct.unpack('>I',d[o:o+4])[0]; fs.append(d[o+4:o+4+l]); o+=4+l
    return fs
def wr(s): return struct.pack('>I',len(s))+s
def write(name, data): open(name,'wb').write(data); return name

templates={'ed':'/tmp/hostkey_ed','rsa':'/tmp/hostkey_rsa','ecdsa':'/tmp/hostkey_ecdsa'}
for name,path in templates.items():
    d=open(path,'rb').read(); fs=fields(path)
    print('\n==',name,'len',len(d),'fields',[len(f) for f in fs])
    # truncations at each field end, mid, after type len bytes etc
    offs=[]; o=0
    for f in fs: offs.append(o); o+=4+len(f)
    offs.append(o)
    for idx,off in enumerate(offs):
        for variant, cut in [('end',off),('minus1',max(0,off-1))]:
            if idx==0 and variant=='minus1': continue
            p=write('/tmp/keytest.bin', d[:cut])
            rc,lines=run([p])
