    for extra in [b'\x00',b'\x00\x00\x00\x00',b'\x00\x00\x00\x01x',b'garbage']:
        p=write('/tmp/keytest.bin',d+extra); rc,lines=run([p]); print(' trailing',extra,rc,lines)
    # first length manipulations
