// ---------- logging ----------

var logMu sync.Mutex
var logOut = os.Stderr

func dbLog(format string, args ...interface{}) {
	now := time.Now()
	msg := fmt.Sprintf(format, args...)
	line := fmt.Sprintf("[%d] %s %s\n", os.Getpid(), now.Format("Jan 02 15:04:05"), msg)
	logMu.Lock()
	logOut.WriteString(line)
	logMu.Unlock()
}

// fatalError is panicked to unwind to a process-level handler which
// formats the message in the manner of dropbear_exit().
type fatalError struct{ msg string }

func (e *fatalError) Error() string { return e.msg }

func fatalf(format string, args ...interface{}) {
	panic(&fatalError{fmt.Sprintf(format, args...)})
}

func strerror(err error) string {
	return cStrerror(err)
}

func errnoString(errno int) string {
	return cStrerrorNum(errno)
}

// truncate at first NUL, mimicking C strings.
func cstr(s string) string {
	if i := strings.IndexByte(s, 0); i >= 0 {
		return s[:i]
	}
	return s
}

// ---------- SSH wire buffer ----------

type buffer struct {
	data []byte
	pos  int
}

func newBuffer(data []byte) *buffer { return &buffer{data: data} }

func (b *buffer) remaining() int { return len(b.data) - b.pos }
func (b *buffer) len() int       { return len(b.data) }

func (b *buffer) getPtr(n int) []byte {
	if n < 0 || b.pos+n > len(b.data) {
		fatalf("Bad buf_getptr")
	}
	p := b.data[b.pos : b.pos+n]
	b.pos += n
	return p
}

func (b *buffer) incrPos(n int) {
	if n < 0 || b.pos+n > len(b.data) {
		fatalf("Bad buf_incrpos")
	}
	b.pos += n
}

func (b *buffer) getByte() byte {
	if b.pos >= len(b.data) {
		fatalf("Bad buf_getbyte")
	}
	v := b.data[b.pos]
	b.pos++
	return v
}

func (b *buffer) getBool() bool { return b.getByte() != 0 }

func (b *buffer) getUint32() uint32 {
	return binary.BigEndian.Uint32(b.getPtr(4))
}

// getString mirrors buf_getstring: strings over 9000 bytes are a
// fatal "String too long".
func (b *buffer) getString() []byte {
	l := b.getUint32()
	if l > 9000 {
		fatalf("String too long")
	}
	return b.getPtr(int(l))
}

func (b *buffer) getStringStr() string { return string(b.getString()) }

// getBytes reads a fixed number of bytes.
func (b *buffer) getBytes(n int) []byte { return b.getPtr(n) }

// peekStringLen reads the next uint32 without consuming beyond it.
// Caller must have checked 4 bytes are present (getUint32 semantics).
func (b *buffer) getMpint() (*big.Int, bool) {
	raw := b.getString()
	return parseMpint(raw)
}

func parseMpint(raw []byte) (*big.Int, bool) {
	if len(raw) == 0 {
		return big.NewInt(0), true
	}
	// Two's complement big-endian.
	v := new(big.Int).SetBytes(raw)
	if raw[0]&0x80 != 0 {
		// negative: value = v - 2^(8*len)
		shift := new(big.Int).Lsh(big.NewInt(1), uint(8*len(raw)))
		v.Sub(v, shift)
		return v, false
	}
	return v, true
}

// mpintBytes returns the raw two's complement magnitude encoding (no length).
func mpintBytes(v *big.Int) []byte {
	if v.Sign() == 0 {
		return []byte{}
	}
	b := v.Bytes()
	if b[0]&0x80 != 0 {
		b = append([]byte{0}, b...)
	}
	return b
}

// ---------- wire writer ----------

func wrapString(b []byte) []byte {
	out := make([]byte, 4, 4+len(b))
	binary.BigEndian.PutUint32(out, uint32(len(b)))
	return append(out, b...)
}

func wrapStringStr(s string) []byte { return wrapString([]byte(s)) }

func appendString(dst, b []byte) []byte {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], uint32(len(b)))
	dst = append(dst, l[:]...)
	return append(dst, b...)
}

func appendUint32(dst []byte, v uint32) []byte {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], v)
	return append(dst, l[:]...)
}

func appendMpint(dst []byte, v *big.Int) []byte {
	return appendString(dst, mpintBytes(v))
}

func makeString(b []byte) []byte { return wrapString(b) }

// splitNameList splits a comma separated SSH name-list.
func splitNameList(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

func containsString(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

// findCommonAlgo returns first element of client list present in server list.
func findCommonAlgo(client, server []string) string {
	for _, c := range client {
		for _, s := range server {
			if c == s {
				return c
			}
		}
	}
	return ""
}
