import "C"

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"unsafe"
)

func cStrerror(err error) string {
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return C.GoString(C.my_strerror(C.int(errno)))
	}
	if err == nil {
		return ""
	}
	s := err.Error()
	// Strip a leading "op path: " style prefix if present is not reliable;
	// capitalise first letter to match strerror style.
	if len(s) > 0 && s[0] >= 'a' && s[0] <= 'z' {
		s = string(s[0]-32) + s[1:]
	}
	return s
}

func cStrerrorNum(e int) string {
	return C.GoString(C.my_strerror(C.int(e)))
}

type passwdInfo struct {
	Name  string
	Pass  string
	UID   int
	GID   int
	Home  string
	Shell string
}

var pwMu sync.Mutex

func lookupUser(name string) *passwdInfo {
	pwMu.Lock()
	defer pwMu.Unlock()
	cn := C.CString(name)
	defer C.free(unsafe.Pointer(cn))
	p := C.my_getpwnam(cn)
	if p == nil {
		return nil
	}
	return &passwdInfo{
		Name:  C.GoString(C.pw_name(p)),
		Pass:  C.GoString(C.pw_passwd(p)),
		UID:   int(C.pw_uid(p)),
		GID:   int(C.pw_gid(p)),
		Home:  C.GoString(C.pw_dir(p)),
		Shell: C.GoString(C.pw_shell(p)),
	}
}

func lookupUserByUID(uid int) *passwdInfo {
	pwMu.Lock()
	defer pwMu.Unlock()
	p := C.my_getpwuid(C.uid_t(uid))
	if p == nil {
		return nil
	}
	return &passwdInfo{
		Name:  C.GoString(C.pw_name(p)),
		Pass:  C.GoString(C.pw_passwd(p)),
		UID:   int(C.pw_uid(p)),
		GID:   int(C.pw_gid(p)),
		Home:  C.GoString(C.pw_dir(p)),
		Shell: C.GoString(C.pw_shell(p)),
	}
}

func lookupShadow(name string) (string, bool) {
	pwMu.Lock()
	defer pwMu.Unlock()
	cn := C.CString(name)
	defer C.free(unsafe.Pointer(cn))
	s := C.my_getspnam(cn)
	if s == nil {
		return "", false
	}
	return C.GoString(C.sp_pwdp(s)), true
}

type groupInfo struct {
	Name    string
	GID     int
	Members []string
}

func lookupGroup(name string) *groupInfo {
	pwMu.Lock()
	defer pwMu.Unlock()
	cn := C.CString(name)
	defer C.free(unsafe.Pointer(cn))
	g := C.my_getgrnam(cn)
	if g == nil {
		return nil
	}
	gi := &groupInfo{Name: C.GoString(C.gr_name(g)), GID: int(C.gr_gid(g))}
	for i := 0; ; i++ {
		m := C.gr_mem_at(g, C.int(i))
		if m == nil {
			break
		}
		gi.Members = append(gi.Members, C.GoString(m))
	}
	return gi
}

func lookupGroupByGID(gid int) *groupInfo {
	pwMu.Lock()
	defer pwMu.Unlock()
	g := C.my_getgrgid(C.gid_t(gid))
	if g == nil {
		return nil
	}
	gi := &groupInfo{Name: C.GoString(C.gr_name(g)), GID: int(C.gr_gid(g))}
	for i := 0; ; i++ {
		m := C.gr_mem_at(g, C.int(i))
		if m == nil {
			break
		}
		gi.Members = append(gi.Members, C.GoString(m))
	}
	return gi
}

func cryptPassword(password, setting string) string {
	pwMu.Lock()
	defer pwMu.Unlock()
	ck := C.CString(password)
	defer C.free(unsafe.Pointer(ck))
	cs := C.CString(setting)
	defer C.free(unsafe.Pointer(cs))
	r := C.my_crypt(ck, cs)
	if r == nil {
		return ""
	}
	return C.GoString(r)
}

func validShells() []string {
	pwMu.Lock()
	defer pwMu.Unlock()
	C.my_setusershell()
	var out []string
	for {
		s := C.my_getusershell()
		if s == nil {
			break
		}
		out = append(out, C.GoString(s))
	}
	C.my_endusershell()
	return out
}

func userGroupList(user string, gid int) []int {
	pwMu.Lock()
	defer pwMu.Unlock()
	cn := C.CString(user)
	defer C.free(unsafe.Pointer(cn))
	n := C.int(64)
	groups := make([]C.gid_t, 64)
	r := C.my_getgrouplist(cn, C.gid_t(gid), &groups[0], &n)
	if r < 0 {
		if n > 64 {
			groups = make([]C.gid_t, int(n))
			r = C.my_getgrouplist(cn, C.gid_t(gid), &groups[0], &n)
			if r < 0 {
				return []int{gid}
			}
		} else {
			return []int{gid}
		}
	}
	out := make([]int, 0, int(n))
	for i := 0; i < int(n); i++ {
		out = append(out, int(groups[i]))
	}
	return out
}

type resolvedAddr struct {
	Family int // AF_INET / AF_INET6 numeric from C
	IP     string
	Port   int
}

// resolveAddrInfo uses getaddrinfo(3) to match C library behaviour and
// error strings of the original. host may be "" for NULL; service is a
// service name or decimal port string.
func resolveAddrInfo(host, service string, passive bool) ([]resolvedAddr, error) {
	var ch *C.char
	if host != "" {
		ch = C.CString(host)
		defer C.free(unsafe.Pointer(ch))
	}
	cs := C.CString(service)
	defer C.free(unsafe.Pointer(cs))
	pasv := C.int(0)
	if passive {
		pasv = 1
	}
	var out *C.char
	errcode := C.my_resolve(ch, cs, pasv, &out)
	if errcode != 0 {
		return nil, &gaiError{code: int(errcode)}
	}
	defer C.free(unsafe.Pointer(out))
	text := C.GoString(out)
	var addrs []resolvedAddr
	for _, line := range strings.Split(text, "\n") {
		if line == "" {
			continue
		}
		f := strings.SplitN(line, " ", 3)
		if len(f) != 3 {
			continue
		}
		fam, _ := strconv.Atoi(f[0])
		port, _ := strconv.Atoi(f[2])
		addrs = append(addrs, resolvedAddr{Family: fam, IP: f[1], Port: port})
	}
	return addrs, nil
}

type gaiError struct{ code int }

func (e *gaiError) Error() string {
	return C.GoString(C.my_gai_strerror(C.int(e.code)))
}

func gaiErrorString(err error) string {
	var ge *gaiError
	if errors.As(err, &ge) {
		return ge.Error()
	}
	return fmt.Sprint(err)
}

func utmpLogin(line, host, user string, pid int) {
	cl := C.CString(line)
	defer C.free(unsafe.Pointer(cl))
	ch := C.CString(host)
	defer C.free(unsafe.Pointer(ch))
	cu := C.CString(user)
	defer C.free(unsafe.Pointer(cu))
	C.my_login(cl, ch, cu, C.int(pid))
}

func utmpLogout(line string) int {
	cl := C.CString(line)
	defer C.free(unsafe.Pointer(cl))
	return int(C.my_logout(cl))
}
