	return append(dst, b...)
}

func appendUint32(dst []byte, v uint32) []byte {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], v)
	return append(dst, l[:]...)
}

func appendMpint(dst []byte, v *big.Int) []byte {
	return appendString(dst, mpintBytes(v))
}

func makeString(b []byte) []byte { return wrapString(b) }

