func (e *gaiError) Error() string {
	return C.GoString(C.my_gai_strerror(C.int(e.code)))
}

func gaiErrorString(err error) string {
	var ge *gaiError
	if errors.As(err, &ge) {
		return ge.Error()
	}
	return fmt.Sprint(err)
}

