package main

import (
	"encoding/binary"
	"math/big"
	"math/bits"
)

// ChaCha20 stream cipher (RFC 8439), implemented from the spec.

type chacha20 struct {
	state [16]uint32
	block [64]byte
	off   int
}

func newChaCha20(key []byte, nonce []byte, counter uint32) *chacha20 {
	c := &chacha20{off: 64}
	c.state[0] = 0x61707865
	c.state[1] = 0x3320646e
	c.state[2] = 0x79622d32
	c.state[3] = 0x6b206574
	for i := 0; i < 8; i++ {
		c.state[4+i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	c.state[12] = counter
	for i := 0; i < 3; i++ {
		c.state[13+i] = binary.LittleEndian.Uint32(nonce[i*4:])
	}
	return c
}

func qr(s *[16]uint32, a, b, c, d int) {
	s[a] += s[b]
	s[d] = bits.RotateLeft32(s[d]^s[a], 16)
	s[c] += s[d]
	s[b] = bits.RotateLeft32(s[b]^s[c], 12)
	s[a] += s[b]
	s[d] = bits.RotateLeft32(s[d]^s[a], 8)
	s[c] += s[d]
	s[b] = bits.RotateLeft32(s[b]^s[c], 7)
}

func (c *chacha20) nextBlock() {
	orig := c.state
	s := c.state
	for i := 0; i < 10; i++ {
		qr(&s, 0, 4, 8, 12)
		qr(&s, 1, 5, 9, 13)
		qr(&s, 2, 6, 10, 14)
		qr(&s, 3, 7, 11, 15)
		qr(&s, 0, 5, 10, 15)
		qr(&s, 1, 6, 11, 12)
		qr(&s, 2, 7, 8, 13)
		qr(&s, 3, 4, 9, 14)
	}
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(c.block[i*4:], s[i]+orig[i])
	}
	c.state[12]++
	// state is not the working state apart from counter: restore
	c.state = orig
	c.state[12]++
	c.off = 0
}

func (c *chacha20) XORKeyStream(dst, src []byte) {
	for i := range src {
		if c.off >= 64 {
			c.nextBlock()
		}
		dst[i] = src[i] ^ c.block[c.off]
		c.off++
	}
}

// Poly1305 one-time authenticator (RFC 8439), using math/big.

var (
	polyP  = new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 130), big.NewInt(5))
	poly2k = new(big.Int).Lsh(big.NewInt(1), 128)
)

func leBytesToBig(b []byte) *big.Int {
	rev := make([]byte, len(b))
	for i, v := range b {
		rev[len(b)-1-i] = v
	}
	return new(big.Int).SetBytes(rev)
}

func poly1305Sum(out *[16]byte, msg []byte, key *[32]byte) {
	rBytes := make([]byte, 16)
	copy(rBytes, key[:16])
	rBytes[3] &= 15
	rBytes[7] &= 15
	rBytes[11] &= 15
	rBytes[15] &= 15
	rBytes[4] &= 252
	rBytes[8] &= 252
	rBytes[12] &= 252
	r := leBytesToBig(rBytes)
	s := leBytesToBig(key[16:32])
	acc := new(big.Int)
	tmp := new(big.Int)
	for len(msg) > 0 {
		n := 16
		if len(msg) < n {
			n = len(msg)
		}
		block := make([]byte, n+1)
		copy(block, msg[:n])
		block[n] = 1
		num := leBytesToBig(block)
		acc.Add(acc, num)
		acc.Mul(acc, r)
		acc.Mod(acc, polyP)
		msg = msg[n:]
	}
	acc.Add(acc, s)
	acc.Mod(acc, poly2k)
	_ = tmp
	b := acc.Bytes() // big-endian, at most 16 bytes
	for i := 0; i < 16; i++ {
		out[i] = 0
	}
	for i := 0; i < len(b); i++ {
		out[i] = b[len(b)-1-i]
	}
}

func poly1305Verify(mac *[16]byte, msg []byte, key *[32]byte) bool {
	var calc [16]byte
	poly1305Sum(&calc, msg, key)
	var diff byte
	for i := 0; i < 16; i++ {
		diff |= calc[i] ^ mac[i]
	}
	return diff == 0
}
