	acc.Mod(acc, poly2k)
	_ = tmp
	b := acc.Bytes() // big-endian, at most 16 bytes
	for i := 0; i < 16; i++ {
		out[i] = 0
	}
	for i := 0; i < len(b); i++ {
		out[i] = b[len(b)-1-i]
	}
}

func poly1305Verify(mac *[16]byte, msg []byte, key *[32]byte) bool {
	var calc [16]byte
	poly1305Sum(&calc, msg, key)
	var diff byte
	for i := 0; i < 16; i++ {
		diff |= calc[i] ^ mac[i]
	}
	return diff == 0
}
