// signkey types
const (
	keyNone = iota
	keyRSA
	keyECDSA256
	keyECDSA384
	keyECDSA521
	keyEd25519
)

var keyTypeNames = map[int]string{
	keyRSA:      "ssh-rsa",
	keyECDSA256: "ecdsa-sha2-nistp256",
	keyECDSA384: "ecdsa-sha2-nistp384",
	keyECDSA521: "ecdsa-sha2-nistp521",
	keyEd25519:  "ssh-ed25519",
}

var keyTypeLabels = map[int]string{
	keyRSA:      "RSA",
	keyECDSA256: "ECDSA256",
	keyECDSA384: "ECDSA384",
	keyECDSA521: "ECDSA521",
	keyEd25519:  "ed25519",
}

// hostkeyAlgoFor maps a key type to the hostkey algorithm name advertised.
func hostkeyAlgoFor(kt int) string {
	if kt == keyRSA {
		return "rsa-sha2-256"
	}
	return keyTypeNames[kt]
}

func keyTypeFromName(name string) int {
	for k, v := range keyTypeNames {
		if v == name {
			return k
		}
	}
	return keyNone
}

