type hostKey struct {
	typ int
	// ed25519
	edPriv ed25519.PrivateKey
	// rsa
	rsaE, rsaN, rsaD *big.Int
	rsaP, rsaQ       *big.Int
	// ecdsa
	ecPriv *ecdsa.PrivateKey
	ecQ    []byte // uncompressed point
}

func (k *hostKey) publicBlob() []byte {
	var out []byte
	switch k.typ {
	case keyEd25519:
		out = appendString(out, []byte("ssh-ed25519"))
		pub := k.edPriv[32:]
		out = appendString(out, pub)
	case keyRSA:
		out = appendString(out, []byte("ssh-rsa"))
		out = appendMpint(out, k.rsaE)
		out = appendMpint(out, k.rsaN)
	case keyECDSA256, keyECDSA384, keyECDSA521:
		curve := curveName(k.typ)
		out = appendString(out, []byte(keyTypeNames[k.typ]))
		out = appendString(out, []byte(curve))
		out = appendString(out, k.ecQ)
	}
	return out
}

func curveName(kt int) string {
	switch kt {
	case keyECDSA256:
		return "nistp256"
	case keyECDSA384:
		return "nistp384"
	case keyECDSA521:
		return "nistp521"
	}
	return ""
}

func curveFor(kt int) elliptic.Curve {
	switch kt {
	case keyECDSA256:
		return elliptic.P256()
	case keyECDSA384:
		return elliptic.P384()
	case keyECDSA521:
		return elliptic.P521()
	}
	return nil
}

func hashForAlgoForECDSA(kt int) (crypto.Hash, hash.Hash) {
	switch kt {
	case keyECDSA384:
		return crypto.SHA384, sha512.New384()
	case keyECDSA521:
		return crypto.SHA512, sha512.New()
	default:
		return crypto.SHA256, sha256.New()
	}
}

// sign returns an SSH signature blob (the contents of the signature
// string: string algorithm, string signature).
func (k *hostKey) sign(randSrc io.Reader, data []byte) []byte {
	switch k.typ {
	case keyEd25519:
		sig := ed25519.Sign(k.edPriv, data)
		var out []byte
		out = appendString(out, []byte("ssh-ed25519"))
		out = appendString(out, sig)
		return out
	case keyRSA:
		h := sha256.Sum256(data)
		sig, err := rsaSignSHA256(randSrc, k, h[:])
		if err != nil {
			fatalf("Error signing")
		}
		var out []byte
		out = appendString(out, []byte("rsa-sha2-256"))
		out = appendString(out, sig)
		return out
	case keyECDSA256, keyECDSA384, keyECDSA521:
		_, hh := hashForAlgoForECDSA(k.typ)
		hh.Write(data)
		sum := hh.Sum(nil)
		r, s, err := ecdsa.Sign(randSrc, k.ecPriv, sum)
		if err != nil {
			fatalf("Error signing")
		}
		var inner []byte
		inner = appendMpint(inner, r)
		inner = appendMpint(inner, s)
		var out []byte
		out = appendString(out, []byte(keyTypeNames[k.typ]))
		out = appendString(out, inner)
		return out
	}
	return nil
}

// RSA PKCS#1 v1.5 signing using only n and d (mirrors the original,
// which does not rely on CRT parameters).
func rsaSignSHA256(randSrc io.Reader, k *hostKey, digest []byte) ([]byte, error) {
	// Use crypto/rsa if we have valid primes, else raw exponentiation.
	if k.rsaP != nil && k.rsaQ != nil {
		priv := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{N: k.rsaN, E: int(k.rsaE.Int64())},
			D:         k.rsaD,
			Primes:    []*big.Int{k.rsaP, k.rsaQ},
		}
		if priv.Validate() == nil {
			priv.Precompute()
			return rsa.SignPKCS1v15(randSrc, priv, crypto.SHA256, digest)
		}
	}
	return rsaRawSign(k.rsaN, k.rsaD, crypto.SHA256, digest)
}

var hashPrefixes = map[crypto.Hash][]byte{
	crypto.SHA1:   {0x30, 0x21, 0x30, 0x09, 0x06, 0x05, 0x2b, 0x0e, 0x03, 0x02, 0x1a, 0x05, 0x00, 0x04, 0x14},
	crypto.SHA256: {0x30, 0x31, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01, 0x05, 0x00, 0x04, 0x20},
	crypto.SHA512: {0x30, 0x51, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x03, 0x05, 0x00, 0x04, 0x40},
}

func rsaRawSign(n, d *big.Int, hashAlgo crypto.Hash, digest []byte) ([]byte, error) {
	prefix := hashPrefixes[hashAlgo]
	k := (n.BitLen() + 7) / 8
	if k < len(prefix)+len(digest)+11 {
		return nil, errors.New("key too small")
	}
	em := make([]byte, k)
	em[1] = 1
	for i := 2; i < k-len(prefix)-len(digest)-1; i++ {
		em[i] = 0xff
	}
	copy(em[k-len(prefix)-len(digest):], prefix)
	copy(em[k-len(digest):], digest)
	m := new(big.Int).SetBytes(em)
	s := new(big.Int).Exp(m, d, n)
	out := s.Bytes()
	if len(out) < k {
		pad := make([]byte, k-len(out))
		out = append(pad, out...)
	}
	return out, nil
}

func fingerprintSHA256(blob []byte) string {
	sum := sha256.Sum256(blob)
	return strings.TrimRight(base64.StdEncoding.EncodeToString(sum[:]), "=")
}

// ---------- public key (for auth verification) ----------

type pubKey struct {
	typ    int    // key type for plain keys, or special below
	algo   string // algorithm name in blob (e.g. ssh-rsa, sk-...)
	blob   []byte // full marshalled public key blob
	// rsa
	rsaE, rsaN *big.Int
	// ecdsa
	ecX, ecY *big.Int
	ecCurve  elliptic.Curve
	// ed25519 / sk
	edPub []byte
	// sk-ecdsa
	skApp string
	isSK  bool
}

func (p *pubKey) fingerprint() string { return fingerprintSHA256(p.blob) }

// keyTypeString returns the name used in "with %s key" log messages,
// which is the blob's type name.
func (p *pubKey) keyTypeString() string {
	return p.algo
}

// parsePubkeyBlob parses a marshalled public key. Returns nil if the
// type is unsupported or the format is invalid. Possible fatal panics
// from the buffer mimic buffer functions used by the original when
// parsing fields *within* a blob; the caller recovers contextually
// in auth handling. For authorized_keys parsing, invalid blobs simply
// don't match (see caller handling there).
func parsePubkeyBlob(blob []byte) *pubKey {
	b := newBuffer(blob)
	algo := b.getStringStr()
	pk := &pubKey{algo: algo, blob: append([]byte(nil), blob...)}
	switch algo {
	case "ssh-ed25519":
		pk.typ = keyEd25519
		pk.edPub = b.getString()
		if len(pk.edPub) != 32 {
			return nil
		}
	case "sk-ssh-ed25519@openssh.com":
		pk.typ = keyEd25519
		pk.isSK = true
		pk.edPub = b.getString()
		if len(pk.edPub) != 32 {
			return nil
		}
		pk.skApp = b.getStringStr()
	case "ssh-rsa":
		pk.typ = keyRSA
		e, ok1 := b.getMpint()
		n, ok2 := b.getMpint()
		if !ok1 || !ok2 {
			return nil
		}
		pk.rsaE, pk.rsaN = e, n
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		pk.typ = keyTypeFromName(algo)
		curve := b.getStringStr()
		if curve != curveName(pk.typ) {
			return nil
		}
		q := b.getString()
		c := curveFor(pk.typ)
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return nil
		}
		pk.ecX, pk.ecY, pk.ecCurve = x, y, c
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		pk.typ = keyECDSA256
		pk.isSK = true
		curve := b.getStringStr()
		if curve != "nistp256" {
			return nil
		}
		q := b.getString()
		c := elliptic.P256()
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return nil
		}
		pk.ecX, pk.ecY, pk.ecCurve = x, y, c
		pk.skApp = b.getStringStr()
	default:
		return nil
	}
	return pk
}

// verifySignature checks an SSH signature blob over data.
// sigAlgo is the algorithm reported in the signature itself.
func (p *pubKey) verifySignature(data, sigBlob []byte) bool {
	b := newBuffer(sigBlob)
	sigAlgo := b.getStringStr()
	sig := b.getString()
	return p.verifyWithAlgo(data, sigAlgo, sig, nil)
}

// verifyWithAlgo: for SK keys the signature has additional structure;
// sig here is the inner signature string content.
func (p *pubKey) verifyWithAlgo(data []byte, sigAlgo string, sig []byte, sessionID []byte) bool {
	if p.isSK {
		return p.verifySK(data, sigAlgo, sig)
	}
	switch p.typ {
	case keyEd25519:
		if sigAlgo != "ssh-ed25519" {
			return false
		}
		if len(sig) != ed25519.SignatureSize {
			return false
		}
		return ed25519.Verify(ed25519.PublicKey(p.edPub), data, sig)
	case keyRSA:
		if sigAlgo != "rsa-sha2-256" {
			return false
		}
		h := sha256.Sum256(data)
		pub := &rsa.PublicKey{N: p.rsaN, E: int(p.rsaE.Int64())}
		return rsa.VerifyPKCS1v15(pub, crypto.SHA256, h[:], sig) == nil
	case keyECDSA256, keyECDSA384, keyECDSA521:
		if sigAlgo != keyTypeNames[p.typ] {
			return false
		}
		// inner: mpint r, mpint s
		ib := newBuffer(sig)
		r, ok1 := ib.getMpint()
		s, ok2 := ib.getMpint()
		if !ok1 || !ok2 {
			return false
		}
		_, hh := hashForAlgoForECDSA(p.typ)
		hh.Write(data)
		pub := &ecdsa.PublicKey{Curve: p.ecCurve, X: p.ecX, Y: p.ecY}
		return ecdsa.Verify(pub, hh.Sum(nil), r, s)
	}
	return false
}

func (p *pubKey) verifySK(data []byte, sigAlgo string, sig []byte) bool {
	// SK signature format: string algo is already stripped by caller path;
	// Here sig is signature blob content which for SK is:
	//   raw signature bytes (for ed25519: 64) or (mpint r, mpint s) for ecdsa,
	// but the SSH wire signature field for SK keys contains a substructure:
	//   string signature, byte flags, uint32 counter
	// Our caller in auth.go handles the SK substructure explicitly, so this
	// fallback simply fails.
	return false
}

// ---------- host key file loading / generation ----------

type loadResult struct {
	key    *hostKey
	typ    int // identified key type, keyNone if unknown
	ok     bool
}

// loadHostkeyFile reads one dropbear-format private key file.
// Non-fatal failures return ok=false. Malformed buffers may panic
// with fatalError like the original's dropbear_exit from buf helpers.
func loadHostkeyFile(path string) loadResult {
	data, err := os.ReadFile(path)
	if err != nil {
		return loadResult{}
	}
	b := newBuffer(data)
	typName := b.getStringStr()
	typ := keyTypeFromName(typName)
	if typ == keyNone {
		return loadResult{}
	}
	switch typ {
	case keyEd25519:
		// Reads the length first (fatal if <4 bytes remain), then
		// validates it without a fatal buffer read.
		l := b.getUint32()
		if l != 64 || b.remaining() < 64 {
			return loadResult{typ: typ}
		}
		priv := b.getPtr(64)
		k := &hostKey{typ: typ, edPriv: ed25519.PrivateKey(append([]byte(nil), priv...))}
		return loadResult{key: k, typ: typ, ok: true}
	case keyRSA:
		e, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		n, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		if n.BitLen() < 1024 {
			dbLog("RSA key too short")
			return loadResult{typ: typ}
		}
		d, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		k := &hostKey{typ: typ, rsaE: e, rsaN: n, rsaD: d}
		if b.remaining() > 0 {
			p, ok1 := b.getMpint()
			q, ok2 := b.getMpint()
			if ok1 && ok2 {
				k.rsaP, k.rsaQ = p, q
			}
		}
		return loadResult{key: k, typ: typ, ok: true}
	case keyECDSA256, keyECDSA384, keyECDSA521:
		curveStr := b.getStringStr()
		if curveStr != curveName(typ) {
			return loadResult{typ: typ}
		}
		q := b.getString()
		if len(q) == 0 {
			fatalf("Bad buf_getbyte")
		}
		c := curveFor(typ)
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return loadResult{typ: typ}
		}
		priv, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		k := &hostKey{typ: typ, ecQ: append([]byte(nil), q...), ecPriv: &ecdsa.PrivateKey{
			PublicKey: ecdsa.PublicKey{Curve: c, X: x, Y: y}, D: priv,
		}}
		return loadResult{key: k, typ: typ, ok: true}
	}
	return loadResult{}
}

// encodeHostkey serialises a host key in dropbear private format.
func encodeHostkey(k *hostKey) []byte {
	var out []byte
	switch k.typ {
	case keyEd25519:
		out = appendString(out, []byte("ssh-ed25519"))
		out = appendString(out, []byte(k.edPriv))
	case keyRSA:
		out = appendString(out, []byte("ssh-rsa"))
		out = appendMpint(out, k.rsaE)
		out = appendMpint(out, k.rsaN)
		out = appendMpint(out, k.rsaD)
		out = appendMpint(out, k.rsaP)
		out = appendMpint(out, k.rsaQ)
	case keyECDSA256, keyECDSA384, keyECDSA521:
		out = appendString(out, []byte(keyTypeNames[k.typ]))
		out = appendString(out, []byte(curveName(k.typ)))
		out = appendString(out, k.ecQ)
		out = appendMpint(out, k.ecPriv.D)
	}
	return out
}

func generateHostkey(typ int) (*hostKey, error) {
	switch typ {
	case keyEd25519:
		_, priv, err := ed25519.GenerateKey(rand.Reader)
		if err != nil {
			return nil, err
		}
		return &hostKey{typ: typ, edPriv: priv}, nil
	case keyRSA:
		priv, err := rsa.GenerateKey(rand.Reader, 2048)
		if err != nil {
			return nil, err
		}
		return &hostKey{typ: typ, rsaE: big.NewInt(int64(priv.E)), rsaN: priv.N, rsaD: priv.D, rsaP: priv.Primes[0], rsaQ: priv.Primes[1]}, nil
	case keyECDSA256, keyECDSA384, keyECDSA521:
		c := curveFor(typ)
		priv, err := ecdsa.GenerateKey(c, rand.Reader)
		if err != nil {
			return nil, err
		}
		q := elliptic.Marshal(c, priv.X, priv.Y)
		return &hostKey{typ: typ, ecPriv: priv, ecQ: q}, nil
	}
	return nil, fmt.Errorf("unknown type")
}

// checkBytesEqual compares two blobs.
func checkBytesEqual(a, b []byte) bool { return bytes.Equal(a, b) }
