	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		pk.typ = keyTypeFromName(algo)
		curve := b.getStringStr()
		if curve != curveName(pk.typ) {
			return nil
		}
		q := b.getString()
		c := curveFor(pk.typ)
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return nil
		}
		pk.ecX, pk.ecY, pk.ecCurve = x, y, c
	case "sk-ecdsa-sha2-nistp256@openssh.com":
		pk.typ = keyECDSA256
		pk.isSK = true
		curve := b.getStringStr()
		if curve != "nistp256" {
			return nil
		}
		q := b.getString()
		c := elliptic.P256()
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return nil
		}
		pk.ecX, pk.ecY, pk.ecCurve = x, y, c
		pk.skApp = b.getStringStr()
	default:
		return nil
	}
	return pk
}

// verifySignature checks an SSH signature blob over data.
// sigAlgo is the algorithm reported in the signature itself.
func (p *pubKey) verifySignature(data, sigBlob []byte) bool {
	b := newBuffer(sigBlob)
	sigAlgo := b.getStringStr()
	sig := b.getString()
	return p.verifyWithAlgo(data, sigAlgo, sig, nil)
}

// verifyWithAlgo: for SK keys the signature has additional structure;
// sig here is the inner signature string content.
func (p *pubKey) verifyWithAlgo(data []byte, sigAlgo string, sig []byte, sessionID []byte) bool {
	if p.isSK {
		return p.verifySK(data, sigAlgo, sig)
	}
	switch p.typ {
	case keyEd25519:
		if sigAlgo != "ssh-ed25519" {
			return false
		}
		if len(sig) != ed25519.SignatureSize {
			return false
		}
		return ed25519.Verify(ed25519.PublicKey(p.edPub), data, sig)
	case keyRSA:
		if sigAlgo != "rsa-sha2-256" {
			return false
		}
		h := sha256.Sum256(data)
		pub := &rsa.PublicKey{N: p.rsaN, E: int(p.rsaE.Int64())}
		return rsa.VerifyPKCS1v15(pub, crypto.SHA256, h[:], sig) == nil
	case keyECDSA256, keyECDSA384, keyECDSA521:
		if sigAlgo != keyTypeNames[p.typ] {
			return false
		}
		// inner: mpint r, mpint s
		ib := newBuffer(sig)
		r, ok1 := ib.getMpint()
		s, ok2 := ib.getMpint()
		if !ok1 || !ok2 {
			return false
		}
		_, hh := hashForAlgoForECDSA(p.typ)
		hh.Write(data)
		pub := &ecdsa.PublicKey{Curve: p.ecCurve, X: p.ecX, Y: p.ecY}
		return ecdsa.Verify(pub, hh.Sum(nil), r, s)
	}
	return false
}

func (p *pubKey) verifySK(data []byte, sigAlgo string, sig []byte) bool {
	// SK signature format: string algo is already stripped by caller path;
	// Here sig is signature blob content which for SK is:
	//   raw signature bytes (for ed25519: 64) or (mpint r, mpint s) for ecdsa,
	// but the SSH wire signature field for SK keys contains a substructure:
	//   string signature, byte flags, uint32 counter
	// Our caller in auth.go handles the SK substructure explicitly, so this
	// fallback simply fails.
	return false
}

// ---------- host key file loading / generation ----------

type loadResult struct {
	key    *hostKey
	typ    int // identified key type, keyNone if unknown
	ok     bool
}

// loadHostkeyFile reads one dropbear-format private key file.
// Non-fatal failures return ok=false. Malformed buffers may panic
// with fatalError like the original's dropbear_exit from buf helpers.
func loadHostkeyFile(path string) loadResult {
	data, err := os.ReadFile(path)
	if err != nil {
		return loadResult{}
	}
	b := newBuffer(data)
	typName := b.getStringStr()
	typ := keyTypeFromName(typName)
	if typ == keyNone {
		return loadResult{}
	}
	switch typ {
	case keyEd25519:
		// Reads the length first (fatal if <4 bytes remain), then
		// validates it without a fatal buffer read.
		l := b.getUint32()
		if l != 64 || b.remaining() < 64 {
			return loadResult{typ: typ}
		}
		priv := b.getPtr(64)
		k := &hostKey{typ: typ, edPriv: ed25519.PrivateKey(append([]byte(nil), priv...))}
		return loadResult{key: k, typ: typ, ok: true}
	case keyRSA:
		e, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		n, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		if n.BitLen() < 1024 {
			dbLog("RSA key too short")
			return loadResult{typ: typ}
		}
		d, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		k := &hostKey{typ: typ, rsaE: e, rsaN: n, rsaD: d}
		if b.remaining() > 0 {
			p, ok1 := b.getMpint()
			q, ok2 := b.getMpint()
			if ok1 && ok2 {
				k.rsaP, k.rsaQ = p, q
			}
		}
		return loadResult{key: k, typ: typ, ok: true}
	case keyECDSA256, keyECDSA384, keyECDSA521:
		curveStr := b.getStringStr()
		if curveStr != curveName(typ) {
			return loadResult{typ: typ}
		}
		q := b.getString()
		if len(q) == 0 {
			fatalf("Bad buf_getbyte")
		}
		c := curveFor(typ)
		x, y := elliptic.Unmarshal(c, q)
		if x == nil {
			return loadResult{typ: typ}
		}
		priv, ok := b.getMpint()
		if !ok {
			return loadResult{typ: typ}
		}
		k := &hostKey{typ: typ, ecQ: append([]byte(nil), q...), ecPriv: &ecdsa.PrivateKey{
			PublicKey: ecdsa.PublicKey{Curve: c, X: x, Y: y}, D: priv,
		}}
		return loadResult{key: k, typ: typ, ok: true}
	}
	return loadResult{}
}

// encodeHostkey serialises a host key in dropbear private format.
func encodeHostkey(k *hostKey) []byte {
	var out []byte
	switch k.typ {
	case keyEd25519:
		out = appendString(out, []byte("ssh-ed25519"))
		out = appendString(out, []byte(k.edPriv))
	case keyRSA:
		out = appendString(out, []byte("ssh-rsa"))
		out = appendMpint(out, k.rsaE)
		out = appendMpint(out, k.rsaN)
		out = appendMpint(out, k.rsaD)
		out = appendMpint(out, k.rsaP)
		out = appendMpint(out, k.rsaQ)
	case keyECDSA256, keyECDSA384, keyECDSA521:
		out = appendString(out, []byte(keyTypeNames[k.typ]))
		out = appendString(out, []byte(curveName(k.typ)))
		out = appendString(out, k.ecQ)
		out = appendMpint(out, k.ecPriv.D)
	}
	return out
}

func generateHostkey(typ int) (*hostKey, error) {
	switch typ {
	case keyEd25519:
		_, priv, err := ed25519.GenerateKey(rand.Reader)
		if err != nil {
			return nil, err
		}
		return &hostKey{typ: typ, edPriv: priv}, nil
	case keyRSA:
		priv, err := rsa.GenerateKey(rand.Reader, 2048)
		if err != nil {
			return nil, err
		}
		return &hostKey{typ: typ, rsaE: big.NewInt(int64(priv.E)), rsaN: priv.N, rsaD: priv.D, rsaP: priv.Primes[0], rsaQ: priv.Primes[1]}, nil
	case keyECDSA256, keyECDSA384, keyECDSA521:
		c := curveFor(typ)
		priv, err := ecdsa.GenerateKey(c, rand.Reader)
		if err != nil {
			return nil, err
		}
		q := elliptic.Marshal(c, priv.X, priv.Y)
		return &hostKey{typ: typ, ecPriv: priv, ecQ: q}, nil
	}
	return nil, fmt.Errorf("unknown type")
}

// checkBytesEqual compares two blobs.
func checkBytesEqual(a, b []byte) bool { return bytes.Equal(a, b) }
