func parseUint32Str(s string) (uint32, bool) {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\v' || s[i] == '\f' || s[i] == '\r') {
		i++
	}
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	if i >= len(s) || s[i] < '0' || s[i] > '9' {
		return 0, false
	}
	var val uint64
	overflow := false
	for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
		d := uint64(s[i] - '0')
		if val > (^uint64(0)-d)/10 {
			overflow = true
			val = ^uint64(0)
		} else {
			val = val*10 + d
		}
	}
	if i != len(s) {
		return 0, false
	}
	if overflow {
		return 0, false
	}
	res := val
	if neg {
		res = ^val + 1
	}
	if res > 4294967295 {
		return 0, false
	}
	return uint32(res), true
}

func parseFD2Str(s string) (int, bool) {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\v' || s[i] == '\f' || s[i] == '\r') {
		i++
	}
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	if i >= len(s) || s[i] < '0' || s[i] > '9' {
		return 0, false
	}
	var val int64
	overflow := false
	for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
		d := int64(s[i] - '0')
		if val > (1<<62) {
			overflow = true
		} else {
			val = val*10 + d
		}
	}
	if i != len(s) || overflow {
		return 0, false
	}
	if neg {
		val = -val
	}
	if val < 0 || val > 2147483647 {
		return 0, false
	}
	return int(val), true
}

func selfSegfault() {
	// Reproduce crashes of the original for two specific inputs.
	syscall.Kill(syscall.Getpid(), syscall.SIGSEGV)
	select {}
}

func parsePortSpec(spec string) portSpec {
	if spec == "" || spec == "[]" {
		selfSegfault()
	}
	if spec[0] == '[' {
		idx := strings.Index(spec, "]")
		if idx < 0 {
			dbLog("Bad address '%s'", spec)
			fatalf("Bad -p argument")
		}
		if idx == len(spec)-1 {
			// [port]
			return portSpec{addr: "", port: spec[1:idx]}
		}
		if spec[idx+1] != ':' {
			dbLog("Bad address '%s'", spec)
			fatalf("Bad -p argument")
		}
		port := spec[idx+2:]
		if port == "" {
			fatalf("Bad port")
		}
		return portSpec{addr: spec[1:idx], port: port}
	}
	if strings.Contains(spec, ":") {
		last := strings.LastIndex(spec, ":")
		port := spec[last+1:]
		if port == "" {
			fatalf("Bad port")
		}
		return portSpec{addr: spec[:last], port: port}
	}
	return portSpec{addr: "", port: spec}
}

type rawOptions struct {
	opts          *serverOptions
	bannerArg     *string
	recvWindowArg *string
	maxTriesArg   *string
	keepaliveArg  *string
	idleArg       *string
	fd2Arg        *string
}

// parseOptions performs argv parsing. When quiet is true (internal
// re-exec children), post-processing log lines are suppressed.
func parseOptions(quiet bool) *serverOptions {
	o := &serverOptions{
		pidFile:    "/var/run/dropbear.pid",
		recvWindow: 24576,
		hostkeys:   make(map[int]*hostKey),
	}
	raw := &rawOptions{opts: o}
	if v, ok := os.LookupEnv("LANG"); ok {
		o.langVal = v
		o.langSet = true
	}
	maxAuth := uint32(10)
	o.maxAuthTries = maxAuth

	args := os.Args[1:]
	getStr := func(p *string) func(string) {
		return func(s string) { v := s; *p = &v }
		_ = getStr
	}
	_ = getStr

	setStr := func(dst **string, s string) {
		v := s
		*dst = &v
	}

	i := 0
	for i < len(args) {
		tok := args[i]
		i++
		if len(tok) == 0 || tok == "-" || tok[0] != '-' {
			fatalf("Invalid argument: %s", tok)
		}
		// tok starts with '-'; process option characters.
		j := 1
		for j < len(tok) {
			ch := tok[j]
			// Options taking an argument.
			isArgOpt := strings.IndexByte("brdc pPGDlW KIT2", ch) >= 0 && strings.IndexByte("brdcpPGDlWKIT2", ch) >= 0
			// (the string above avoids a confusing literal; compute plainly)
			switch ch {
			case 'b', 'r', 'd', 'c', 'p', 'P', 'G', 'D', 'l', 'W', 'K', 'I', 'T', '2':
				isArgOpt = true
			default:
				isArgOpt = false
			}
			if isArgOpt {
				var val string
				if j+1 < len(tok) {
					val = tok[j+1:]
					j = len(tok)
				} else {
					if i >= len(args) {
						fatalf("Missing argument")
					}
					val = args[i]
					i++
					j = len(tok)
				}
				switch ch {
				case 'b':
					setStr(&raw.bannerArg, val)
					setStr(&o.bannerFile, val)
				case 'r', 'd':
					o.hostkeyFiles = append(o.hostkeyFiles, val)
				case 'c':
					setStr(&o.forcedCmd, val)
				case 'p':
					if len(o.portsRaw) < 10 {
						o.portsRaw = append(o.portsRaw, val)
					}
				case 'P':
					o.pidFile = val
				case 'G':
					setStr(&o.groupName, val)
				case 'D':
					setStr(&o.authDir, val)
				case 'l':
					setStr(&o.ifaceName, val)
				case 'W':
					setStr(&raw.recvWindowArg, val)
				case 'K':
					setStr(&raw.keepaliveArg, val)
				case 'I':
					setStr(&raw.idleArg, val)
				case 'T':
					setStr(&raw.maxTriesArg, val)
				case '2':
					setStr(&raw.fd2Arg, val)
				}
				continue
			}
			switch ch {
			case 'h':
				printUsage()
				os.Exit(0)
			case 'V':
				fmt.Fprintf(os.Stderr, "Dropbear v%s\n", versionStr)
				os.Exit(0)
			case 'R':
				o.createKeys = true
			case 'F':
				o.foreground = true
			case 'e':
				o.passEnv = true
			case 'm':
				o.noMotd = true
			case 'w':
				o.noRootLogin = true
			case 's':
				o.disablePass = true
			case 'g':
				o.disableRootPw = true
			case 'B':
				o.blankPass = true
			case 't':
				o.twoFactor = true
			case 'j':
				o.disableLocal = true
			case 'k':
				o.disableRemote = true
			case 'a':
				o.allowAnyHost = true
			case 'i':
				o.inetd = true
			case 'z':
				o.disableQoS = true
			case 'u':
				// accepted, no effect in this build
			default:
				fmt.Fprintf(os.Stderr, "Invalid option -%c\n", ch)
				printUsage()
				os.Exit(1)
			}
			j++
		}
	}

	postProcessOptions(o, raw, quiet)
	return o
}

func postProcessOptions(o *serverOptions, raw *rawOptions, quiet bool) {
	log := func(format string, a ...interface{}) {
		if !quiet {
			dbLog(format, a...)
		}
	}
	// 1. ports validation
	for _, rawSpec := range o.portsRaw {
		if rawSpec == "" || rawSpec == "[]" {
			selfSegfault()
		}
		// parsePortSpec may log Bad address regardless of quiet in the
		// original initial process; in children this was already done.
		if quiet {
			// parse without logging by temporarily discarding? parsePortSpec
			// only logs on bad address which cannot happen here (validated).
		}
		o.ports = append(o.ports, parsePortSpec(rawSpec))
	}
	// 2. banner
	if raw.bannerArg != nil {
		path := *raw.bannerArg
		info, err := os.Stat(path)
		if err != nil {
			log("Error opening banner file '%s'", path)
		} else if info.Size() > 2050 {
			log("Banner file too large, max is 2050 bytes")
		} else {
			data, err := os.ReadFile(path)
			if err != nil {
				log("Error reading banner file '%s'", path)
			} else {
				o.banner = data
			}
		}
	}
	// 3. group
	if o.groupName != nil {
		g := lookupGroup(*o.groupName)
		if g == nil {
			fatalf("Cannot restrict logins to group '%s' as the group does not exist", *o.groupName)
		}
		o.groupID = g.GID
	}
	// 4. recv window
	if raw.recvWindowArg != nil {
		v, ok := parseUint32Str(*raw.recvWindowArg)
		if !ok || v == 0 {
			o.recvWindow = 24576
			log("Bad recv window '%s', using 24576", *raw.recvWindowArg)
		} else if v > 10485760 {
			o.recvWindow = 10485760
			log("Bad recv window '%s', using 10485760", *raw.recvWindowArg)
		} else {
			o.recvWindow = v
		}
	}
	// 5. max auth tries
	if raw.maxTriesArg != nil {
		v, ok := parseUint32Str(*raw.maxTriesArg)
		if !ok {
			fatalf("Bad maxauthtries '%s'", *raw.maxTriesArg)
		}
		o.maxAuthTries = v
	}
	// 6. keepalive
	if raw.keepaliveArg != nil {
		v, ok := parseUint32Str(*raw.keepaliveArg)
		if !ok {
			fatalf("Bad keepalive '%s'", *raw.keepaliveArg)
		}
		o.keepalive = v
	}
	// 7. idle timeout
	if raw.idleArg != nil {
		v, ok := parseUint32Str(*raw.idleArg)
		if !ok {
			fatalf("Bad idle_timeout '%s'", *raw.idleArg)
		}
		o.idleTimeout = v
	}
	// 8. forced command
	if o.forcedCmd != nil {
		log("Forced command set to '%s'", *o.forcedCmd)
	}
	// 9. interface
	if o.ifaceName != nil {
		log("Binding to interface '%s'", *o.ifaceName)
	}
	// 10. -2
	if raw.fd2Arg != nil {
		v, ok := parseFD2Str(*raw.fd2Arg)
		if !ok {
			fatalf("Bad -2")
		}
		o.fd2 = v
		o.mode2 = true
		o.inetd = true
	}
	// 11. -t/-s incompatibility
	if o.twoFactor && o.disablePass {
		fatalf("-t and -s are incompatible")
	}
	// 12. -D
	if o.authDir != nil && *o.authDir == "" {
		fatalf("Bad -D")
	}
}

var defaultHostkeyFiles = []string{
