func parseUint32Str(s string) (uint32, bool) {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\v' || s[i] == '\f' || s[i] == '\r') {
		i++
	}
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		neg = s[i] == '-'
		i++
	}
	if i >= len(s) || s[i] < '0' || s[i] > '9' {
		return 0, false
	}
	var val uint64
	overflow := false
	for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
		d := uint64(s[i] - '0')
		if val > (^uint64(0)-d)/10 {
			overflow = true
			val = ^uint64(0)
		} else {
			val = val*10 + d
		}
	}
	if i != len(s) {
		return 0, false
	}
	if overflow {
		return 0, false
	}
	res := val
	if neg {
		res = ^val + 1
	}
	if res > 4294967295 {
		return 0, false
	}
	return uint32(res), true
}

func parseFD2Str(s string) (int, bool) {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\v' || s[i] == '\f' || s[i] == '\r') {
		i++
	}
	neg := false
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
