	overflow := false
	for ; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
		d := int64(s[i] - '0')
		if val > (1<<62) {
			overflow = true
		} else {
			val = val*10 + d
		}
	}
	if i != len(s) || overflow {
		return 0, false
	}
	if neg {
		val = -val
	}
	if val < 0 || val > 2147483647 {
