package main

import (
	"fmt"
	"net"
	"os"
	"os/exec"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
)

const (
	envReexec = "_DROPBEAR_REEXEC_MODE"
)

var (
	procIsMainListener bool
	pidfileAttempted   bool
	pidfilePath        string
)

func main() {
	os.Exit(run())
}

func run() (code int) {
	signal.Ignore(syscall.SIGQUIT)
	mode := os.Getenv(envReexec)
	os.Unsetenv(envReexec)

	switch {
	case strings.HasPrefix(mode, "daemon:"):
		return runDaemonChild(mode)
	case mode == "connchild":
		return runConnectionChild()
	case mode == "session":
		return runSessionRunner()
	default:
		return runInitial()
	}
}

// earlyExitHandler recovers fatalError panics for the initial/main process.
func earlyExitHandler(code *int) {
	if r := recover(); r != nil {
		if fe, ok := r.(*fatalError); ok {
			dbLog("Early exit: %s", fe.msg)
			if procIsMainListener && pidfileAttempted {
				os.Remove(pidfilePath)
			}
			*code = 1
			return
		}
		panic(r)
	}
}

func runInitial() (code int) {
	defer earlyExitHandler(&code)
	opts := parseOptions(false)

	if opts.inetd {
		return runInetd(opts)
	}

	opts.loadAllHostkeys(false)
	listeners := setupListeners(opts)
	if len(listeners) == 0 {
		fatalf("No listening ports available.")
	}

	if !opts.foreground {
		// Spawn the daemon child, passing listener FDs.
		if err := spawnDaemon(listeners); err != nil {
			for _, l := range listeners {
				l.Close()
			}
			fatalf("%s", err.Error())
		}
		for _, l := range listeners {
			l.Close()
		}
		return 0
	}

	procIsMainListener = true
	pidfilePath = opts.pidFile
	dbLog("Not backgrounding")
	writePidfile(opts)
	return acceptLoop(opts, listeners)
}

func writePidfile(opts *serverOptions) {
	pidfileAttempted = true
	pidfilePath = opts.pidFile
	// Silent on failure, matching the original.
	_ = os.WriteFile(opts.pidFile, []byte(fmt.Sprintf("%d\n", os.Getpid())), 0644)
}

func setupListeners(opts *serverOptions) []net.Listener {
	specs := opts.ports
	if len(specs) == 0 {
		specs = []portSpec{{addr: "", port: "22"}}
	}
	var listeners []net.Listener
	for _, spec := range specs {
		addrs, err := resolveAddrInfo(spec.addr, spec.port, true)
		if err != nil {
			dbLog("Failed listening on '%s': Error resolving: %s", spec.port, gaiErrorString(err))
			continue
		}
		succeeded := false
		var lastErr error
		for _, a := range addrs {
			l, berr := bindOne(opts, a)
			if berr != nil {
				lastErr = berr
				continue
			}
			listeners = append(listeners, l)
			succeeded = true
		}
		if !succeeded {
			dbLog("Failed listening on '%s': Error listening: %s", spec.port, strerror(lastErr))
		}
	}
	return listeners
}

func bindOne(opts *serverOptions, a resolvedAddr) (net.Listener, error) {
	const AF_INET = 2
	const AF_INET6 = 10
	var family int
	var sa syscall.Sockaddr
	ip := net.ParseIP(a.IP)
	if a.Family == AF_INET6 {
		family = syscall.AF_INET6
		var addr [16]byte
		copy(addr[:], ip.To16())
		sa = &syscall.SockaddrInet6{Port: a.Port, Addr: addr}
	} else {
		family = syscall.AF_INET
		var addr [4]byte
		copy(addr[:], ip.To4())
		sa = &syscall.SockaddrInet4{Port: a.Port, Addr: addr}
	}
	fd, err := syscall.Socket(family, syscall.SOCK_STREAM, syscall.IPPROTO_TCP)
	if err != nil {
		return nil, err
	}
	syscall.SetsockoptInt(fd, syscall.SOL_SOCKET, syscall.SO_REUSEADDR, 1)
	if family == syscall.AF_INET6 {
		syscall.SetsockoptInt(fd, syscall.IPPROTO_IPV6, syscall.IPV6_V6ONLY, 1)
	}
	if opts.ifaceName != nil {
		if err := syscall.SetsockoptString(fd, syscall.SOL_SOCKET, 25 /*SO_BINDTODEVICE*/, *opts.ifaceName); err != nil {
			dbLog("Couldn't set SO_BINDTODEVICE")
		}
	}
	if err := syscall.Bind(fd, sa); err != nil {
		syscall.Close(fd)
		return nil, err
	}
	if err := syscall.Listen(fd, 128); err != nil {
		syscall.Close(fd)
		return nil, err
	}
	f := os.NewFile(uintptr(fd), "listener")
	l, err := net.FileListener(f)
	f.Close()
	if err != nil {
		return nil, err
	}
	return l, nil
}

func selfExe() string {
	exe, err := os.Executable()
	if err != nil {
		return os.Args[0]
	}
	return exe
}

func spawnDaemon(listeners []net.Listener) error {
	readyR, readyW, err := os.Pipe()
	if err != nil {
		return err
	}
	defer readyR.Close()
	var files []*os.File
	for _, l := range listeners {
		if tl, ok := l.(*net.TCPListener); ok {
			f, err := tl.File()
			if err != nil {
				readyW.Close()
				return err
			}
			defer f.Close()
			files = append(files, f)
		} else {
			readyW.Close()
			return fmt.Errorf("unexpected listener type")
		}
	}
	files = append(files, readyW)
	cmd := exec.Command(selfExe(), os.Args[1:]...)
	cmd.Args[0] = os.Args[0]
	cmd.Env = append(os.Environ(), envReexec+"=daemon:"+strconv.Itoa(len(listeners)))
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.ExtraFiles = files
	cmd.SysprocAttr = &syscall.SysprocAttr{Setsid: true}
	if err := cmd.Start(); err != nil {
		readyW.Close()
		return err
	}
	readyW.Close()
	buf := make([]byte, 1)
	n, _ := readyR.Read(buf)
	if n == 1 && buf[0] == 'R' {
		return nil
	}
	// Child failed; reap it to get its exit code.
	cmd.Wait()
	return fmt.Errorf("daemon failed to start")
}

func runDaemonChild(mode string) (code int) {
	defer earlyExitHandler(&code)
	n, _ := strconv.Atoi(strings.TrimPrefix(mode, "daemon:"))
	// Extra files: listeners at fd 3..3+n-1, ready pipe at fd 3+n.
	opts := parseOptions(true)
	var listeners []net.Listener
	for i := 0; i < n; i++ {
		f := os.NewFile(uintptr(3+i), "listener")
		l, err := net.FileListener(f)
		f.Close()
		if err == nil {
			listeners = append(listeners, l)
		}
	}
	readyFd := 3 + n
	os.Chdir("/")
	procIsMainListener = true
	pidfilePath = opts.pidFile
	dbLog("Running in background")
	writePidfile(opts)
	// Notify the parent.
	syscall.Write(readyFd, []byte{'R'})
	syscall.Close(readyFd)
	return acceptLoop(opts, listeners)
}

func acceptLoop(opts *serverOptions, listeners []net.Listener) int {
	sigCh := make(chan os.Signal, 4)
	signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
	defer signal.Stop(sigCh)

	type accepted struct{ conn net.Conn }
	acceptCh := make(chan accepted, 64)
	for _, l := range listeners {
		go func(l net.Listener) {
			for {
				c, err := l.Accept()
				if err != nil {
					return
				}
				acceptCh <- accepted{c}
			}
		}(l)
	}
	unauthDone := make(chan struct{}, 64)
	unauthCount := 0

	for {
		select {
		case <-sigCh:
			for _, l := range listeners {
				l.Close()
			}
			dbLog("Early exit: Terminated by signal")
			if pidfileAttempted {
				os.Remove(pidfilePath)
			}
			return 0
		case <-unauthDone:
			if unauthCount > 0 {
				unauthCount--
			}
		case ac := <-acceptCh:
			if unauthCount >= 5 {
				ac.conn.Close()
				continue
			}
			unauthCount++
			if err := spawnConnectionChild(ac.conn, unauthDone); err != nil {
				ac.conn.Close()
				if unauthCount > 0 {
					unauthCount--
				}
			}
		}
	}
}

func spawnConnectionChild(conn net.Conn, unauthDone chan<- struct{}) error {
	tcpConn, ok := conn.(*net.TCPConn)
	if !ok {
		return fmt.Errorf("not tcp")
	}
	connFile, err := tcpConn.File()
	if err != nil {
		return err
	}
	defer connFile.Close()
	// File() makes the dup blocking; close the original now that we have a dup
	// for the child (child gets another dup via ExtraFiles).
	rPipe, wPipe, err := os.Pipe()
	if err != nil {
		return err
	}
	defer wPipe.Close()
	cmd := exec.Command(selfExe(), os.Args[1:]...)
	cmd.Args[0] = os.Args[0]
	cmd.Env = append(os.Environ(), envReexec+"=connchild")
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.ExtraFiles = []*os.File{connFile, wPipe}
	cmd.SysprocAttr = &syscall.SysprocAttr{Setsid: true}
	if err := cmd.Start(); err != nil {
		rPipe.Close()
		return err
	}
	conn.Close()
	// Monitor unauth pipe: EOF means authenticated or exited.
	go func() {
		buf := make([]byte, 16)
		for {
			_, err := rPipe.Read(buf)
			if err != nil {
				break
			}
		}
		rPipe.Close()
		unauthDone <- struct{}{}
	}()
	go cmd.Wait()
	return nil
}

func runConnectionChild() int {
	opts := parseOptions(true)
	f := os.NewFile(3, "conn")
	conn, err := net.FileConn(f)
	f.Close()
	if err != nil {
		return 1
	}
	unauthFile := os.NewFile(4, "unauth")
	return serveConnection(opts, conn, unauthFile, true)
}

func runInetd(opts *serverOptions) int {
	// Load host keys first (logs/fatals as in the initial process).
	opts.loadAllHostkeys(false)
	// stdin must be a socket.
	conn, err := socketFromFD0()
	if err != nil {
		fatalf("Failed socket address: %s", strerror(err))
	}
	return serveConnection(opts, conn, nil, !opts.mode2)
}

func socketFromFD0() (net.Conn, error) {
	// Validate fd 0 is a socket by asking for its peer address.
	if _, err := syscall.Getpeername(0); err != nil {
		return nil, err
	}
	if _, err := syscall.Getsockname(0); err != nil {
		return nil, err
	}
	f := os.NewFile(0, "inetd")
	conn, err := net.FileConn(f)
	if err != nil {
		// FileConn dups the fd; keep using f-based conn if possible.
		return nil, err
	}
	// net.FileConn duplicates the descriptor, so fd 0 can remain; but
	// subsequent session children expect stdin to be the shell's stdin,
	// which is set up separately with pipes/ptys.
	return conn, nil
}
