{"command":"cat > transport.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"compress/zlib"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"io"
	"net"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

var errCleanEOF = errors.New("clean eof")

// cryptState for one direction.
type cryptState struct {
	cipherName string
	macName    string
	stream     cipher.Stream // AES-CTR or identity; nil for chacha
	macKey     []byte
	key        []byte // chacha 64-byte key
	blockSize  int
	aead       bool
}

type identityStream struct{}

func (identityStream) XORKeyStream(dst, src []byte) { copy(dst, src) }

func plainCryptState() *cryptState {
	return &cryptState{cipherName: "none", stream: identityStream{}, blockSize: 8}
}

type packetConn struct {
	conn net.Conn
	r    *bufio.Reader

	wmu     sync.Mutex // protects writes and writeState/seq
	rState  *cryptState
	wState  *cryptState
	recvSeq uint32
	sendSeq uint32

	// compression (outbound = server->client, inbound = client->server)
	compOutName string
	compInName  string
	compOutOn   bool
	compInOn    bool
	zlibW       *zlib.Writer
	zlibWBuf    *bytes.Buffer
	zlibR       io.ReadCloser
	zlibRBuf    *bytes.Buffer // feeds compressed chunks to zlibR

	writeErr atomic.Value // string

	lastDataNano   atomic.Int64
	lastAnyRecv    atomic.Int64
	lastKeepalive  atomic.Int64
	onDataActivity func()
}

func newPacketConn(conn net.Conn) *packetConn {
	p := &packetConn{
		conn:   conn,
		r:      bufio.NewReaderSize(conn, 4096),
		rState: plainCryptState(),
		wState: plainCryptState(),
	}
	p.lastAnyRecv.Store(time.Now().UnixNano())
	p.lastDataNano.Store(time.Now().UnixNano())
	return p
}

func (p *packetConn) noteDataActivity() {
	p.lastDataNano.Store(time.Now().UnixNano())
	if p.onDataActivity != nil {
		p.onDataActivity()
	}
}

func readErrToFatal(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
		return errCleanEOF
	}
	// Connection reset etc.
	return &fatalError{msg: "Error reading: " + strerror(err)}
}

func (p *packetConn) readFull(b []byte) error {
	_, err := io.ReadFull(p.r, b)
	if err != nil {
		return readErrToFatal(err)
	}
	return nil
}

// readPacket reads one SSH packet, returning its payload. Fatal
// protocol errors panic with *fatalError; clean EOF returns errCleanEOF.
func (p *packetConn) readPacket() ([]byte, error) {
	if p.rState.aead {
		return p.readPacketChaCha()
	}
	return p.readPacketStream()
}

func (p *packetConn) readPacketStream() ([]byte, error) {
	bs := p.rState.blockSize
	if bs <= 0 {
		bs = 8
	}
	first := make([]byte, bs)
	if err := p.readFull(first); err != nil {
		return nil, err
	}
	p.rState.stream.XORKeyStream(first, first)
	packetLen := binary.BigEndian.Uint32(first[:4])
	total := packetLen + 4 // wraps like C uint32 arithmetic in message
	if total%uint32(bs) != 0 || total > 35000 {
		fatalf("Integrity error (bad packet size %d)", total)
	}
	// total is at least bs (alignment and <35000 check would have caught
	// small misaligned values, but e.g. packetLen=0 => total=4 %8 !=0)
	if int(total) < bs {
		fatalf("Integrity error (bad packet size %d)", total)
	}
	rest := make([]byte, int(total)-bs)
	if err := p.readFull(rest); err != nil {
		return nil, err
	}
	p.rState.stream.XORKeyStream(rest, rest)
	plain := append(first, rest...)

	if len(p.rState.macKey) > 0 {
		mac := make([]byte, 32)
		if err := p.readFull(mac); err != nil {
			return nil, err
		}
		m := hmac.New(sha256.New, p.rState.macKey)
		var seqB [4]byte
		binary.BigEndian.PutUint32(seqB[:], p.recvSeq)
		m.Write(seqB[:])
		m.Write(plain)
		if !hmac.Equal(m.Sum(nil), mac) {
			fatalf("Integrity error")
		}
	}
	p.recvSeq++
	return p.extractPayload(plain, packetLen)
}

func (p *packetConn) readPacketChaCha() ([]byte, error) {
	encLen := make([]byte, 4)
	if err := p.readFull(encLen); err != nil {
		return nil, err
	}
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint32(nonce[8:], p.recvSeq)
	lenCipher := newChaCha20(p.rState.key[32:], nonce, 0)
	lenBytes := make([]byte, 4)
	lenCipher.XORKeyStream(lenBytes, encLen)
	packetLen := binary.BigEndian.Uint32(lenBytes)
	total := packetLen + 4
	if total%8 != 0 || total > 35000 {
		fatalf("Integrity error (bad packet size %d)", total)
	}
	content := make([]byte, int(packetLen))
	if err := p.readFull(content); err != nil {
		return nil, err
	}
	tag := make([]byte, 16)
	if err := p.readFull(tag); err != nil {
		return nil, err
	}
	contentCipher := newChaCha20(p.rState.key[:32], nonce, 0)
	var polyKey [32]byte
	contentCipher.XORKeyStream(polyKey[:], polyKey[:])
	discard := make([]byte, 32)
	contentCipher.XORKeyStream(discard, discard)
	// Verify tag over encrypted length + encrypted content.
	tagData := append(append([]byte{}, encLen...), content...)
	var tagArr [16]byte
	copy(tagArr[:], tag)
	if !poly1305Verify(&tagArr, tagData, &polyKey) {
		fatalf("Integrity error")
	}
	contentCipher.XORKeyStream(content, content)
	p.recvSeq++
	plain := append(lenBytes, content...)
	return p.extractPayload(plain, packetLen)
}

func (p *packetConn) extractPayload(plain []byte, packetLen uint32) ([]byte, error) {
	if len(plain) < 5 {
		fatalf("Bad packet size %d", uint32(int32(packetLen)-1))
	}
	padLen := int(plain[4])
	payloadLen := int(int32(packetLen) - int32(padLen) - 1)
	if payloadLen <= 0 {
		fatalf("Bad packet size %d", uint32(int32(payloadLen)))
	}
	if 5+payloadLen > len(plain) {
		fatalf("Bad packet size %d", uint32(int32(payloadLen)))
	}
	payload := plain[5 : 5+payloadLen]
	p.lastAnyRecv.Store(time.Now().UnixNano())
	// Inbound compression (not negotiated by our server lists for
	// client->server, but handle "zlib" if it ever is).
	if p.compInOn && p.zlibR != nil {
		p.zlibRBuf.Write(payload)
		out, err := io.ReadAll(p.zlibR)
		if err != nil {
			fatalf("zlib error")
		}
		// Recreate reader over updated buffer for next chunk: zlib
		// stream readers in Go can't be re-fed easily; we instead
		// use a resettable approach below in practice because
		// compInOn is never true for this server.
		payload = out
	}
	return payload, nil
}

// writePacket encrypts and writes one packet. It can be called from
// multiple goroutines.
func (p *packetConn) writePacket(payload []byte) error {
	p.wmu.Lock()
	defer p.wmu.Unlock()
	return p.writePacketLocked(payload)
}

func (p *packetConn) writePacketLocked(payload []byte) error {
	if len(payload) > 0 {
		switch payload[0] {
		case 80: // global request (keepalive): not data activity
		default:
			p.noteDataActivity()
		}
	}
	data := payload
	if p.compOutOn && p.zlibW != nil {
		p.zlibWBuf.Reset()
		p.zlibW.Write(payload)
		p.zlibW.Flush()
		data = append([]byte(nil), p.zlibWBuf.Bytes()...)
	}
	var packet []byte
	if p.wState.aead {
		packet = p.buildChaChaPacket(data)
	} else {
		packet = p.buildStreamPacket(data)
	}
	_, err := p.conn.Write(packet)
	if err != nil {
		p.writeErr.Store("Error writing: " + strerror(err))
		return err
	}
	p.sendSeq++
	return nil
}

func (p *packetConn) buildStreamPacket(payload []byte) []byte {
	bs := p.wState.blockSize
	if bs <= 0 {
		bs = 8
	}
	padLen := bs - ((5 + len(payload)) % bs)
	if padLen < 4 {
		padLen += bs
	}
	packetLen := 1 + len(payload) + padLen
	plain := make([]byte, 4+packetLen)
	binary.BigEndian.PutUint32(plain, uint32(packetLen))
	plain[4] = byte(padLen)
	copy(plain[5:], payload)
	io.ReadFull(rand.Reader, plain[5+len(payload):])
	var mac []byte
	if len(p.wState.macKey) > 0 {
		m := hmac.New(sha256.New, p.wState.macKey)
		var seqB [4]byte
		binary.BigEndian.PutUint32(seqB[:], p.sendSeq)
		m.Write(seqB[:])
		m.Write(plain)
		mac = m.Sum(nil)
	}
	enc := make([]byte, len(plain))
	p.wState.stream.XORKeyStream(enc, plain)
	return append(enc, mac...)
}

func (p *packetConn) buildChaChaPacket(payload []byte) []byte {
	const bs = 8
	padLen := bs - ((5 + len(payload)) % bs)
	if padLen < 4 {
		padLen += bs
	}
	packetLen := 1 + len(payload) + padLen
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint32(nonce[8:], p.sendSeq)

	contentCipher := newChaCha20(p.wState.key[:32], nonce, 0)
	var polyKey [32]byte
	contentCipher.XORKeyStream(polyKey[:], polyKey[:])
	discard := make([]byte, 32)
	contentCipher.XORKeyStream(discard, discard)

	out := make([]byte, 4+packetLen+16)
	binary.BigEndian.PutUint32(out, uint32(packetLen))
	lenCipher := newChaCha20(p.wState.key[32:], nonce, 0)
	lenCipher.XORKeyStream(out[:4], out[:4])
	out[4] = byte(padLen)
	copy(out[5:], payload)
	io.ReadFull(rand.Reader, out[5+len(payload):4+packetLen])
	// Encrypt content (from padding-length byte onwards).
	contentCipher.XORKeyStream(out[4:4+packetLen], out[4:4+packetLen])
	var tag [16]byte
	poly1305Sum(&tag, out[:4+packetLen], &polyKey)
	copy(out[4+packetLen:], tag[:])
	return out
}

// ---------- key derivation / state construction ----------

func deriveKey(K, H []byte, id byte, sessionID []byte, need int, hashFunc func() hashObj) []byte {
	panic("unused")
}

type hashObj interface {
	Write([]byte) (int, error)
	Sum([]byte) []byte
}

var _ = aes.NewCipher
var _ cipher.Stream
var _ syscall.ECONNRESET
EOF
gofmt -w transport.go; ./compile.sh 2>&1 | head -n 30"}

