	macKey     []byte
	key        []byte // chacha 64-byte key
	blockSize  int
	aead       bool
}

type identityStream struct{}

func (identityStream) XORKeyStream(dst, src []byte) { copy(dst, src) }

func plainCryptState() *cryptState {
	return &cryptState{cipherName: "none", stream: identityStream{}, blockSize: 8}
}

type packetConn struct {
	conn net.Conn
	r    *bufio.Reader

	wmu     sync.Mutex // protects writes and writeState/seq
	rState  *cryptState
	wState  *cryptState
	recvSeq uint32
	sendSeq uint32

	// compression (outbound = server->client, inbound = client->server)
	compOutName string
	compInName  string
	compOutOn   bool
	compInOn    bool
	zlibW       *zlib.Writer
	zlibWBuf    *bytes.Buffer
	zlibR       io.ReadCloser
	zlibRBuf    *bytes.Buffer // feeds compressed chunks to zlibR

	writeErr atomic.Value // string

	lastDataNano   atomic.Int64
	lastAnyRecv    atomic.Int64
	lastKeepalive  atomic.Int64
	onDataActivity func()
}

func newPacketConn(conn net.Conn) *packetConn {
	p := &packetConn{
		conn:   conn,
		r:      bufio.NewReaderSize(conn, 4096),
		rState: plainCryptState(),
		wState: plainCryptState(),
	}
	p.lastAnyRecv.Store(time.Now().UnixNano())
	p.lastDataNano.Store(time.Now().UnixNano())
	return p
}

func (p *packetConn) noteDataActivity() {
	p.lastDataNano.Store(time.Now().UnixNano())
	if p.onDataActivity != nil {
		p.onDataActivity()
	}
}

func readErrToFatal(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
		return errCleanEOF
	}
	// Connection reset etc.
	return &fatalError{msg: "Error reading: " + strerror(err)}
}

func (p *packetConn) readFull(b []byte) error {
	_, err := io.ReadFull(p.r, b)
	if err != nil {
		return readErrToFatal(err)
	}
	return nil
