func (p *packetConn) readPacketStream() ([]byte, error) {
	bs := p.rState.blockSize
	if bs <= 0 {
		bs = 8
	}
	first := make([]byte, bs)
	if err := p.readFull(first); err != nil {
		return nil, err
	}
	p.rState.stream.XORKeyStream(first, first)
	packetLen := binary.BigEndian.Uint32(first[:4])
	total := packetLen + 4 // wraps like C uint32 arithmetic in message
	if total%uint32(bs) != 0 || total > 35000 {
		fatalf("Integrity error (bad packet size %d)", total)
	}
