	}
	contentCipher := newChaCha20(p.rState.key[:32], nonce, 0)
	var polyKey [32]byte
	contentCipher.XORKeyStream(polyKey[:], polyKey[:])
	discard := make([]byte, 32)
	contentCipher.XORKeyStream(discard, discard)
