		serverCipherAlgos,
		serverMACAlgos,
		serverMACAlgos,
		serverCompCS,
		serverCompSC,
		{},
		{},
	}
	for _, l := range lists {
		p = appendString(p, []byte(strings.Join(l, ",")))
	}
	p = append(p, 0)
	p = appendUint32(p, 0)
	return p
