type clientKexInit struct {
	payload        []byte
	lists          [10][]string
	firstFollows   bool
}

func parseKexInit(payload []byte) *clientKexInit {
	b := newBuffer(payload)
	b.getByte() // message type, already checked
	b.incrPos(16)
	ck := &clientKexInit{payload: payload}
	for i := 0; i < 10; i++ {
		ck.lists[i] = splitNameList(b.getStringStr())
	}
	ck.firstFollows = b.getBool()
	b.getUint32() // reserved
	return ck
}

func (s *sshConn) negotiate(ck *clientKexInit, rekey bool) *negotiatedAlgos {
	n := &negotiatedAlgos{}
	// kex (skip pseudo names in client list)
	var clientKex []string
	for _, a := range ck.lists[0] {
		if a == "ext-info-c" || a == "kex-strict-c-v00@openssh.com" || a == "kexguess2@matt.ucc.asn.au" {
			continue
		}
		clientKex = append(clientKex, a)
	}
	n.kex = findCommonAlgo(clientKex, selectableKexAlgos)
	if n.kex == "" {
		fatalf("No matching algo kex")
	}
	n.hostkeyAlgo = findCommonAlgo(ck.lists[1], s.serverHostkeyAlgos(rekey))
	if n.hostkeyAlgo == "" {
		fatalf("No matching algo hostkey")
	}
	n.encCS = findCommonAlgo(ck.lists[2], serverCipherAlgos)
	if n.encCS == "" {
		fatalf("No matching algo enc c->s")
	}
	n.encSC = findCommonAlgo(ck.lists[3], serverCipherAlgos)
	if n.encSC == "" {
		fatalf("No matching algo enc s->c")
	}
	if n.encCS != "chacha20-poly1305@openssh.com" {
		n.macCS = findCommonAlgo(ck.lists[4], serverMACAlgos)
		if n.macCS == "" {
			fatalf("No matching algo mac c->s")
		}
	}
	if n.encSC != "chacha20-poly1305@openssh.com" {
		n.macSC = findCommonAlgo(ck.lists[5], serverMACAlgos)
		if n.macSC == "" {
			fatalf("No matching algo mac s->c")
		}
	}
	n.compCS = findCommonAlgo(ck.lists[6], serverCompCS)
	if n.compCS == "" {
		fatalf("No matching algo comp c->s")
	}
	n.compSC = findCommonAlgo(ck.lists[7], serverCompSC)
	if n.compSC == "" {
		fatalf("No matching algo comp s->c")
	}
	switch n.kex {
	case "ecdh-sha2-nistp384":
		n.hashAlgo = crypto.SHA384
	case "ecdh-sha2-nistp521":
		n.hashAlgo = crypto.SHA512
	case "sntrup761x25519-sha512", "sntrup761x25519-sha512@openssh.com":
		n.hashAlgo = crypto.SHA512
	default:
		n.hashAlgo = crypto.SHA256
	}
	n.hostKey = s.resolveHostkey(n.hostkeyAlgo)
	return n
