func (s *sshConn) resolveHostkey(algo string) *hostKey {
	kt := keyTypeForHostkeyAlgo(algo)
	if k, ok := s.opts.hostkeys[kt]; ok && k != nil {
		return k
	}
	if !s.opts.createKeys {
		// Should not happen because only loaded algos were advertised.
		fatalf("No matching algo hostkey")
	}
	path, genType := defaultHostkeyPathFor(algo)
	// Try loading again (may panic on malformed files, matching original).
	res := loadHostkeyFile(path)
	if res.ok && res.typ == kt {
		s.opts.hostkeys[kt] = res.key
		return res.key
	}
	if _, err := os.Lstat(path); err == nil {
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	// Generate.
	k, err := generateHostkey(genType)
	if err != nil {
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	tmpPath := fmt.Sprintf("%s.tmp%d", path, os.Getpid())
	f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		dbLog("Couldn't create new file %s: %s", tmpPath, strerror(err))
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if _, err := f.Write(encodeHostkey(k)); err != nil {
		f.Close()
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	dbLog("Generated hostkey %s, fingerprint is SHA256:%s", path, fingerprintSHA256(k.publicBlob()))
	s.opts.hostkeys[kt] = k
	return k
}

func hashNew(h crypto.Hash) hash.Hash {
	switch h {
	case crypto.SHA384:
		return sha512.New384()
	case crypto.SHA512:
		return sha512.New()
	default:
		return sha256.New()
	}
}

func appendHashString(h hash.Hash, b []byte) {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], uint32(len(b)))
	h.Write(l[:])
	h.Write(b)
}

// Structure holding the result of a key exchange.
type kexResult struct {
	H          []byte
	Kencoded   []byte // encoded K as used in hash/key derivation input
	hashAlgo   crypto.Hash
}

// RFC 4253 group14 prime.
var dhGroup14Prime = func() *big.Int {
