		"15728E5A8AACAA68FFFFFFFFFFFFFFFF"
	p, _ := new(big.Int).SetString(pHex, 16)
	return p
}()

// performServerKex runs the algorithm-specific exchange after both
// KEXINITs are known. It returns H and encoded K.
func (s *sshConn) performServerKex(ck *clientKexInit, neg *negotiatedAlgos) *kexResult {
	// First-follows handling.
	if ck.firstFollows {
		guessKex := ""
		guessHK := ""
		if len(ck.lists[0]) > 0 {
			guessKex = ck.lists[0][0]
		}
		if len(ck.lists[1]) > 0 {
			guessHK = ck.lists[1][0]
		}
		if guessKex != neg.kex || guessHK != neg.hostkeyAlgo {
			// Discard the guessed packet.
			s.readPacketRaw()
		}
	}
	payload := s.expectPacket(30)
	b := newBuffer(payload)
	b.getByte()

	magics := func(h hash.Hash) {
		appendHashString(h, []byte(s.clientVersion))
		appendHashString(h, []byte(serverVersionString()))
		appendHashString(h, ck.payload)
		appendHashString(h, s.serverKexInit)
		appendHashString(h, neg.hostKey.publicBlob())
	}

	switch neg.kex {
	case "curve25519-sha256", "curve25519-sha256@libssh.org":
		qc := b.getString()
		if len(qc) != 32 {
			fatalf("Bad curve25519")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(qc)
		if err != nil {
			fatalf("Bad curve25519")
		}
		shared, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		qs := priv.PublicKey().Bytes()
		K := new(big.Int).SetBytes(shared)
		h := hashNew(neg.hashAlgo)
		magics(h)
		appendHashString(h, qc)
		appendHashString(h, qs)
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, qs, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "ecdh-sha2-nistp256", "ecdh-sha2-nistp384", "ecdh-sha2-nistp521":
		qc := b.getString()
		if len(qc) == 0 {
			fatalf("Bad buf_getbyte")
		}
		var curve ecdh.Curve
		var ecCurve elliptic.Curve
		switch neg.kex {
		case "ecdh-sha2-nistp256":
			curve, ecCurve = ecdh.P256(), elliptic.P256()
		case "ecdh-sha2-nistp384":
			curve, ecCurve = ecdh.P384(), elliptic.P384()
		default:
			curve, ecCurve = ecdh.P521(), elliptic.P521()
		}
		if x, _ := elliptic.Unmarshal(ecCurve, qc); x == nil {
			fatalf("ECC error")
		}
		priv, err := curve.GenerateKey(rand.Reader)
		if err != nil {
			fatalf("ECC error")
		}
		remote, err := curve.NewPublicKey(qc)
		if err != nil {
			fatalf("ECC error")
		}
		shared, err := priv.ECDH(remote)
		if err != nil {
			fatalf("ECC error")
		}
		qs := priv.PublicKey().Bytes()
		K := new(big.Int).SetBytes(shared)
		h := hashNew(neg.hashAlgo)
		magics(h)
		appendHashString(h, qc)
		appendHashString(h, qs)
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, qs, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "diffie-hellman-group14-sha256":
		e, ok := b.getMpint()
		p := dhGroup14Prime
		if !ok || e.Cmp(big.NewInt(1)) <= 0 || e.Cmp(new(big.Int).Sub(p, big.NewInt(1))) >= 0 {
			fatalf("Diffie-Hellman error")
		}
		// Generate private exponent.
		privBytes := make([]byte, 256)
		rand.Read(privBytes)
		y := new(big.Int).SetBytes(privBytes)
		y.Mod(y, new(big.Int).Sub(p, big.NewInt(3)))
		y.Add(y, big.NewInt(2))
		f := new(big.Int).Exp(big.NewInt(2), y, p)
		K := new(big.Int).Exp(e, y, p)
		h := hashNew(neg.hashAlgo)
		magics(h)
		// e and f are written as mpints (string wrapped).
		h.Write(wrapString(mpintBytes(e)))
		h.Write(wrapString(mpintBytes(f)))
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReplyDH(neg, f, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "mlkem768x25519-sha256":
		hybrid := b.getString()
		sub := newBuffer(hybrid)
		pqPart := sub.getPtr(1184)
		curvePart := sub.getPtr(32)
		if sub.remaining() != 0 {
			fatalf("Bad sntrup")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(curvePart)
		if err != nil {
			fatalf("Bad curve25519")
		}
		curveSecret, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		pqSecret, pqCiphertext := mlkemEncapsulate(pqPart)
		serverHybrid := append(append([]byte(nil), pqCiphertext...), priv.PublicKey().Bytes()...)
		kh := sha256.New()
		kh.Write(pqSecret)
		kh.Write(curveSecret)
		secret := kh.Sum(nil)
		h := sha256.New()
		magics(h)
		appendHashString(h, hybrid)
		appendHashString(h, serverHybrid)
		Kenc := wrapString(secret)
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, serverHybrid, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "sntrup761x25519-sha512", "sntrup761x25519-sha512@openssh.com":
		hybrid := b.getString()
		sub := newBuffer(hybrid)
		pqPart := sub.getPtr(1158)
		curvePart := sub.getPtr(32)
		if sub.remaining() != 0 {
			fatalf("Bad sntrup")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(curvePart)
		if err != nil {
			fatalf("Bad curve25519")
		}
		curveSecret, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		pqSecret, pqCiphertext, ok := sntrupEncapsulate(pqPart)
		if !ok {
			fatalf("Bad sntrup")
		}
		serverHybrid := append(append([]byte(nil), pqCiphertext...), priv.PublicKey().Bytes()...)
		kh := sha512.New()
		kh.Write(pqSecret)
		kh.Write(curveSecret)
		secret := kh.Sum(nil)
		h := sha512.New()
		magics(h)
		appendHashString(h, hybrid)
		appendHashString(h, serverHybrid)
		Kenc := wrapString(secret)
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, serverHybrid, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}
	}
	fatalf("No matching algo kex")
	return nil
}

func (s *sshConn) sendKexReply(neg *negotiatedAlgos, serverEphemeral []byte, H []byte) {
	sig := neg.hostKey.sign(rand.Reader, H)
	var p []byte
	p = append(p, 31)
	p = appendString(p, neg.hostKey.publicBlob())
	p = appendString(p, serverEphemeral)
	p = appendString(p, sig)
	s.writePacketOrFatal(p)
}

func (s *sshConn) sendKexReplyDH(neg *negotiatedAlgos, f *big.Int, H []byte) {
	sig := neg.hostKey.sign(rand.Reader, H)
	var p []byte
	p = append(p, 31)
	p = appendString(p, neg.hostKey.publicBlob())
	p = appendMpint(p, f)
	p = appendString(p, sig)
	s.writePacketOrFatal(p)
}

// ---------- deriving session keys ----------

func expandKey(Kenc, H []byte, id byte, sessionID []byte, need int, hashAlgo crypto.Hash) []byte {
	var out []byte
	var prev []byte
	for len(out) < need {
		h := hashNew(hashAlgo)
		h.Write(Kenc)
		h.Write(H)
		if prev == nil {
			h.Write([]byte{id})
			h.Write(sessionID)
		} else {
			h.Write(prev)
		}
		prev = h.Sum(nil)
		out = append(out, prev...)
	}
	return out[:need]
}

func cipherKeySize(name string) (keySize, ivSize int, aead bool) {
	switch name {
	case "aes256-ctr":
		return 32, 16, false
	case "aes128-ctr":
		return 16, 16, false
	case "chacha20-poly1305@openssh.com":
		return 64, 0, true
	}
	return 0, 0, false
}

func makeCryptState(cipherName, macName string, key, iv, macKey []byte) *cryptState {
	cs := &cryptState{cipherName: cipherName, macName: macName}
	_, _, isAEAD := cipherKeySize(cipherName)
	if isAEAD {
		cs.aead = true
		cs.key = append([]byte(nil), key...)
		cs.blockSize = 8
		return cs
	}
	if cipherName == "aes256-ctr" || cipherName == "aes128-ctr" {
		block, err := aes.NewCipher(key)
		if err != nil {
			fatalf("Integrity error")
		}
		cs.stream = cipher.NewCTR(block, iv)
		cs.blockSize = 16
		cs.macKey = append([]byte(nil), macKey...)
		return cs
	}
	cs.stream = identityStream{}
	cs.blockSize = 8
	return cs
}

func (s *sshConn) buildNewCryptStates(neg *negotiatedAlgos, res *kexResult) (inCS, outCS *cryptState) {
	sessionID := s.sessionID
	needFor := func(cipherName string) (int, int) {
		ks, ivs, _ := cipherKeySize(cipherName)
		return ks, ivs
	}
	ksCS, ivCS := needFor(neg.encCS)
	ksSC, ivSC := needFor(neg.encSC)
	ivC := expandKey(res.Kencoded, res.H, 'A', sessionID, ivCS, neg.hashAlgo)
	ivS := expandKey(res.Kencoded, res.H, 'B', sessionID, ivSC, neg.hashAlgo)
	keyC := expandKey(res.Kencoded, res.H, 'C', sessionID, ksCS, neg.hashAlgo)
	keyS := expandKey(res.Kencoded, res.H, 'D', sessionID, ksSC, neg.hashAlgo)
	macC := expandKey(res.Kencoded, res.H, 'E', sessionID, 32, neg.hashAlgo)
	macS := expandKey(res.Kencoded, res.H, 'F', sessionID, 32, neg.hashAlgo)
	inCS = makeCryptState(neg.encCS, neg.macCS, keyC, ivC, macC)
	outCS = makeCryptState(neg.encSC, neg.macSC, keyS, ivS, macS)
	return
}
