func (s *sshConn) serverHostkeyAlgos(rekey bool) []string {
	if rekey && s.negotiated != nil {
		return []string{s.negotiated.hostkeyAlgo}
	}
	o := s.opts
	var out []string
	add := func(algo string) { out = append(out, algo) }
	// ed25519
	if o.hostkeys[keyEd25519] != nil {
		add("ssh-ed25519")
	} else if o.createKeys {
		add("ssh-ed25519")
	}
	// ecdsa
	hasECDSA := o.hostkeys[keyECDSA256] != nil || o.hostkeys[keyECDSA384] != nil || o.hostkeys[keyECDSA521] != nil
