		add("ecdsa-sha2-nistp256")
	} else if o.createKeys && !hasECDSA {
		add("ecdsa-sha2-nistp256")
	}
	if o.hostkeys[keyECDSA384] != nil {
		add("ecdsa-sha2-nistp384")
	}
	if o.hostkeys[keyECDSA521] != nil {
		add("ecdsa-sha2-nistp521")
	}
	// rsa
	if o.hostkeys[keyRSA] != nil {
		add("rsa-sha2-256")
