}

func buildKexInitPayload(hostkeyAlgos []string) []byte {
	var p []byte
	p = append(p, 20)
	cookie := make([]byte, 16)
	rand.Read(cookie)
	p = append(p, cookie...)
	lists := [][]string{
		serverKexAlgos,
		hostkeyAlgos,
		serverCipherAlgos,
		serverCipherAlgos,
		serverMACAlgos,
		serverMACAlgos,
		serverCompCS,
		serverCompSC,
		{},
		{},
	}
	for _, l := range lists {
		p = appendString(p, []byte(strings.Join(l, ",")))
	}
	p = append(p, 0)
	p = appendUint32(p, 0)
	return p
}

type clientKexInit struct {
	payload        []byte
	lists          [10][]string
	firstFollows   bool
}

func parseKexInit(payload []byte) *clientKexInit {
	b := newBuffer(payload)
	b.getByte() // message type, already checked
	b.incrPos(16)
	ck := &clientKexInit{payload: payload}
	for i := 0; i < 10; i++ {
		ck.lists[i] = splitNameList(b.getStringStr())
	}
	ck.firstFollows = b.getBool()
	b.getUint32() // reserved
	return ck
}

func (s *sshConn) negotiate(ck *clientKexInit, rekey bool) *negotiatedAlgos {
	n := &negotiatedAlgos{}
	// kex (skip pseudo names in client list)
	var clientKex []string
	for _, a := range ck.lists[0] {
		if a == "ext-info-c" || a == "kex-strict-c-v00@openssh.com" || a == "kexguess2@matt.ucc.asn.au" {
			continue
		}
		clientKex = append(clientKex, a)
	}
	n.kex = findCommonAlgo(clientKex, selectableKexAlgos)
	if n.kex == "" {
		fatalf("No matching algo kex")
	}
	n.hostkeyAlgo = findCommonAlgo(ck.lists[1], s.serverHostkeyAlgos(rekey))
	if n.hostkeyAlgo == "" {
		fatalf("No matching algo hostkey")
	}
	n.encCS = findCommonAlgo(ck.lists[2], serverCipherAlgos)
	if n.encCS == "" {
		fatalf("No matching algo enc c->s")
	}
	n.encSC = findCommonAlgo(ck.lists[3], serverCipherAlgos)
	if n.encSC == "" {
		fatalf("No matching algo enc s->c")
	}
	if n.encCS != "chacha20-poly1305@openssh.com" {
		n.macCS = findCommonAlgo(ck.lists[4], serverMACAlgos)
		if n.macCS == "" {
			fatalf("No matching algo mac c->s")
		}
	}
	if n.encSC != "chacha20-poly1305@openssh.com" {
		n.macSC = findCommonAlgo(ck.lists[5], serverMACAlgos)
		if n.macSC == "" {
			fatalf("No matching algo mac s->c")
		}
	}
	n.compCS = findCommonAlgo(ck.lists[6], serverCompCS)
	if n.compCS == "" {
		fatalf("No matching algo comp c->s")
	}
	n.compSC = findCommonAlgo(ck.lists[7], serverCompSC)
	if n.compSC == "" {
		fatalf("No matching algo comp s->c")
	}
	switch n.kex {
	case "ecdh-sha2-nistp384":
		n.hashAlgo = crypto.SHA384
	case "ecdh-sha2-nistp521":
		n.hashAlgo = crypto.SHA512
	case "sntrup761x25519-sha512", "sntrup761x25519-sha512@openssh.com":
		n.hashAlgo = crypto.SHA512
	default:
		n.hashAlgo = crypto.SHA256
	}
	n.hostKey = s.resolveHostkey(n.hostkeyAlgo)
	return n
}

func defaultHostkeyPathFor(algo string) (string, int) {
	switch algo {
	case "ssh-ed25519":
		return "/etc/dropbear/dropbear_ed25519_host_key", keyEd25519
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		return "/etc/dropbear/dropbear_ecdsa_host_key", keyECDSA256
	case "rsa-sha2-256":
		return "/etc/dropbear/dropbear_rsa_host_key", keyRSA
	}
	return "", keyNone
}

func keyTypeForHostkeyAlgo(algo string) int {
	if algo == "rsa-sha2-256" {
		return keyRSA
	}
	return keyTypeFromName(algo)
}

func (s *sshConn) resolveHostkey(algo string) *hostKey {
	kt := keyTypeForHostkeyAlgo(algo)
	if k, ok := s.opts.hostkeys[kt]; ok && k != nil {
		return k
	}
	if !s.opts.createKeys {
		// Should not happen because only loaded algos were advertised.
		fatalf("No matching algo hostkey")
	}
	path, genType := defaultHostkeyPathFor(algo)
	// Try loading again (may panic on malformed files, matching original).
	res := loadHostkeyFile(path)
	if res.ok && res.typ == kt {
		s.opts.hostkeys[kt] = res.key
		return res.key
	}
	if _, err := os.Lstat(path); err == nil {
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	// Generate.
	k, err := generateHostkey(genType)
	if err != nil {
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	tmpPath := fmt.Sprintf("%s.tmp%d", path, os.Getpid())
	f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		dbLog("Couldn't create new file %s: %s", tmpPath, strerror(err))
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if _, err := f.Write(encodeHostkey(k)); err != nil {
		f.Close()
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		fatalf("Couldn't read or generate hostkey %s", path)
	}
	dbLog("Generated hostkey %s, fingerprint is SHA256:%s", path, fingerprintSHA256(k.publicBlob()))
	s.opts.hostkeys[kt] = k
	return k
}

func hashNew(h crypto.Hash) hash.Hash {
	switch h {
	case crypto.SHA384:
		return sha512.New384()
	case crypto.SHA512:
		return sha512.New()
	default:
		return sha256.New()
	}
}

func appendHashString(h hash.Hash, b []byte) {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], uint32(len(b)))
	h.Write(l[:])
	h.Write(b)
}

// Structure holding the result of a key exchange.
type kexResult struct {
	H          []byte
	Kencoded   []byte // encoded K as used in hash/key derivation input
	hashAlgo   crypto.Hash
}

// RFC 4253 group14 prime.
var dhGroup14Prime = func() *big.Int {
	const pHex = "FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD1" +
		"29024E088A67CC74020BBEA63B139B22514A08798E3404DD" +
		"EF9519B3CD3A431B302B0A6DF25F14374FE1356D6D51C245" +
		"E485B576625E7EC6F44C42E9A637ED6B0BFF5CB6F406B7ED" +
		"EE386BFB5A899FA5AE9F24117C4B1FE649286651ECE45B3D" +
		"C2007CB8A163BF0598DA48361C55D39A69163FA8FD24CF5F" +
		"83655D23DCA3AD961C62F356208552BB9ED529077096966D" +
		"670C354E4ABC9804F1746C08CA18217C32905E462E36CE3B" +
		"E39E772C180E86039B2783A2EC07A28FB5C55DF06F4C52C9" +
		"DE2BCBF6955817183995497CEA956AE515D2261898FA0510" +
		"15728E5A8AACAA68FFFFFFFFFFFFFFFF"
	p, _ := new(big.Int).SetString(pHex, 16)
	return p
}()

// performServerKex runs the algorithm-specific exchange after both
// KEXINITs are known. It returns H and encoded K.
func (s *sshConn) performServerKex(ck *clientKexInit, neg *negotiatedAlgos) *kexResult {
	// First-follows handling.
	if ck.firstFollows {
		guessKex := ""
		guessHK := ""
		if len(ck.lists[0]) > 0 {
			guessKex = ck.lists[0][0]
		}
		if len(ck.lists[1]) > 0 {
			guessHK = ck.lists[1][0]
		}
		if guessKex != neg.kex || guessHK != neg.hostkeyAlgo {
			// Discard the guessed packet.
			s.readPacketRaw()
		}
	}
	payload := s.expectPacket(30)
	b := newBuffer(payload)
	b.getByte()

	magics := func(h hash.Hash) {
		appendHashString(h, []byte(s.clientVersion))
		appendHashString(h, []byte(serverVersionString()))
		appendHashString(h, ck.payload)
		appendHashString(h, s.serverKexInit)
		appendHashString(h, neg.hostKey.publicBlob())
	}

	switch neg.kex {
	case "curve25519-sha256", "curve25519-sha256@libssh.org":
		qc := b.getString()
		if len(qc) != 32 {
			fatalf("Bad curve25519")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(qc)
		if err != nil {
			fatalf("Bad curve25519")
		}
		shared, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		qs := priv.PublicKey().Bytes()
		K := new(big.Int).SetBytes(shared)
		h := hashNew(neg.hashAlgo)
		magics(h)
		appendHashString(h, qc)
		appendHashString(h, qs)
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, qs, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "ecdh-sha2-nistp256", "ecdh-sha2-nistp384", "ecdh-sha2-nistp521":
		qc := b.getString()
		if len(qc) == 0 {
			fatalf("Bad buf_getbyte")
		}
		var curve ecdh.Curve
		var ecCurve elliptic.Curve
		switch neg.kex {
		case "ecdh-sha2-nistp256":
			curve, ecCurve = ecdh.P256(), elliptic.P256()
		case "ecdh-sha2-nistp384":
			curve, ecCurve = ecdh.P384(), elliptic.P384()
		default:
			curve, ecCurve = ecdh.P521(), elliptic.P521()
		}
		if x, _ := elliptic.Unmarshal(ecCurve, qc); x == nil {
			fatalf("ECC error")
		}
		priv, err := curve.GenerateKey(rand.Reader)
		if err != nil {
			fatalf("ECC error")
		}
		remote, err := curve.NewPublicKey(qc)
		if err != nil {
			fatalf("ECC error")
		}
		shared, err := priv.ECDH(remote)
		if err != nil {
			fatalf("ECC error")
		}
		qs := priv.PublicKey().Bytes()
		K := new(big.Int).SetBytes(shared)
		h := hashNew(neg.hashAlgo)
		magics(h)
		appendHashString(h, qc)
		appendHashString(h, qs)
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, qs, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "diffie-hellman-group14-sha256":
		e, ok := b.getMpint()
		p := dhGroup14Prime
		if !ok || e.Cmp(big.NewInt(1)) <= 0 || e.Cmp(new(big.Int).Sub(p, big.NewInt(1))) >= 0 {
			fatalf("Diffie-Hellman error")
		}
		// Generate private exponent.
		privBytes := make([]byte, 256)
		rand.Read(privBytes)
		y := new(big.Int).SetBytes(privBytes)
		y.Mod(y, new(big.Int).Sub(p, big.NewInt(3)))
		y.Add(y, big.NewInt(2))
		f := new(big.Int).Exp(big.NewInt(2), y, p)
		K := new(big.Int).Exp(e, y, p)
		h := hashNew(neg.hashAlgo)
		magics(h)
		// e and f are written as mpints (string wrapped).
		h.Write(wrapString(mpintBytes(e)))
		h.Write(wrapString(mpintBytes(f)))
		Kenc := wrapString(mpintBytes(K))
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReplyDH(neg, f, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "mlkem768x25519-sha256":
		hybrid := b.getString()
		sub := newBuffer(hybrid)
		pqPart := sub.getPtr(1184)
		curvePart := sub.getPtr(32)
		if sub.remaining() != 0 {
			fatalf("Bad sntrup")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(curvePart)
		if err != nil {
			fatalf("Bad curve25519")
		}
		curveSecret, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		pqSecret, pqCiphertext := mlkemEncapsulate(pqPart)
		serverHybrid := append(append([]byte(nil), pqCiphertext...), priv.PublicKey().Bytes()...)
		kh := sha256.New()
		kh.Write(pqSecret)
		kh.Write(curveSecret)
		secret := kh.Sum(nil)
		h := sha256.New()
		magics(h)
		appendHashString(h, hybrid)
		appendHashString(h, serverHybrid)
		Kenc := wrapString(secret)
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, serverHybrid, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}

	case "sntrup761x25519-sha512", "sntrup761x25519-sha512@openssh.com":
		hybrid := b.getString()
		sub := newBuffer(hybrid)
		pqPart := sub.getPtr(1158)
		curvePart := sub.getPtr(32)
		if sub.remaining() != 0 {
			fatalf("Bad sntrup")
		}
		priv, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			fatalf("Bad curve25519")
		}
		remote, err := ecdh.X25519().NewPublicKey(curvePart)
		if err != nil {
			fatalf("Bad curve25519")
		}
		curveSecret, err := priv.ECDH(remote)
		if err != nil {
			fatalf("Bad curve25519")
		}
		pqSecret, pqCiphertext, ok := sntrupEncapsulate(pqPart)
		if !ok {
			fatalf("Bad sntrup")
		}
		serverHybrid := append(append([]byte(nil), pqCiphertext...), priv.PublicKey().Bytes()...)
		kh := sha512.New()
		kh.Write(pqSecret)
		kh.Write(curveSecret)
		secret := kh.Sum(nil)
		h := sha512.New()
		magics(h)
		appendHashString(h, hybrid)
		appendHashString(h, serverHybrid)
		Kenc := wrapString(secret)
		h.Write(Kenc)
		H := h.Sum(nil)
		s.sendKexReply(neg, serverHybrid, H)
		return &kexResult{H: H, Kencoded: Kenc, hashAlgo: neg.hashAlgo}
	}
	fatalf("No matching algo kex")
	return nil
}

func (s *sshConn) sendKexReply(neg *negotiatedAlgos, serverEphemeral []byte, H []byte) {
	sig := neg.hostKey.sign(rand.Reader, H)
	var p []byte
	p = append(p, 31)
	p = appendString(p, neg.hostKey.publicBlob())
	p = appendString(p, serverEphemeral)
	p = appendString(p, sig)
	s.writePacketOrFatal(p)
}

func (s *sshConn) sendKexReplyDH(neg *negotiatedAlgos, f *big.Int, H []byte) {
	sig := neg.hostKey.sign(rand.Reader, H)
	var p []byte
	p = append(p, 31)
	p = appendString(p, neg.hostKey.publicBlob())
	p = appendMpint(p, f)
	p = appendString(p, sig)
	s.writePacketOrFatal(p)
}

// ---------- deriving session keys ----------

func expandKey(Kenc, H []byte, id byte, sessionID []byte, need int, hashAlgo crypto.Hash) []byte {
	var out []byte
	var prev []byte
	for len(out) < need {
		h := hashNew(hashAlgo)
		h.Write(Kenc)
		h.Write(H)
		if prev == nil {
			h.Write([]byte{id})
			h.Write(sessionID)
		} else {
			h.Write(prev)
		}
		prev = h.Sum(nil)
		out = append(out, prev...)
	}
	return out[:need]
}

func cipherKeySize(name string) (keySize, ivSize int, aead bool) {
	switch name {
	case "aes256-ctr":
		return 32, 16, false
	case "aes128-ctr":
		return 16, 16, false
	case "chacha20-poly1305@openssh.com":
		return 64, 0, true
	}
	return 0, 0, false
}

func makeCryptState(cipherName, macName string, key, iv, macKey []byte) *cryptState {
	cs := &cryptState{cipherName: cipherName, macName: macName}
	_, _, isAEAD := cipherKeySize(cipherName)
	if isAEAD {
		cs.aead = true
		cs.key = append([]byte(nil), key...)
		cs.blockSize = 8
		return cs
	}
	if cipherName == "aes256-ctr" || cipherName == "aes128-ctr" {
		block, err := aes.NewCipher(key)
		if err != nil {
			fatalf("Integrity error")
		}
		cs.stream = cipher.NewCTR(block, iv)
		cs.blockSize = 16
		cs.macKey = append([]byte(nil), macKey...)
		return cs
	}
	cs.stream = identityStream{}
	cs.blockSize = 8
	return cs
}

func (s *sshConn) buildNewCryptStates(neg *negotiatedAlgos, res *kexResult) (inCS, outCS *cryptState) {
	sessionID := s.sessionID
	needFor := func(cipherName string) (int, int) {
		ks, ivs, _ := cipherKeySize(cipherName)
		return ks, ivs
	}
	ksCS, ivCS := needFor(neg.encCS)
	ksSC, ivSC := needFor(neg.encSC)
	ivC := expandKey(res.Kencoded, res.H, 'A', sessionID, ivCS, neg.hashAlgo)
	ivS := expandKey(res.Kencoded, res.H, 'B', sessionID, ivSC, neg.hashAlgo)
	keyC := expandKey(res.Kencoded, res.H, 'C', sessionID, ksCS, neg.hashAlgo)
	keyS := expandKey(res.Kencoded, res.H, 'D', sessionID, ksSC, neg.hashAlgo)
	macC := expandKey(res.Kencoded, res.H, 'E', sessionID, 32, neg.hashAlgo)
	macS := expandKey(res.Kencoded, res.H, 'F', sessionID, 32, neg.hashAlgo)
	inCS = makeCryptState(neg.encCS, neg.macCS, keyC, ivC, macC)
	outCS = makeCryptState(neg.encSC, neg.macSC, keyS, ivS, macS)
	return
}
EOF
