func (s *sshConn) handshake() {
	// Send our version immediately.
	if _, err := s.conn.Write([]byte(serverVersionString() + "\r\n")); err != nil {
		if s.termFlag.Load() {
			fatalf("Terminated by signal")
		}
		fatalf("Error writing: %s", strerror(err))
	}
	// Build and send our KEXINIT.
	s.serverKexInit = buildKexInitPayload(s.serverHostkeyAlgos(false))
	s.writePacketOrFatal(s.serverKexInit)

	s.readClientVersion()

	ckPayload := s.expectPacket([]byte{20}, false)
	ck := parseKexInit(ckPayload)
	for _, a := range ck.lists[0] {
		if a == "kex-strict-c-v00@openssh.com" {
			s.strictKex = true
		}
		if a == "ext-info-c" {
			s.sendExtInfo = true
		}
	}
	if s.strictKex && s.preKexPackets > 0 {
		fatalf("First packet wasn't kexinit")
	}
	neg := s.negotiate(ck, false)
	s.negotiated = neg
	res := s.performServerKex(ck, neg)
	s.sessionID = append([]byte(nil), res.H...)
	inCS, outCS := s.buildNewCryptStates(neg, res)

	// Send NEWKEYS with old keys, then switch outbound.
	s.writePacketOrFatal([]byte{21})
	s.pc.wState = outCS
	if s.strictKex {
		s.pc.sendSeq = 0
	}
	// Activate zlib (not delayed) compression if negotiated.
	if neg.compSC == "zlib" {
		s.pc.compOutName = "zlib"
		s.pc.zlibWBuf = new(bytes.Buffer)
		s.pc.zlibW = zlib.NewWriter(s.pc.zlibWBuf)
		s.pc.compOutOn = true
	} else {
		s.pc.compOutName = neg.compSC
	}
	// Expect client NEWKEYS (read with old inbound keys).
	s.expectPacket([]byte{21}, false)
	s.pc.rState = inCS
	if s.strictKex {
		s.pc.recvSeq = 0
	}
	s.initialKexDone = true

	if s.sendExtInfo {
		var p []byte
		p = append(p, 7)
		p = appendUint32(p, 1)
		p = appendString(p, []byte("server-sig-algs"))
		p = appendString(p, []byte(serverSigAlgsList))
		s.writePacketOrFatal(p)
	}

	// Start keepalive/idle monitor after the transport is up.
	go s.timerLoop()

	// Service request.
	payload := s.expectPacket([]byte{5}, true)
	b := newBuffer(payload)
	b.getByte()
	service := b.getStringStr()
	if service != "ssh-userauth" {
		fatalf("Unknown service")
	}
	var p []byte
	p = append(p, 6)
	p = appendString(p, []byte(service))
	s.writePacketOrFatal(p)
}

func (s *sshConn) readClientVersion() {
	for {
		line := s.readVersionLine()
		trimmed := strings.TrimSuffix(line, "\n")
		trimmed = strings.TrimSuffix(trimmed, "\r")
		if strings.HasPrefix(trimmed, "SSH-") {
			rest := trimmed[4:]
			ver := rest
			if i := strings.IndexAny(rest, "- "); i >= 0 {
				ver = rest[:i]
			}
			if ver != "2.0" && ver != "1.99" {
				fatalf("Incompatible remote version '%s'", trimmed)
			}
			s.clientVersion = trimmed
			return
		}
		// Otherwise a pre-banner line: keep reading.
	}
}

// readVersionLine reads up to and including '\n', but at most 256 bytes.
func (s *sshConn) readVersionLine() string {
	var buf []byte
	for len(buf) < 256 {
		c, err := s.pc.r.ReadByte()
		if err != nil {
			if s.termFlag.Load() {
				fatalf("Terminated by signal")
			}
			if err == io.EOF {
				fatalf("Exited normally")
			}
			fatalf("Error reading: %s", strerror(err))
		}
		buf = append(buf, c)
		if c == '\n' {
			break
		}
	}
	return string(buf)
}

// expectPacket reads packets until one of expect arrives, handling
// disconnect/ignore/debug per strict-kex state.
func (s *sshConn) expectPacket(expect []byte, afterInitial bool) []byte {
	for {
		payload, err := s.pc.readPacket()
		if err == errCleanEOF {
			if s.termFlag.Load() {
				fatalf("Terminated by signal")
			}
			// A write error may be the real cause.
			fatalf("Exited normally")
		}
		if err != nil {
			if fe, ok := err.(*fatalError); ok {
				panic(fe)
			}
			fatalf("%s", err.Error())
		}
		if len(payload) == 0 {
			fatalf("Bad packet size 0")
		}
		msg := payload[0]
		if msg == 1 {
			b := newBuffer(payload)
			b.getByte()
			b.getUint32()
			b.getString()
			b.getString()
			fatalf("Disconnect received")
		}
		isGeneric := msg == 2 || msg == 3 || msg == 4
		if isGeneric {
			strictActive := s.strictKex && !s.initialKexDone
			if !strictActive {
				if len(expect) == 1 && expect[0] == 20 && !s.initialKexDone {
					s.preKexPackets++
				}
				continue
			}
			// strict: fall through to unexpected handling
		}
		for _, e := range expect {
			if msg == e {
				return payload
			}
		}
		fatalf("Unexpected packet type %d, expected %d", msg, expect[0])
	}
}

// readPacketRaw reads and discards one packet (for guessed kex).
func (s *sshConn) readPacketRaw() {
	_, err := s.pc.readPacket()
	if err == errCleanEOF {
		fatalf("Exited normally")
	}
	if err != nil {
		if fe, ok := err.(*fatalError); ok {
			panic(fe)
		}
		fatalf("%s", err.Error())
	}
}

func (s *sshConn) timerLoop() {
	ticker := time.NewTicker(250 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-s.done:
			return
		case now := <-ticker.C:
			k := s.opts.keepalive
			if k > 0 {
				lastAny := time.Unix(0, s.pc.lastAnyRecv.Load())
				lastKA := time.Unix(0, s.pc.lastKeepalive.Load())
				if now.Sub(lastAny) >= time.Duration(k)*time.Second && now.Sub(lastKA) >= time.Duration(k)*time.Second {
					s.pc.lastKeepalive.Store(now.UnixNano())
					var p []byte
					p = append(p, 80)
					p = appendString(p, []byte("keepalive@openssh.com"))
					p = append(p, 1)
					s.pc.writePacket(p)
				}
			}
			idle := s.opts.idleTimeout
			if idle > 0 && s.authDone {
				last := time.Unix(0, s.pc.lastDataNano.Load())
				if now.Sub(last) >= time.Duration(idle)*time.Second {
					// Trigger the main loop to exit with Idle timeout by
					// closing the connection and flagging the reason.
					s.idleExpired.Store(true)
					s.conn.Close()
					return
				}
			}
		}
	}
}

// packetResult is delivered by the post-auth packet reader.
type packetResult struct {
	payload []byte
	err     error // errCleanEOF or *fatalError
}

// serveLoop is the post-auth connection loop.
func (s *sshConn) serveLoop() {
	inCh := make(chan packetResult, 32)
	go s.packetReader(inCh)
	for {
		select {
		case <-s.done:
			return
		case res := <-inCh:
			if res.err == errCleanEOF {
				if s.idleExpired.Load() {
					fatalf("Idle timeout")
				}
				if s.termFlag.Load() {
					fatalf("Terminated by signal")
				}
				if v, ok := s.pc.writeErr.Load().(string); ok && v != "" {
					fatalf("%s", v)
				}
				fatalf("Exited normally")
			}
			if res.err != nil {
				if fe, ok := res.err.(*fatalError); ok {
					panic(fe)
				}
				fatalf("%s", res.err.Error())
			}
			s.handlePacket(res.payload)
		}
	}
}

// packetReader reads packets after auth, handling rekeys and generic
// transport messages internally.
func (s *sshConn) packetReader(inCh chan<- packetResult) {
	for {
		payload, err := s.pc.readPacket()
		if err != nil {
			inCh <- packetResult{err: err}
			return
		}
		if len(payload) == 0 {
			continue
		}
		msg := payload[0]
		switch msg {
		case 1: // disconnect
			b := newBuffer(payload)
			func() {
				defer func() { _ = recover() }()
				b.getByte()
				b.getUint32()
				b.getString()
				b.getString()
			}()
			inCh <- packetResult{err: &fatalError{"Disconnect received"}}
			return
		case 2, 3, 4: // ignore, unimplemented, debug
			continue
		case 7: // ext-info from client
			continue
		case 20: // rekey
			func() {
				defer func() {
					if r := recover(); r != nil {
						if fe, ok := r.(*fatalError); ok {
							inCh <- packetResult{err: fe}
						} else {
							panic(r)
						}
					}
				}()
				s.doRekey(payload)
			}()
			// If doRekey panicked it queued a fatal result; loop will
			// try reading from a closed/broken connection next and
			// terminate. To avoid hanging, check writeErr/done:
			select {
			case <-s.done:
				return
			default:
			}
			continue
		default:
			// Data activity tracking for idle timeout: global requests
			// and their responses don't count.
			if msg != 80 && msg != 81 && msg != 82 {
				s.pc.lastDataNano.Store(time_NowNano())
			}
			inCh <- packetResult{payload: payload}
		}
	}
}

func time_NowNano() int64 {
	return time.Now().UnixNano()
}

// doRekey handles a client-initiated rekey. Runs in the packet reader
// goroutine; takes the write mutex for the exchange.
func (s *sshConn) doRekey(clientKexPayload []byte) {
	ck := parseKexInit(clientKexPayload)
	neg := s.negotiate(ck, true)
	oldNeg := s.negotiated
	s.negotiated = neg
	_ = oldNeg
	// Send our kexinit and perform the exchange. Writes must use the
	// current outbound state until NEWKEYS is sent.
	s.pc.wmu.Lock()
	// Save the kexinit we are about to send for the exchange hash.
	savedInit := s.serverKexInit
	s.serverKexInit = buildKexInitPayload(s.serverHostkeyAlgos(true))
	if err := s.pc.writePacketLocked(s.serverKexInit); err != nil {
		s.pc.wmu.Unlock()
		s.serverKexInit = savedInit
		fatalf("Error writing: %s", strerror(err))
	}
	res := s.performServerKexLocked(ck, neg)
	inCS, outCS := s.buildNewCryptStates(neg, res)
	// Send NEWKEYS (old outbound), then switch.
	if err := s.pc.writePacketLocked([]byte{21}); err != nil {
		s.pc.wmu.Unlock()
		fatalf("Error writing: %s", strerror(err))
	}
	s.pc.wState = outCS
	s.pc.wmu.Unlock()
	// Read client NEWKEYS with old inbound state. Generic packets are
	// not expected here in practice; treat others as unexpected.
	for {
		payload, err := s.pc.readPacket()
		if err == errCleanEOF {
			fatalf("Exited normally")
		}
		if err != nil {
			if fe, ok := err.(*fatalError); ok {
				panic(fe)
			}
			fatalf("%s", err.Error())
		}
		if len(payload) > 0 && (payload[0] == 2 || payload[0] == 3 || payload[0] == 4) {
			continue
		}
		if len(payload) == 0 || payload[0] != 21 {
			var got byte
			if len(payload) > 0 {
				got = payload[0]
			}
			fatalf("Unexpected packet type %d, expected %d", got, 21)
		}
		break
	}
	s.pc.rState = inCS
	// Compression state resets on rekey: delayed compression stays on
	// (authentication has already happened).
	s.resetCompressionAfterRekey(neg)
}

func (s *sshConn) resetCompressionAfterRekey(neg *negotiatedAlgos) {
	// server->client
	if neg.compSC == "zlib@openssh.com" || neg.compSC == "zlib" {
		s.pc.zlibWBuf = new(bytes.Buffer)
		s.pc.zlibW = zlib.NewWriter(s.pc.zlibWBuf)
		s.pc.compOutOn = true
	} else {
		s.pc.compOutOn = false
		s.pc.zlibW = nil
	}
}

// activateDelayedCompression is called after successful authentication.
func (s *sshConn) activateDelayedCompression() {
	if s.negotiated != nil && s.negotiated.compSC == "zlib@openssh.com" {
		s.pc.zlibWBuf = new(bytes.Buffer)
		s.pc.zlibW = zlib.NewWriter(s.pc.zlibWBuf)
		s.pc.compOutOn = true
	}
}
