package main

import (
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	mrand "math/rand"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

// ---------- user checking ----------

func (s *sshConn) checkUser(username string) bool {
	if s.userChecked && s.username == username {
		return s.userValid
	}
	s.username = username
	s.userChecked = true
	s.userValid = false
	s.exitUser = ""
	pw := lookupUser(username)
	if pw == nil {
		dbLog("Login attempt for nonexistent user from %s", s.remoteAddr)
		s.pw = nil
		return false
	}
	s.pw = pw
	s.exitUser = username
	if os.Geteuid() != 0 && pw.UID != os.Geteuid() {
		dbLog("Login attempt with wrong user %s from %s", username, s.remoteAddr)
		return false
	}
	if s.opts.noRootLogin && pw.UID == 0 {
		dbLog("root login rejected")
		return false
	}
	if s.opts.groupName != nil {
		g := lookupGroup(*s.opts.groupName)
		member := false
		if g != nil {
			if pw.GID == g.GID {
				member = true
			}
			for _, m := range g.Members {
				if m == username {
					member = true
				}
			}
		}
		if !member {
			dbLog("Logins are restricted to the group %s but user '%s' is not a member", *s.opts.groupName, username)
			return false
		}
	}
	shell := pw.Shell
	if shell == "" {
		shell = "/bin/sh"
	}
	s.shell = shell
	valid := false
	for _, sh := range validShells() {
		if sh == shell {
			valid = true
			break
		}
	}
	if !valid {
		dbLog("User '%s' has invalid shell, rejected", username)
		return false
	}
	s.userValid = true
	return true
}

// ---------- auth failure / success plumbing ----------

func (s *sshConn) authMethodsList() []string {
	if s.opts.twoFactor {
		if s.factorsDone["publickey"] && !s.factorsDone["password"] {
			return []string{"password"}
		}
		if s.factorsDone["password"] && !s.factorsDone["publickey"] {
			return []string{"publickey"}
		}
	}
	methods := []string{"publickey"}
	if !s.opts.disablePass {
		methods = append(methods, "password")
	}
	return methods
}

func (s *sshConn) sendAuthFailure(partial bool) {
	var p []byte
	p = append(p, 51)
	p = appendString(p, []byte(strings.Join(s.authMethodsList(), ",")))
	if partial {
		p = append(p, 1)
	} else {
		p = append(p, 0)
	}
	s.writePacketOrFatal(p)
}

func authFailureDelay() {
	d := 250 + mrand.Intn(100)
	time.Sleep(time.Duration(d) * time.Millisecond)
}

// countedFailure registers a failed auth attempt, delays, and
// terminates the connection if the limit has been exceeded. It
// returns normally if the caller should send an auth failure.
func (s *sshConn) countedFailure() {
	s.authFails++
	if uint32(s.authFails) > s.opts.maxAuthTries {
		authFailureDelay()
		fatalf("Max auth tries reached - user '%s'", s.username)
	}
}

func (s *sshConn) countedFailureWithDelay() {
	s.countedFailureNoDelay()
	authFailureDelay()
}
func (s *sshConn) countedFailureNoDelay() {
	s.authFails++
	if uint32(s.authFails) > s.opts.maxAuthTries {
		authFailureDelay()
		fatalf("Max auth tries reached - user '%s'", s.username)
	}
}

// succeedFactor records a successful auth factor. It returns true if
// authentication is now complete (and the success packet was sent).
// logLine is the already-formatted success message without any
// "extra auth required" suffix.
func (s *sshConn) succeedFactor(method, logLine string) bool {
	if s.opts.twoFactor && !s.factorsDone[otherFactor(method)] {
		s.factorsDone[method] = true
		dbLog("%s, extra auth required", logLine)
		s.sendAuthFailure(true)
		return false
	}
	s.factorsDone[method] = true
	dbLog("%s", logLine)
	s.authDone = true
	// Notify the parent that we are authenticated.
	if s.unauth != nil {
		s.unauth.Close()
		s.unauth = nil
	}
	s.writePacketOrFatal([]byte{52})
	s.activateDelayedCompression()
	// Switch effective identity to the user when running as root.
	s.switchToUser()
	s.pc.lastDataNano.Store(time.Now().UnixNano())
	return true
}

func otherFactor(m string) string {
	if m == "publickey" {
		return "password"
	}
	return "publickey"
}

func (s *sshConn) switchToUser() {
	if os.Geteuid() != 0 || s.pw == nil {
		return
	}
	// Retain saved root uid so session children can regain it for
	// pty/lastlog setup: use seteuid/setegid and set groups.
	groups := userGroupList(s.pw.Name, s.pw.GID)
	syscall.Setgroups(groups)
	syscall.Setegid(s.pw.GID)
	syscall.Seteuid(s.pw.UID)
}

// withUserEUID runs fn with the effective uid/gid of pw when root.
func withUserEUID(pw *passwdInfo, fn func()) {
	if os.Getuid() != 0 || os.Geteuid() != 0 {
		// Already switched (post-auth) or not root: fn directly, but
		// note Getuid()==0 check above means real uid root: when we
		// have seteuid'd, euid != 0; regain for the switch logic
		// below only in pre-auth root processes.
		if os.Getuid() != 0 {
			fn()
			return
		}
	}
	if os.Geteuid() == pw.UID {
		fn()
		return
	}
	oldGid := syscall.Getegid()
	syscall.Setegid(pw.GID)
	syscall.Seteuid(pw.UID)
	fn()
	syscall.Seteuid(0)
	syscall.Setegid(oldGid)
}

// ---------- main auth loop ----------

func (s *sshConn) doAuth() {
	// Default key options.
	s.keyOpts = defaultAuthKeyOptions()
	for {
		payload := s.expectPacket([]byte{50}, true)
		if !s.bannerSent {
			s.bannerSent = true
			if s.opts.bannerLoaded {
				var p []byte
				p = append(p, 53)
				p = appendString(p, s.opts.banner)
				p = appendString(p, []byte{})
				s.writePacketOrFatal(p)
			}
		}
		if s.handleAuthRequest(payload) {
			return
		}
	}
}

// handleAuthRequest returns true when authentication completed.
func (s *sshConn) handleAuthRequest(payload []byte) bool {
	b := newBuffer(payload)
	b.getByte()
	username := cstr(b.getStringStr())
	_ = b.getStringStr() // service
	method := cstr(b.getStringStr())

	valid := s.checkUser(username)

	switch method {
	case "none":
		s.sendAuthFailure(false)
		return false
	case "password":
		if s.opts.disablePass {
			s.sendAuthFailure(false)
			return false
		}
		return s.authPassword(b, valid)
	case "publickey":
		return s.authPubkey(b, valid)
	default:
		s.sendAuthFailure(false)
		return false
	}
}

// ---------- password auth ----------

func (s *sshConn) authPassword(b *buffer, valid bool) bool {
	change := b.getBool()
	password := cstr(b.getStringStr())
	if change {
		// A new-password field follows; password changes are not
		// supported, consume it and fail as a bad attempt.
		_ = b.getStringStr()
		if valid {
			s.countedFailureWithDelay()
		} else {
			s.countedFailureWithDelay()
		}
		s.sendAuthFailure(false)
		return false
	}
	if !valid {
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	if s.pw.UID == 0 && s.opts.disableRootPw {
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	encPass := s.pw.Pass
	if encPass == "x" {
		if sh, ok := lookupShadow(s.pw.Name); ok {
			encPass = sh
		}
	}
	if encPass == "" {
		if !s.opts.blankPass {
			dbLog("User '%s' has blank password, rejected", s.username)
			s.countedFailureWithDelay()
			s.sendAuthFailure(false)
			return false
		}
		// Blank password account: any password succeeds.
		s.applyPasswordAuthSettings()
		return s.succeedFactor("password", fmt.Sprintf("Auth succeeded with blank password for '%s' from %s", s.username, s.remoteAddr))
	}
	computed := cryptPassword(password, encPass)
	if computed == "" || computed != encPass {
		dbLog("Bad password attempt for '%s' from %s", s.username, s.remoteAddr)
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	s.applyPasswordAuthSettings()
	return s.succeedFactor("password", fmt.Sprintf("Password auth succeeded for '%s' from %s", s.username, s.remoteAddr))
}

func (s *sshConn) applyPasswordAuthSettings() {
	// A final password authentication clears pubkey-derived settings,
	// mirroring the reference behaviour with two-factor auth.
	s.keyOpts = defaultAuthKeyOptions()
	s.pubkeyInfo = ""
	s.hasInfo = false
}

// ---------- public key auth ----------

func (s *sshConn) authPubkey(b *buffer, valid bool) bool {
	hasSig := b.getBool()
	reqAlgo := cstr(b.getStringStr())
	keyBlob := b.getString()
	if !valid {
		// Pubkey queries/signed attempts for invalid users fail
		// without counting (signed attempts cannot arrive from
		// compliant clients because the query is rejected).
		s.sendAuthFailure(false)
		return false
	}
	if !supportedPubkeyAlgo(reqAlgo) {
		s.sendAuthFailure(false)
		return false
	}
	offered := parsePubkeyBlobSafe(keyBlob)
	if offered == nil {
		s.sendAuthFailure(false)
		return false
	}
	// The request algorithm must match the blob format.
	if !pubkeyAlgoMatchesBlob(reqAlgo, offered) {
		s.sendAuthFailure(false)
		return false
	}
	match := s.lookupAuthorizedKey(offered)
	if match == nil {
		s.sendAuthFailure(false)
		return false
	}
	if !hasSig {
		// Query: reply PK_OK.
		var p []byte
		p = append(p, 60)
		p = appendString(p, []byte(reqAlgo))
		p = appendString(p, keyBlob)
		s.writePacketOrFatal(p)
		return false
	}
	sigBlob := b.getString()
	// Build the data that was signed.
	var signed []byte
	signed = appendString(signed, s.sessionID)
	signed = append(signed, 50)
	signed = appendString(signed, []byte(s.username))
	signed = appendString(signed, []byte("ssh-connection"))
	signed = appendString(signed, []byte("publickey"))
	signed = append(signed, 1)
	signed = appendString(signed, []byte(reqAlgo))
	signed = appendString(signed, keyBlob)

	if !verifyPubkeySignature(offered, signed, sigBlob, match.opts) {
		dbLog("Pubkey auth bad signature for '%s' with key SHA256:%s from %s", s.username, offered.fingerprint(), s.remoteAddr)
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	// Success: apply options from this authorized_keys line.
	s.keyOpts = match.opts
	s.pubkeyInfo = match.info
	s.hasInfo = match.hasInfo
	return s.succeedFactor("publickey", fmt.Sprintf("Pubkey auth succeeded for '%s' with %s key SHA256:%s from %s", s.username, offered.keyTypeString(), offered.fingerprint(), s.remoteAddr))
}

func supportedPubkeyAlgo(algo string) bool {
	switch algo {
	case "ssh-ed25519", "sk-ssh-ed25519@openssh.com",
		"ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521",
		"sk-ecdsa-sha2-nistp256@openssh.com", "rsa-sha2-256":
		return true
	}
	return false
}

func pubkeyAlgoMatchesBlob(reqAlgo string, pk *pubKey) bool {
	if reqAlgo == "rsa-sha2-256" {
		return pk.algo == "ssh-rsa"
	}
	return reqAlgo == pk.algo
}

func parsePubkeyBlobSafe(blob []byte) (pk *pubKey) {
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(*fatalError); ok {
				pk = nil
				return
			}
			panic(r)
		}
	}()
	return parsePubkeyBlob(blob)
}

func verifyPubkeySignature(pk *pubKey, signedData, sigBlob []byte, opts *authKeyOptions) bool {
	b := newBuffer(sigBlob)
	var sigAlgo string
	var sig []byte
	ok := func() (ok bool) {
		defer func() {
			if r := recover(); r != nil {
				ok = false
			}
		}()
		sigAlgo = b.getStringStr()
		sig = b.getString()
		return true
	}()
	if !ok {
		return false
	}
	if pk.isSK {
		return verifySKSignature(pk, signedData, sigAlgo, sig, opts)
	}
	defer func() { _ = recover() }()
	return pk.verifyWithAlgoWrapped(signedData, sigAlgo, sig)
}

func (p *pubKey) verifyWithAlgoWrapped(data []byte, sigAlgo string, sig []byte) (ret bool) {
	defer func() {
		if r := recover(); r != nil {
			ret = false
		}
	}()
	return p.verifyWithAlgo(data, sigAlgo, sig, nil)
}

func verifySKSignature(pk *pubKey, signedData []byte, sigAlgo string, sig []byte, opts *authKeyOptions) bool {
	if sigAlgo != pk.algo {
		return false
	}
	// sig content: string signature, byte flags, uint32 counter
	b := newBuffer(sig)
	var rawSig []byte
	var flags byte
	var counter uint32
	okParse := func() (ok bool) {
		defer func() {
			if r := recover(); r != nil {
				ok = false
			}
		}()
		rawSig = b.getString()
		flags = b.getByte()
		counter = b.getUint32()
		return true
	}()
	if !okParse {
		return false
	}
	if opts != nil {
		if !opts.noTouchRequired && flags&0x01 == 0 {
			return false
		}
		if opts.verifyRequired && flags&0x04 == 0 {
			return false
		}
	}
	appHash := sha256.Sum256([]byte(pk.skApp))
	challengeHash := sha256.Sum256(signedData)
	var msg []byte
	msg = append(msg, appHash[:]...)
	msg = append(msg, flags)
	var ctr [4]byte
	ctr[0] = byte(counter >> 24)
	ctr[1] = byte(counter >> 16)
	ctr[2] = byte(counter >> 8)
	ctr[3] = byte(counter)
	msg = append(msg, ctr[:]...)
	msg = append(msg, challengeHash[:]...)
	// Verify using the underlying plain key over msg with rawSig.
	plain := *pk
	plain.isSK = false
	if pk.typ == keyEd25519 {
		plain.algo = "ssh-ed25519"
		return plain.verifyWithAlgo(msg, "ssh-ed25519", rawSig, nil)
	}
	// ECDSA: rawSig is (mpint r || mpint s) encoded content.
	plain.algo = "ecdsa-sha2-nistp256"
	return plain.verifyWithAlgo(msg, "ecdsa-sha2-nistp256", rawSig, nil)
}

var _ = rand.Reader
var _ = bytes.Equal

// ---------- authorized_keys ----------

type authKeyOptions struct {
	noPty            bool
	noPortForwarding bool
	noAgentForwarding bool
	noX11Forwarding  bool
	noTouchRequired  bool
	verifyRequired   bool
	restrict         bool
	forcedCmd        *string
	permitOpens      []permitOpen
	hasPermitOpens   bool
}

type permitOpen struct {
	host string
	port string
}

func defaultAuthKeyOptions() *authKeyOptions {
	return &authKeyOptions{}
}

type authorizedMatch struct {
	opts    *authKeyOptions
	info    string
	hasInfo bool
}

func (s *sshConn) authorizedKeysPath() string {
	if s.opts.authDir != nil {
		return *s.opts.authDir + "/authorized_keys"
	}
	return s.pw.Home + "/.ssh/authorized_keys"
}

// checkPubkeyPerms verifies directory ownership/permissions for the
// authorized_keys file. Returns true if acceptable.
func (s *sshConn) checkPubkeyPerms(filename string) bool {
	dir := filepath.Dir(filename)
	// Collect directories from the file's directory up to the user's
	// home (inclusive), or to the root if not under home.
	var dirs []string
	d := dir
	for {
		dirs = append(dirs, d)
		if d == s.pw.Home {
			break
		}
		parent := filepath.Dir(d)
		if parent == d {
			break
		}
		d = parent
	}
	for _, dd := range dirs {
		fi, err := os.Stat(dd)
		if err != nil {
			return false
		}
		st, ok := fi.Sys().(*syscall.Stat_t)
		if !ok {
			continue
		}
		if (int(st.Uid) != s.pw.UID && st.Uid != 0) || fi.Mode().Perm()&0022 != 0 {
			dbLog("%s must be owned by user or root, and not writable by group or others", dd)
			return false
		}
	}
	return true
}

func (s *sshConn) lookupAuthorizedKey(offered *pubKey) *authorizedMatch {
	filename := s.authorizedKeysPath()
	var data []byte
	var permsOk bool
	withUserEUID(s.pw, func() {
		if !s.checkPubkeyPerms(filename) {
			permsOk = false
			return
		}
		permsOk = true
		data, _ = os.ReadFile(filename)
	})
	if !permsOk || data == nil {
		return nil
	}
	lines := splitAuthorizedLines(string(data))
	for idx, line := range lines {
		m := s.matchAuthorizedLine(line, offered, filename, idx+1)
		if m != nil {
			return m
		}
	}
	return nil
}

// splitAuthorizedLines splits file content into lines, discarding
// lines longer than 4200 bytes (including the newline).
func splitAuthorizedLines(content string) []string {
	var out []string
	for len(content) > 0 {
		nl := strings.IndexByte(content, '\n')
		var line string
		if nl < 0 {
			line = content
			content = ""
			if len(line) > 4200 {
				continue
			}
			out = append(out, line)
		} else {
			line = content[:nl+1]
			content = content[nl+1:]
			if len(line) > 4200 {
				continue
			}
			out = append(out, strings.TrimSuffix(strings.TrimSuffix(line, "\n"), "\r"))
		}
	}
	return out
}

var knownBlobTypes = map[string]bool{
	"ssh-rsa": true, "ssh-dss": true, "ssh-ed25519": true,
	"ecdsa-sha2-nistp256": true, "ecdsa-sha2-nistp384": true, "ecdsa-sha2-nistp521": true,
	"sk-ssh-ed25519@openssh.com": true, "sk-ecdsa-sha2-nistp256@openssh.com": true,
}

func (s *sshConn) matchAuthorizedLine(line string, offered *pubKey, filename string, lineno int) *authorizedMatch {
	if line == "" || line[0] == '#' {
		return nil
	}
	rest := line
	optsStr := ""
	// If first token is a known key type, there are no options.
	firstSpace := strings.IndexByte(rest, ' ')
	if firstSpace < 0 {
		return nil
	}
	firstTok := rest[:firstSpace]
	if !knownBlobTypes[firstTok] {
		// Options field: find the first space outside quotes.
		end := findOptionsEnd(rest)
		if end < 0 {
			return nil
		}
		optsStr = rest[:end]
		rest = rest[end+1:]
	}
	// rest is "<keytype> <base64>[ <comment>]"
	sp := strings.IndexByte(rest, ' ')
	if sp < 0 {
		return nil
	}
	keyTypeTok := rest[:sp]
	if !knownBlobTypes[keyTypeTok] {
		return nil
	}
	rest = rest[sp+1:]
	blobTok := rest
	comment := ""
	hasCommentField := false
	if sp2 := strings.IndexByte(rest, ' '); sp2 >= 0 {
		blobTok = rest[:sp2]
		after := rest[sp2+1:]
		hasCommentField = true
		if sp3 := strings.IndexByte(after, ' '); sp3 >= 0 {
			comment = after[:sp3]
		} else {
			comment = after
		}
	}
	decoded, err := base64.StdEncoding.DecodeString(blobTok)
	if err != nil {
		return nil
	}
	// The blob's internal type must equal the token.
	parsed := parsePubkeyBlobTypeOnly(decoded)
	if parsed != keyTypeTok {
		return nil
	}
	if !bytes.Equal(decoded, offered.blob) {
		return nil
	}
	// Key matches: now parse options.
	opts := defaultAuthKeyOptions()
	if optsStr != "" {
		if !parseAuthKeyOptions(optsStr, opts) {
			dbLog("Bad public key options at %s:%d", filename, lineno)
			return nil
		}
	}
	m := &authorizedMatch{opts: opts}
	if hasCommentField && comment != "" {
		m.info = comment
		m.hasInfo = true
	} else if hasCommentField && comment == "" {
		// Empty comment token (double space): no info.
		m.hasInfo = false
	}
	return m
}

func parsePubkeyBlobTypeOnly(blob []byte) string {
	b := newBuffer(blob)
	var t string
	func() {
		defer func() { _ = recover() }()
		t = b.getStringStr()
	}()
	return t
}

// findOptionsEnd returns the index of the first space not inside a
// quoted string, or -1.
func findOptionsEnd(s string) int {
	inQuote := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inQuote = false
			}
			continue
		}
		if c == '"' {
			inQuote = true
			continue
		}
		if c == ' ' {
			return i
		}
	}
	return -1
}

// parseAuthKeyOptions parses a comma-separated options string into
// opts, logging recognised flags as the original does. Returns false
// on a malformed/unknown option.
func parseAuthKeyOptions(s string, opts *authKeyOptions) bool {
	i := 0
	matchName := func(name string) bool {
		if len(s)-i >= len(name) && strings.EqualFold(s[i:i+len(name)], name) {
			return true
		}
		return false
	}
	for i < len(s) {
		if s[i] == ',' {
			i++
			continue
		}
		switch {
		case matchName("command="):
			i += len("command=")
			v, ni, ok, badly := parseQuotedValue(s, i)
			if badly {
				dbLog("Badly formatted command= authorized_keys option")
			}
			if !ok {
				return false
			}
			i = ni
			vv := v
			opts.forcedCmd = &vv
		case matchName("permitopen="):
			i += len("permitopen=")
			v, ni, ok, _ := parseQuotedValue(s, i)
			if !ok {
				return false
			}
			i = ni
			po, valid := parsePermitOpen(v)
			if !valid {
				dbLog("Badly formatted permitopen= authorized_keys option")
				return false
			}
			opts.permitOpens = append(opts.permitOpens, po)
			opts.hasPermitOpens = true
		case matchName("no-pty"):
			dbLog("Pty allocation disabled.")
			opts.noPty = true
			i += len("no-pty")
		case matchName("no-port-forwarding"):
			dbLog("Port forwarding disabled.")
			opts.noPortForwarding = true
			i += len("no-port-forwarding")
		case matchName("no-agent-forwarding"):
			dbLog("Agent forwarding disabled.")
			opts.noAgentForwarding = true
			i += len("no-agent-forwarding")
		case matchName("no-x11-forwarding"):
			opts.noX11Forwarding = true
			i += len("no-x11-forwarding")
		case matchName("no-touch-required"):
			dbLog("No user presence check required for U2F/FIDO key.")
			opts.noTouchRequired = true
			i += len("no-touch-required")
		case matchName("verify-required"):
			dbLog("User verification required for U2F/FIDO key.")
			opts.verifyRequired = true
			i += len("verify-required")
		case matchName("restrict"):
			dbLog("Restrict option set")
			opts.restrict = true
			opts.noPty = true
			opts.noPortForwarding = true
			opts.noAgentForwarding = true
			opts.noX11Forwarding = true
			opts.noTouchRequired = true
			i += len("restrict")
		default:
			return false
		}
		// After an option, expect comma or end.
		if i < len(s) {
			if s[i] == ',' {
				i++
				continue
			}
			return false
		}
	}
	return true
}

// parseQuotedValue parses a quoted string starting at s[i] which must
// be '"'. Returns value, next index, ok, badlyFormatted (unterminated).
func parseQuotedValue(s string, i int) (string, int, bool, bool) {
	if i >= len(s) || s[i] != '"' {
		return "", i, false, false
	}
	i++
	var sb strings.Builder
	for i < len(s) {
		c := s[i]
		if c == '\\' {
			if i+1 >= len(s) {
				return "", i, false, true
			}
			sb.WriteByte(s[i+1])
			i += 2
			continue
		}
		if c == '"' {
			return sb.String(), i + 1, true, false
		}
		sb.WriteByte(c)
		i++
	}
	return "", i, false, true
}

func parsePermitOpen(v string) (permitOpen, bool) {
	// Use the same bracket/colon rules as -p parsing without fatals.
	var host, port string
	if strings.HasPrefix(v, "[") {
		idx := strings.Index(v, "]")
		if idx < 0 || idx+1 >= len(v) || v[idx+1] != ':' {
			return permitOpen{}, false
		}
		host = v[1:idx]
		port = v[idx+2:]
		// Host as matched against channel target is the bracketed form
		// text? Channel targets for IPv6 arrive without brackets, and
		// the original stores the address text inside brackets.
		// Keep host as-is inside brackets.
	} else {
		last := strings.LastIndex(v, ":")
		if last < 0 {
			return permitOpen{}, false
		}
		host = v[:last]
		port = v[last+1:]
	}
	if host == "" || port == "" {
		return permitOpen{}, false
	}
	if port != "*" {
		for _, c := range port {
			if c < '0' || c > '9' {
				return permitOpen{}, false
			}
		}
	}
	return permitOpen{host: host, port: port}, true
}
