// ---------- user checking ----------

func (s *sshConn) checkUser(username string) bool {
	if s.userChecked && s.username == username {
		return s.userValid
	}
	s.username = username
	s.userChecked = true
	s.userValid = false
	s.exitUser = ""
	pw := lookupUser(username)
	if pw == nil {
		dbLog("Login attempt for nonexistent user from %s", s.remoteAddr)
		s.pw = nil
		return false
	}
	s.pw = pw
	s.exitUser = username
	if os.Geteuid() != 0 && pw.UID != os.Geteuid() {
		dbLog("Login attempt with wrong user %s from %s", username, s.remoteAddr)
		return false
	}
	if s.opts.noRootLogin && pw.UID == 0 {
		dbLog("root login rejected")
		return false
	}
	if s.opts.groupName != nil {
		g := lookupGroup(*s.opts.groupName)
		member := false
		if g != nil {
			if pw.GID == g.GID {
				member = true
			}
			for _, m := range g.Members {
				if m == username {
					member = true
				}
			}
		}
		if !member {
			dbLog("Logins are restricted to the group %s but user '%s' is not a member", *s.opts.groupName, username)
			return false
		}
	}
	shell := pw.Shell
	if shell == "" {
		shell = "/bin/sh"
	}
	s.shell = shell
	valid := false
	for _, sh := range validShells() {
		if sh == shell {
			valid = true
			break
		}
	}
	if !valid {
		dbLog("User '%s' has invalid shell, rejected", username)
		return false
	}
	s.userValid = true
	return true
}

// ---------- auth failure / success plumbing ----------

func (s *sshConn) authMethodsList() []string {
	if s.opts.twoFactor {
		if s.factorsDone["publickey"] && !s.factorsDone["password"] {
			return []string{"password"}
		}
		if s.factorsDone["password"] && !s.factorsDone["publickey"] {
			return []string{"publickey"}
		}
	}
	methods := []string{"publickey"}
	if !s.opts.disablePass {
		methods = append(methods, "password")
	}
	return methods
}

func (s *sshConn) sendAuthFailure(partial bool) {
	var p []byte
	p = append(p, 51)
	p = appendString(p, []byte(strings.Join(s.authMethodsList(), ",")))
	if partial {
		p = append(p, 1)
	} else {
		p = append(p, 0)
	}
	s.writePacketOrFatal(p)
}

func authFailureDelay() {
	d := 250 + mrand.Intn(100)
	time.Sleep(time.Duration(d) * time.Millisecond)
}

// countedFailure registers a failed auth attempt, delays, and
// terminates the connection if the limit has been exceeded. It
// returns normally if the caller should send an auth failure.
func (s *sshConn) countedFailure() {
	s.authFails++
	if uint32(s.authFails) > s.opts.maxAuthTries {
		authFailureDelay()
		fatalf("Max auth tries reached - user '%s'", s.username)
	}
}

func (s *sshConn) countedFailureWithDelay() {
	s.countedFailureNoDelay()
	authFailureDelay()
}
func (s *sshConn) countedFailureNoDelay() {
	s.authFails++
	if uint32(s.authFails) > s.opts.maxAuthTries {
		authFailureDelay()
		fatalf("Max auth tries reached - user '%s'", s.username)
	}
}

// succeedFactor records a successful auth factor. It returns true if
// authentication is now complete (and the success packet was sent).
// logLine is the already-formatted success message without any
// "extra auth required" suffix.
func (s *sshConn) succeedFactor(method, logLine string) bool {
	if s.opts.twoFactor && !s.factorsDone[otherFactor(method)] {
		s.factorsDone[method] = true
		dbLog("%s, extra auth required", logLine)
		s.sendAuthFailure(true)
		return false
	}
	s.factorsDone[method] = true
	dbLog("%s", logLine)
	s.authDone = true
	// Notify the parent that we are authenticated.
	if s.unauth != nil {
		s.unauth.Close()
		s.unauth = nil
	}
	s.writePacketOrFatal([]byte{52})
	s.activateDelayedCompression()
	// Switch effective identity to the user when running as root.
	s.switchToUser()
	s.pc.lastDataNano.Store(time.Now().UnixNano())
	return true
}

func otherFactor(m string) string {
	if m == "publickey" {
		return "password"
	}
	return "publickey"
}

func (s *sshConn) switchToUser() {
	if os.Geteuid() != 0 || s.pw == nil {
		return
	}
	// Retain saved root uid so session children can regain it for
	// pty/lastlog setup: use seteuid/setegid and set groups.
	groups := userGroupList(s.pw.Name, s.pw.GID)
	syscall.Setgroups(groups)
	syscall.Setegid(s.pw.GID)
	syscall.Seteuid(s.pw.UID)
}

// withUserEUID runs fn with the effective uid/gid of pw when root.
func withUserEUID(pw *passwdInfo, fn func()) {
	if os.Getuid() != 0 || os.Geteuid() != 0 {
		// Already switched (post-auth) or not root: fn directly, but
		// note Getuid()==0 check above means real uid root: when we
		// have seteuid'd, euid != 0; regain for the switch logic
		// below only in pre-auth root processes.
		if os.Getuid() != 0 {
			fn()
			return
		}
	}
	if os.Geteuid() == pw.UID {
		fn()
		return
	}
	oldGid := syscall.Getegid()
	syscall.Setegid(pw.GID)
	syscall.Seteuid(pw.UID)
	fn()
	syscall.Seteuid(0)
	syscall.Setegid(oldGid)
}

// ---------- main auth loop ----------

func (s *sshConn) doAuth() {
	// Default key options.
	s.keyOpts = defaultAuthKeyOptions()
	for {
		payload := s.expectPacket([]byte{50}, true)
		if !s.bannerSent {
			s.bannerSent = true
			if s.opts.bannerLoaded {
				var p []byte
				p = append(p, 53)
				p = appendString(p, s.opts.banner)
				p = appendString(p, []byte{})
				s.writePacketOrFatal(p)
			}
		}
		if s.handleAuthRequest(payload) {
			return
		}
	}
}

// handleAuthRequest returns true when authentication completed.
func (s *sshConn) handleAuthRequest(payload []byte) bool {
	b := newBuffer(payload)
	b.getByte()
	username := cstr(b.getStringStr())
	_ = b.getStringStr() // service
	method := cstr(b.getStringStr())

	valid := s.checkUser(username)

	switch method {
	case "none":
		s.sendAuthFailure(false)
		return false
	case "password":
		if s.opts.disablePass {
			s.sendAuthFailure(false)
			return false
		}
		return s.authPassword(b, valid)
	case "publickey":
		return s.authPubkey(b, valid)
	default:
		s.sendAuthFailure(false)
		return false
	}
}

// ---------- password auth ----------

func (s *sshConn) authPassword(b *buffer, valid bool) bool {
	change := b.getBool()
	password := cstr(b.getStringStr())
	if change {
		// A new-password field follows; password changes are not
		// supported, consume it and fail as a bad attempt.
		_ = b.getStringStr()
		if valid {
			s.countedFailureWithDelay()
		} else {
			s.countedFailureWithDelay()
		}
		s.sendAuthFailure(false)
		return false
	}
	if !valid {
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	if s.pw.UID == 0 && s.opts.disableRootPw {
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	encPass := s.pw.Pass
	if encPass == "x" {
		if sh, ok := lookupShadow(s.pw.Name); ok {
			encPass = sh
		}
	}
	if encPass == "" {
		if !s.opts.blankPass {
			dbLog("User '%s' has blank password, rejected", s.username)
			s.countedFailureWithDelay()
			s.sendAuthFailure(false)
			return false
		}
		// Blank password account: any password succeeds.
		s.applyPasswordAuthSettings()
		return s.succeedFactor("password", fmt.Sprintf("Auth succeeded with blank password for '%s' from %s", s.username, s.remoteAddr))
	}
	computed := cryptPassword(password, encPass)
	if computed == "" || computed != encPass {
		dbLog("Bad password attempt for '%s' from %s", s.username, s.remoteAddr)
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	s.applyPasswordAuthSettings()
	return s.succeedFactor("password", fmt.Sprintf("Password auth succeeded for '%s' from %s", s.username, s.remoteAddr))
}

func (s *sshConn) applyPasswordAuthSettings() {
	// A final password authentication clears pubkey-derived settings,
	// mirroring the reference behaviour with two-factor auth.
	s.keyOpts = defaultAuthKeyOptions()
	s.pubkeyInfo = ""
	s.hasInfo = false
}

// ---------- public key auth ----------

func (s *sshConn) authPubkey(b *buffer, valid bool) bool {
	hasSig := b.getBool()
	reqAlgo := cstr(b.getStringStr())
	keyBlob := b.getString()
	if !valid {
		// Pubkey queries/signed attempts for invalid users fail
		// without counting (signed attempts cannot arrive from
		// compliant clients because the query is rejected).
		s.sendAuthFailure(false)
		return false
	}
	if !supportedPubkeyAlgo(reqAlgo) {
		s.sendAuthFailure(false)
		return false
	}
	offered := parsePubkeyBlobSafe(keyBlob)
	if offered == nil {
		s.sendAuthFailure(false)
		return false
	}
	// The request algorithm must match the blob format.
	if !pubkeyAlgoMatchesBlob(reqAlgo, offered) {
		s.sendAuthFailure(false)
		return false
	}
	match := s.lookupAuthorizedKey(offered)
	if match == nil {
		s.sendAuthFailure(false)
		return false
	}
	if !hasSig {
		// Query: reply PK_OK.
		var p []byte
		p = append(p, 60)
		p = appendString(p, []byte(reqAlgo))
		p = appendString(p, keyBlob)
		s.writePacketOrFatal(p)
		return false
	}
	sigBlob := b.getString()
	// Build the data that was signed.
	var signed []byte
	signed = appendString(signed, s.sessionID)
	signed = append(signed, 50)
	signed = appendString(signed, []byte(s.username))
	signed = appendString(signed, []byte("ssh-connection"))
	signed = appendString(signed, []byte("publickey"))
	signed = append(signed, 1)
	signed = appendString(signed, []byte(reqAlgo))
	signed = appendString(signed, keyBlob)

	if !verifyPubkeySignature(offered, signed, sigBlob, match.opts) {
		dbLog("Pubkey auth bad signature for '%s' with key SHA256:%s from %s", s.username, offered.fingerprint(), s.remoteAddr)
		s.countedFailureWithDelay()
		s.sendAuthFailure(false)
		return false
	}
	// Success: apply options from this authorized_keys line.
	s.keyOpts = match.opts
	s.pubkeyInfo = match.info
	s.hasInfo = match.hasInfo
	return s.succeedFactor("publickey", fmt.Sprintf("Pubkey auth succeeded for '%s' with %s key SHA256:%s from %s", s.username, offered.keyTypeString(), offered.fingerprint(), s.remoteAddr))
}

func supportedPubkeyAlgo(algo string) bool {
	switch algo {
	case "ssh-ed25519", "sk-ssh-ed25519@openssh.com",
		"ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521",
		"sk-ecdsa-sha2-nistp256@openssh.com", "rsa-sha2-256":
		return true
	}
	return false
}

func pubkeyAlgoMatchesBlob(reqAlgo string, pk *pubKey) bool {
	if reqAlgo == "rsa-sha2-256" {
		return pk.algo == "ssh-rsa"
	}
	return reqAlgo == pk.algo
}

func parsePubkeyBlobSafe(blob []byte) (pk *pubKey) {
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(*fatalError); ok {
				pk = nil
				return
			}
			panic(r)
		}
	}()
	return parsePubkeyBlob(blob)
}

func verifyPubkeySignature(pk *pubKey, signedData, sigBlob []byte, opts *authKeyOptions) bool {
	b := newBuffer(sigBlob)
	var sigAlgo string
	var sig []byte
	ok := func() (ok bool) {
		defer func() {
			if r := recover(); r != nil {
				ok = false
			}
		}()
		sigAlgo = b.getStringStr()
		sig = b.getString()
		return true
	}()
	if !ok {
		return false
	}
	if pk.isSK {
		return verifySKSignature(pk, signedData, sigAlgo, sig, opts)
	}
	defer func() { _ = recover() }()
	return pk.verifyWithAlgoWrapped(signedData, sigAlgo, sig)
}

func (p *pubKey) verifyWithAlgoWrapped(data []byte, sigAlgo string, sig []byte) (ret bool) {
	defer func() {
		if r := recover(); r != nil {
			ret = false
		}
	}()
	return p.verifyWithAlgo(data, sigAlgo, sig, nil)
}

func verifySKSignature(pk *pubKey, signedData []byte, sigAlgo string, sig []byte, opts *authKeyOptions) bool {
	if sigAlgo != pk.algo {
		return false
	}
	// sig content: string signature, byte flags, uint32 counter
	b := newBuffer(sig)
	var rawSig []byte
	var flags byte
	var counter uint32
	okParse := func() (ok bool) {
		defer func() {
			if r := recover(); r != nil {
				ok = false
			}
		}()
		rawSig = b.getString()
		flags = b.getByte()
		counter = b.getUint32()
		return true
	}()
	if !okParse {
		return false
	}
	if opts != nil {
		if !opts.noTouchRequired && flags&0x01 == 0 {
			return false
		}
		if opts.verifyRequired && flags&0x04 == 0 {
			return false
		}
	}
	appHash := sha256.Sum256([]byte(pk.skApp))
	challengeHash := sha256.Sum256(signedData)
	var msg []byte
	msg = append(msg, appHash[:]...)
	msg = append(msg, flags)
	var ctr [4]byte
	ctr[0] = byte(counter >> 24)
	ctr[1] = byte(counter >> 16)
	ctr[2] = byte(counter >> 8)
	ctr[3] = byte(counter)
	msg = append(msg, ctr[:]...)
	msg = append(msg, challengeHash[:]...)
	// Verify using the underlying plain key over msg with rawSig.
	plain := *pk
	plain.isSK = false
	if pk.typ == keyEd25519 {
		plain.algo = "ssh-ed25519"
		return plain.verifyWithAlgo(msg, "ssh-ed25519", rawSig, nil)
	}
	// ECDSA: rawSig is (mpint r || mpint s) encoded content.
	plain.algo = "ecdsa-sha2-nistp256"
	return plain.verifyWithAlgo(msg, "ecdsa-sha2-nistp256", rawSig, nil)
}

