// ---------- authorized_keys ----------

type authKeyOptions struct {
	noPty            bool
	noPortForwarding bool
	noAgentForwarding bool
	noX11Forwarding  bool
	noTouchRequired  bool
	verifyRequired   bool
	restrict         bool
	forcedCmd        *string
	permitOpens      []permitOpen
	hasPermitOpens   bool
}

type permitOpen struct {
	host string
	port string
}

func defaultAuthKeyOptions() *authKeyOptions {
	return &authKeyOptions{}
}

type authorizedMatch struct {
	opts    *authKeyOptions
	info    string
	hasInfo bool
}

func (s *sshConn) authorizedKeysPath() string {
	if s.opts.authDir != nil {
		return *s.opts.authDir + "/authorized_keys"
	}
	return s.pw.Home + "/.ssh/authorized_keys"
}

// checkPubkeyPerms verifies directory ownership/permissions for the
// authorized_keys file. Returns true if acceptable.
func (s *sshConn) checkPubkeyPerms(filename string) bool {
	dir := filepath.Dir(filename)
	// Collect directories from the file's directory up to the user's
	// home (inclusive), or to the root if not under home.
	var dirs []string
	d := dir
	for {
		dirs = append(dirs, d)
		if d == s.pw.Home {
			break
		}
		parent := filepath.Dir(d)
		if parent == d {
			break
		}
		d = parent
	}
	for _, dd := range dirs {
		fi, err := os.Stat(dd)
		if err != nil {
			return false
		}
		st, ok := fi.Sys().(*syscall.Stat_t)
		if !ok {
			continue
		}
		if (int(st.Uid) != s.pw.UID && st.Uid != 0) || fi.Mode().Perm()&0022 != 0 {
			dbLog("%s must be owned by user or root, and not writable by group or others", dd)
			return false
		}
	}
	return true
}

func (s *sshConn) lookupAuthorizedKey(offered *pubKey) *authorizedMatch {
	filename := s.authorizedKeysPath()
	var data []byte
	var permsOk bool
	withUserEUID(s.pw, func() {
		if !s.checkPubkeyPerms(filename) {
			permsOk = false
			return
		}
		permsOk = true
		data, _ = os.ReadFile(filename)
	})
	if !permsOk || data == nil {
		return nil
	}
	lines := splitAuthorizedLines(string(data))
	for idx, line := range lines {
		m := s.matchAuthorizedLine(line, offered, filename, idx+1)
		if m != nil {
			return m
		}
	}
	return nil
}

// splitAuthorizedLines splits file content into lines, discarding
// lines longer than 4200 bytes (including the newline).
func splitAuthorizedLines(content string) []string {
	var out []string
	for len(content) > 0 {
		nl := strings.IndexByte(content, '\n')
		var line string
		if nl < 0 {
			line = content
			content = ""
			if len(line) > 4200 {
				continue
			}
			out = append(out, line)
		} else {
			line = content[:nl+1]
			content = content[nl+1:]
			if len(line) > 4200 {
				continue
			}
			out = append(out, strings.TrimSuffix(strings.TrimSuffix(line, "\n"), "\r"))
		}
	}
	return out
}

var knownBlobTypes = map[string]bool{
	"ssh-rsa": true, "ssh-dss": true, "ssh-ed25519": true,
	"ecdsa-sha2-nistp256": true, "ecdsa-sha2-nistp384": true, "ecdsa-sha2-nistp521": true,
	"sk-ssh-ed25519@openssh.com": true, "sk-ecdsa-sha2-nistp256@openssh.com": true,
}

func (s *sshConn) matchAuthorizedLine(line string, offered *pubKey, filename string, lineno int) *authorizedMatch {
	if line == "" || line[0] == '#' {
		return nil
	}
	rest := line
	optsStr := ""
	// If first token is a known key type, there are no options.
	firstSpace := strings.IndexByte(rest, ' ')
	if firstSpace < 0 {
		return nil
	}
	firstTok := rest[:firstSpace]
	if !knownBlobTypes[firstTok] {
		// Options field: find the first space outside quotes.
		end := findOptionsEnd(rest)
		if end < 0 {
			return nil
		}
		optsStr = rest[:end]
		rest = rest[end+1:]
	}
	// rest is "<keytype> <base64>[ <comment>]"
	sp := strings.IndexByte(rest, ' ')
	if sp < 0 {
		return nil
	}
	keyTypeTok := rest[:sp]
	if !knownBlobTypes[keyTypeTok] {
		return nil
	}
	rest = rest[sp+1:]
	blobTok := rest
	comment := ""
	hasCommentField := false
	if sp2 := strings.IndexByte(rest, ' '); sp2 >= 0 {
		blobTok = rest[:sp2]
		after := rest[sp2+1:]
		hasCommentField = true
		if sp3 := strings.IndexByte(after, ' '); sp3 >= 0 {
			comment = after[:sp3]
		} else {
			comment = after
		}
	}
	decoded, err := base64.StdEncoding.DecodeString(blobTok)
	if err != nil {
		return nil
	}
	// The blob's internal type must equal the token.
	parsed := parsePubkeyBlobTypeOnly(decoded)
	if parsed != keyTypeTok {
		return nil
	}
	if !bytes.Equal(decoded, offered.blob) {
		return nil
	}
	// Key matches: now parse options.
	opts := defaultAuthKeyOptions()
	if optsStr != "" {
		if !parseAuthKeyOptions(optsStr, opts) {
			dbLog("Bad public key options at %s:%d", filename, lineno)
			return nil
		}
	}
	m := &authorizedMatch{opts: opts}
	if hasCommentField && comment != "" {
		m.info = comment
		m.hasInfo = true
	} else if hasCommentField && comment == "" {
		// Empty comment token (double space): no info.
		m.hasInfo = false
	}
	return m
}

func parsePubkeyBlobTypeOnly(blob []byte) string {
	b := newBuffer(blob)
	var t string
	func() {
		defer func() { _ = recover() }()
		t = b.getStringStr()
	}()
	return t
}

// findOptionsEnd returns the index of the first space not inside a
// quoted string, or -1.
func findOptionsEnd(s string) int {
	inQuote := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inQuote = false
			}
			continue
		}
		if c == '"' {
			inQuote = true
			continue
		}
		if c == ' ' {
			return i
		}
	}
	return -1
}

// parseAuthKeyOptions parses a comma-separated options string into
// opts, logging recognised flags as the original does. Returns false
// on a malformed/unknown option.
func parseAuthKeyOptions(s string, opts *authKeyOptions) bool {
	i := 0
	matchName := func(name string) bool {
		if len(s)-i >= len(name) && strings.EqualFold(s[i:i+len(name)], name) {
			return true
		}
		return false
	}
	for i < len(s) {
		if s[i] == ',' {
			i++
			continue
		}
		switch {
		case matchName("command="):
			i += len("command=")
			v, ni, ok, badly := parseQuotedValue(s, i)
			if badly {
				dbLog("Badly formatted command= authorized_keys option")
			}
			if !ok {
				return false
			}
			i = ni
			vv := v
			opts.forcedCmd = &vv
		case matchName("permitopen="):
			i += len("permitopen=")
			v, ni, ok, _ := parseQuotedValue(s, i)
			if !ok {
				return false
			}
			i = ni
			po, valid := parsePermitOpen(v)
			if !valid {
				dbLog("Badly formatted permitopen= authorized_keys option")
				return false
			}
			opts.permitOpens = append(opts.permitOpens, po)
			opts.hasPermitOpens = true
		case matchName("no-pty"):
			dbLog("Pty allocation disabled.")
			opts.noPty = true
			i += len("no-pty")
		case matchName("no-port-forwarding"):
			dbLog("Port forwarding disabled.")
			opts.noPortForwarding = true
			i += len("no-port-forwarding")
		case matchName("no-agent-forwarding"):
			dbLog("Agent forwarding disabled.")
			opts.noAgentForwarding = true
			i += len("no-agent-forwarding")
		case matchName("no-x11-forwarding"):
			opts.noX11Forwarding = true
			i += len("no-x11-forwarding")
		case matchName("no-touch-required"):
			dbLog("No user presence check required for U2F/FIDO key.")
			opts.noTouchRequired = true
			i += len("no-touch-required")
		case matchName("verify-required"):
			dbLog("User verification required for U2F/FIDO key.")
			opts.verifyRequired = true
			i += len("verify-required")
		case matchName("restrict"):
			dbLog("Restrict option set")
			opts.restrict = true
			opts.noPty = true
			opts.noPortForwarding = true
			opts.noAgentForwarding = true
			opts.noX11Forwarding = true
			opts.noTouchRequired = true
			i += len("restrict")
		default:
			return false
		}
		// After an option, expect comma or end.
		if i < len(s) {
			if s[i] == ',' {
				i++
				continue
			}
			return false
		}
	}
	return true
}

// parseQuotedValue parses a quoted string starting at s[i] which must
// be '"'. Returns value, next index, ok, badlyFormatted (unterminated).
func parseQuotedValue(s string, i int) (string, int, bool, bool) {
	if i >= len(s) || s[i] != '"' {
		return "", i, false, false
	}
	i++
	var sb strings.Builder
	for i < len(s) {
		c := s[i]
		if c == '\\' {
			if i+1 >= len(s) {
				return "", i, false, true
			}
			sb.WriteByte(s[i+1])
			i += 2
			continue
		}
		if c == '"' {
			return sb.String(), i + 1, true, false
		}
		sb.WriteByte(c)
		i++
	}
	return "", i, false, true
}

func parsePermitOpen(v string) (permitOpen, bool) {
	// Use the same bracket/colon rules as -p parsing without fatals.
	var host, port string
	if strings.HasPrefix(v, "[") {
		idx := strings.Index(v, "]")
		if idx < 0 || idx+1 >= len(v) || v[idx+1] != ':' {
			return permitOpen{}, false
		}
		host = v[1:idx]
		port = v[idx+2:]
		// Host as matched against channel target is the bracketed form
		// text? Channel targets for IPv6 arrive without brackets, and
		// the original stores the address text inside brackets.
		// Keep host as-is inside brackets.
	} else {
		last := strings.LastIndex(v, ":")
		if last < 0 {
			return permitOpen{}, false
		}
		host = v[:last]
		port = v[last+1:]
	}
	if host == "" || port == "" {
		return permitOpen{}, false
	}
	if port != "*" {
		for _, c := range port {
			if c < '0' || c > '9' {
				return permitOpen{}, false
			}
		}
	}
	return permitOpen{host: host, port: port}, true
}
