package main

import (
	"encoding/binary"
	"fmt"
	"io"
	"net"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
)

type channel struct {
	localID  uint32
	remoteID uint32
	typ      string

	remoteWindow    int64
	remoteMaxPacket uint32
	winMu           sync.Mutex
	winCond         chan struct{} // recreated on window change

	mu         sync.Mutex
	sentEOF    bool
	sentClose  bool
	recvEOF    bool
	recvClose  bool
	sendMu     sync.Mutex // serialises data packets from output readers

	// data sink for client->server data
	inbound *inboundWriter

	// generic network connection (direct/forwarded/agent)
	netConn net.Conn

	// session-specific
	sess *sessionState

	conn *sshConn
}

type sessionState struct {
	ptyAllocated bool
	ptyMaster    *os.File
	ptySlave     *os.File
	ptyName      string
	term         string
	cols, rows   uint32
	widthPx      uint32
	heightPx     uint32

	agentRequested bool
	started        bool
	startedKind    string // "shell", "exec", "subsystem"

	cmd      *exec.Cmd
	procDone chan struct{}
	outDone  sync.WaitGroup
}

func (ch *channel) addWindow(n uint32) {
	ch.winMu.Lock()
	ch.remoteWindow += int64(n)
	if ch.winCond != nil {
		close(ch.winCond)
		ch.winCond = nil
	}
	ch.winMu.Unlock()
}

func (ch *channel) waitWindow(n int) bool {
	for {
		ch.winMu.Lock()
		if ch.sentClose || ch.recvClose {
			ch.winMu.Unlock()
			return false
		}
		if ch.remoteWindow >= int64(n) {
			ch.remoteWindow -= int64(n)
			ch.winMu.Unlock()
			return true
		}
		if ch.winCond == nil {
			ch.winCond = make(chan struct{})
		}
		cond := ch.winCond
		ch.winMu.Unlock()
		select {
		case <-cond:
		case <-ch.conn.done:
			return false
		}
	}
}

// outbound data to the client
func (ch *channel) sendData(ext bool, data []byte) {
	ch.sendMu.Lock()
	defer ch.sendMu.Unlock()
	for len(data) > 0 {
		n := len(data)
		maxP := int(ch.remoteMaxPacket)
		if maxP <= 0 || maxP > 32759 {
			maxP = 32759
		}
		// Leave room for packet header fields in max packet estimate.
		limit := maxP - 20
		if limit < 1024 {
			limit = maxP
		}
		if n > limit {
			n = limit
		}
		if !ch.waitWindow(n) {
			return
		}
		var p []byte
		if ext {
			p = append(p, 95)
			p = appendUint32(p, ch.remoteID)
			p = appendUint32(p, 1)
		} else {
			p = append(p, 94)
			p = appendUint32(p, ch.remoteID)
		}
		p = appendString(p, data[:n])
		if err := ch.conn.pc.writePacket(p); err != nil {
			return
		}
		data = data[n:]
	}
}

func (ch *channel) sendEOF() {
	ch.mu.Lock()
	if ch.sentEOF || ch.sentClose {
		ch.mu.Unlock()
		return
	}
	ch.sentEOF = true
	ch.mu.Unlock()
	var p []byte
	p = append(p, 96)
	p = appendUint32(p, ch.remoteID)
	ch.conn.pc.writePacket(p)
}

func (ch *channel) sendClose() {
	ch.mu.Lock()
	if ch.sentClose {
		ch.mu.Unlock()
		return
	}
	ch.sentClose = true
	ch.mu.Unlock()
	// Wake any window waiters.
	ch.winMu.Lock()
	if ch.winCond != nil {
		close(ch.winCond)
		ch.winCond = nil
	}
	ch.winMu.Unlock()
	var p []byte
	p = append(p, 97)
	p = appendUint32(p, ch.remoteID)
	ch.conn.pc.writePacket(p)
}

func (ch *channel) sendWindowAdjust(n int) {
	if n <= 0 {
		return
	}
	ch.mu.Lock()
	closed := ch.sentClose || ch.recvClose
	ch.mu.Unlock()
	if closed {
		return
	}
	var p []byte
	p = append(p, 93)
	p = appendUint32(p, ch.remoteID)
	p = appendUint32(p, uint32(n))
	ch.conn.pc.writePacket(p)
}

func (ch *channel) killProcess() {
	if ch.sess != nil && ch.sess.cmd != nil && ch.sess.cmd.Process != nil {
		// Kill the whole process group for PTY sessions (own session),
		// else just the process and its group == connection group, so
		// signal the process directly to avoid killing ourselves.
		if ch.sess.ptyAllocated {
			syscall.Kill(-ch.sess.cmd.Process.Pid, syscall.SIGHUP)
		} else {
			ch.sess.cmd.Process.Signal(syscall.SIGHUP)
		}
	}
	if ch.netConn != nil {
		ch.netConn.Close()
	}
	if ch.inbound != nil {
		ch.inbound.Close()
	}
}

// ---------- inbound queue ----------

type inboundWriter struct {
	ch     chan []byte
	done   chan struct{}
	once   sync.Once
	dest   io.Writer
	closer func()
	owner  *channel
	adjust bool
}

func newInboundWriter(owner *channel, dest io.Writer, closer func(), adjust bool) *inboundWriter {
	iw := &inboundWriter{ch: make(chan []byte, 64), done: make(chan struct{}), dest: dest, closer: closer, owner: owner, adjust: adjust}
	go iw.run()
	return iw
}

func (iw *inboundWriter) run() {
	for data := range iw.ch {
		// Write fully.
		off := 0
		for off < len(data) {
			n, err := iw.dest.Write(data[off:])
			off += n
			if err != nil {
				break
			}
		}
		if iw.adjust && off > 0 {
			iw.owner.sendWindowAdjust(off)
		}
	}
	if iw.closer != nil {
		iw.closer()
	}
	close(iw.done)
}

func (iw *inboundWriter) Write(data []byte) {
	cp := append([]byte(nil), data...)
	select {
	case iw.ch <- cp:
	case <-iw.done:
	}
}

func (iw *inboundWriter) Close() {
	iw.once.Do(func() { close(iw.ch) })
}

// ---------- packet dispatch (post-auth) ----------

func (s *sshConn) handlePacket(payload []byte) {
	if len(payload) == 0 {
		return
	}
	switch payload[0] {
	case 80:
		s.handleGlobalRequest(payload)
	case 90:
		s.handleChannelOpen(payload)
	case 91, 92:
		s.handleChannelOpenResponse(payload)
	case 93:
		b := newBuffer(payload)
		b.getByte()
		id := b.getUint32()
		add := b.getUint32()
		if ch := s.getChannel(id); ch != nil {
			ch.addWindow(add)
		}
	case 94, 95:
		ext := payload[0] == 95
		b := newBuffer(payload)
		b.getByte()
		id := b.getUint32()
		if ext {
			b.getUint32() // data type code
		}
		data := b.getString()
		if ch := s.getChannel(id); ch != nil && ch.inbound != nil {
			ch.inbound.Write(data)
		}
		s.pc.lastDataNano.Store(time_NowNano())
	case 96:
		b := newBuffer(payload)
		b.getByte()
		id := b.getUint32()
		if ch := s.getChannel(id); ch != nil {
			ch.mu.Lock()
			ch.recvEOF = true
			ch.mu.Unlock()
			if ch.inbound != nil {
				ch.inbound.Close()
			}
		}
	case 97:
		b := newBuffer(payload)
		b.getByte()
		id := b.getUint32()
		if ch := s.getChannel(id); ch != nil {
			ch.mu.Lock()
			ch.recvClose = true
			ch.mu.Unlock()
			ch.killProcess()
			ch.sendClose()
			s.removeChannel(id)
		}
	case 98:
		s.handleChannelRequest(payload)
	default:
		// Unknown post-auth packet types are ignored by dropbear's
		// session loop (it logs/handles a fixed set); do nothing.
	}
}

func (s *sshConn) getChannel(id uint32) *channel {
	s.chanMu.Lock()
	defer s.chanMu.Unlock()
	return s.channels[id]
}

func (s *sshConn) removeChannel(id uint32) {
	s.chanMu.Lock()
	delete(s.channels, id)
	s.chanMu.Unlock()
}

func (s *sshConn) allocChannel(ch *channel) uint32 {
	s.chanMu.Lock()
	defer s.chanMu.Unlock()
	var id uint32
	for {
		if _, used := s.channels[id]; !used {
			break
		}
		id++
	}
	ch.localID = id
	s.channels[id] = ch
	return id
}

func (s *sshConn) channelCount() int {
	s.chanMu.Lock()
	defer s.chanMu.Unlock()
	return len(s.channels)
}

func (s *sshConn) sendOpenFailure(remoteID uint32, reason uint32, desc string) {
	var p []byte
	p = append(p, 92)
	p = appendUint32(p, remoteID)
	p = appendUint32(p, reason)
	p = appendString(p, []byte(desc))
	p = appendString(p, []byte{})
	s.writePacketOrFatal(p)
}

func (s *sshConn) sendOpenConfirmation(ch *channel) {
	var p []byte
	p = append(p, 91)
	p = appendUint32(p, ch.remoteID)
	p = appendUint32(p, ch.localID)
	p = appendUint32(p, s.opts.recvWindow)
	p = appendUint32(p, 32759)
	s.writePacketOrFatal(p)
}

// initiateChannel opens a server-initiated channel (forwarded/agent).
// extraData is the type-specific payload. Returns the channel once the
// client confirms, using the pending map below.
