	done chan bool
}

func (s *sshConn) handleChannelOpenResponse(payload []byte) {
	b := newBuffer(payload)
	msg := b.getByte()
	localID := b.getUint32() // our sender id from client's perspective = recipient in response
	ch := s.getChannel(localID)
	if ch == nil {
		return
	}
	if msg == 92 {
		// failure
		if ch.netConn != nil {
			ch.netConn.Close()
		}
		s.removeChannel(localID)
		ch.mu.Lock()
		ch.recvClose = true
		ch.mu.Unlock()
		if ch.openDone != nil {
			ch.openDone <- false
		}
		return
	}
	// confirmation: sender channel, window, max packet
	ch.remoteID = b.getUint32()
	ch.remoteWindow = int64(b.getUint32())
	ch.remoteMaxPacket = b.getUint32()
	if ch.openDone != nil {
		ch.openDone <- true
	}
}

// openServerChannel is used for forwarded-tcpip / auth-agent channels.
func (s *sshConn) openServerChannel(typ string, extra []byte, srcConn net.Conn) *channel {
	if s.channelCount() >= 1000 {
		return nil
	}
	ch := &channel{typ: typ, conn: s, netConn: srcConn, openDone: make(chan bool, 1)}
	s.allocChannel(ch)
	var p []byte
	p = append(p, 90)
	p = appendString(p, []byte(typ))
	p = appendUint32(p, ch.localID)
	p = appendUint32(p, s.opts.recvWindow)
	p = appendUint32(p, 32759)
	p = append(p, extra...)
	if err := s.pc.writePacket(p); err != nil {
		s.removeChannel(ch.localID)
		return nil
	}
	select {
	case ok := <-ch.openDone:
		if !ok {
			return nil
		}
	case <-s.done:
		return nil
	case <-time.After(10 * time.Second):
		return nil
	}
	// Wire up forwarding between srcConn and the channel.
	ch.inbound = newInboundWriter(ch, srcConn, func() {
		if tc, ok := srcConn.(interface{ CloseWrite() error }); ok {
			tc.CloseWrite()
		} else {
			srcConn.Close()
		}
	}, true)
	go func() {
		buf := make([]byte, 32768)
		for {
			n, err := srcConn.Read(buf)
			if n > 0 {
				ch.sendData(false, buf[:n])
			}
			if err != nil {
				ch.sendEOF()
				ch.sendClose()
				return
			}
		}
	}()
	return ch
}

