		ch := &channel{typ: chanType, remoteID: senderID, remoteWindow: int64(initWindow), remoteMaxPacket: maxPacket, conn: s}
		s.allocChannel(ch)
		go s.connectDirectTCP(ch, host, port)
	case "direct-streamlocal@openssh.com":
		path := b.getStringStr()
		_ = b.getStringStr() // originator (empty)
		_ = b.getUint32()    // reserved
		if s.opts.disableLocal || s.keyOpts.noPortForwarding || s.keyOpts.hasPermitOpens {
			s.sendOpenFailure(senderID, openAdminProhibited, "")
			return
		}
		conn, err := net.DialTimeout("unix", path, 10*time.Second)
		if err != nil {
			s.sendOpenFailure(senderID, openConnectFailed, strerror(err))
			return
		}
		ch := &channel{typ: chanType, remoteID: senderID, remoteWindow: int64(initWindow), remoteMaxPacket: maxPacket, conn: s, netConn: conn}
		s.allocChannel(ch)
		s.sendOpenConfirmation(ch)
		s.wireNetConnChannel(ch, conn)
	default:
		s.sendOpenFailure(senderID, openUnknownChanType, "")
	}
}

func permitOpenMatches(list []permitOpen, host string, port uint32) bool {
	for _, po := range list {
		if po.host != host {
			continue
		}
		if po.port == "*" {
			return true
		}
		if n, err := strconv.ParseUint(po.port, 10, 64); err == nil && n == uint64(port) {
			return true
		}
	}
	return false
}

func (s *sshConn) connectDirectTCP(ch *channel, host string, port uint32) {
	service := strconv.FormatUint(uint64(port), 10)
	addrs, err := resolveAddrInfo(host, service, false)
	if err != nil {
		s.removeChannel(ch.localID)
		s.sendOpenFailure(ch.remoteID, openConnectFailed, fmt.Sprintf("Error resolving '%s' port '%d'. %s", host, port, gaiErrorString(err)))
		return
	}
	var conn net.Conn
	var lastErr error
	for _, a := range addrs {
		ipStr := a.IP
		var addr string
		if a.Family == 10 {
			addr = "[" + ipStr + "]:" + strconv.Itoa(a.Port)
		} else {
			addr = ipStr + ":" + strconv.Itoa(a.Port)
		}
		c, err := net.DialTimeout("tcp", addr, 15*time.Second)
		if err != nil {
			lastErr = err
			continue
		}
		conn = c
		break
	}
	if conn == nil {
		s.removeChannel(ch.localID)
		// net.Dial errors wrap the errno; extract text after the last ": "
		msg := strerror(lastErr)
		s.sendOpenFailure(ch.remoteID, openConnectFailed, msg)
		return
	}
	// QoS: connection is a bulk/forwarded connection.
	s.applyQoS()
	ch.netConn = conn
	s.sendOpenConfirmation(ch)
	s.wireNetConnChannel(ch, conn)
}

// wireNetConnChannel sets up forwarding between a channel and a net.Conn.
func (s *sshConn) wireNetConnChannel(ch *channel, conn net.Conn) {
	ch.inbound = newInboundWriter(ch, conn, func() {
		if tc, ok := conn.(interface{ CloseWrite() error }); ok {
			tc.CloseWrite()
		} else {
			conn.Close()
		}
	}, true)
	go func() {
		buf := make([]byte, 32768)
		for {
			n, err := conn.Read(buf)
			if n > 0 {
				ch.sendData(false, buf[:n])
			}
			if err != nil {
				ch.sendEOF()
				ch.sendClose()
				return
			}
		}
	}()
}

func (s *sshConn) applyQoS() {
	// QoS marking is not directly observable in tests; the original
	// sets IP_TOS on the client socket. We keep default behaviour.
}

// ---------- global requests / remote forwarding ----------

type tcpForwardListener struct {
	bindAddr  string
	port      uint32
	listeners []net.Listener
}

func (s *sshConn) sendGlobalReply(success bool, payload []byte) {
	var p []byte
	if success {
		p = append(p, 81)
	} else {
		p = append(p, 82)
	}
	p = append(p, payload...)
	s.writePacketOrFatal(p)
}

func (s *sshConn) handleGlobalRequest(payload []byte) {
	b := newBuffer(payload)
	b.getByte()
	name := b.getStringStr()
	wantReply := b.getBool()
	switch name {
	case "tcpip-forward":
		bindAddr := b.getStringStr()
		port := b.getUint32()
		ok, allocPort := s.setupTCPForward(bindAddr, port)
		if wantReply {
			if ok {
				var extra []byte
				if port == 0 {
					extra = appendUint32(extra, uint32(allocPort))
				}
				s.sendGlobalReply(true, extra)
			} else {
				s.sendGlobalReply(false, nil)
			}
		}
	case "cancel-tcpip-forward":
		bindAddr := b.getStringStr()
		port := b.getUint32()
		ok := s.cancelTCPForward(bindAddr, port)
		if wantReply {
			s.sendGlobalReply(ok, nil)
		}
	default:
		if wantReply {
			s.sendGlobalReply(false, nil)
		}
	}
}

func forwardKey(bindAddr string, port uint32) string {
	return bindAddr + "\x00" + strconv.Itoa(int(port))
}

func (s *sshConn) setupTCPForward(bindAddr string, port uint32) (bool, int) {
	if s.opts.disableRemote || s.keyOpts.noPortForwarding {
		return false, 0
	}
	key := forwardKey(bindAddr, port)
	s.chanMu.Lock()
	// Re-use sshConn mutex fields via a dedicated check.
	s.chanMu.Unlock()
	if _, exists := s.tcpListeners[key]; exists {
		return false, 0
	}
	resolveHost := bindAddr
	passive := true
	if !s.opts.allowAnyHost {
		resolveHost = "localhost"
	} else if resolveHost == "*" {
		resolveHost = ""
	}
	service := strconv.FormatUint(uint64(port), 10)
	addrs, err := resolveAddrInfo(resolveHost, service, passive)
	if err != nil {
		return false, 0
	}
	// Deduplicate addresses and attempt to bind each.
	seen := map[string]bool{}
	fl := &tcpForwardListener{bindAddr: bindAddr, port: port}
	allocPort := 0
	for _, a := range addrs {
		k := fmt.Sprintf("%d/%s/%d", a.Family, a.IP, a.Port)
		if seen[k] {
			continue
		}
		seen[k] = true
		l, err := s.bindForwardListener(a, allocPort)
		if err != nil {
			continue
		}
		// Record allocated port so all families share it when port==0.
		if ta, ok := l.Addr().(*net.TCPAddr); ok && allocPort == 0 {
			allocPort = ta.Port
		}
		fl.listeners = append(fl.listeners, l)
	}
	if len(fl.listeners) == 0 {
		return false, 0
	}
	s.tcpListeners[key] = fl
	for _, l := range fl.listeners {
		go s.acceptForwarded(l)
	}
	if port != 0 {
		allocPort = int(port)
	}
	return true, allocPort
}

func (s *sshConn) bindForwardListener(a resolvedAddr, forcePort int) (net.Listener, error) {
	port := a.Port
	if forcePort != 0 {
		port = forcePort
	}
	// Reuse bindOne logic without interface binding by temporarily
	// constructing a listener through net.Listen with address.
	var addr string
	if a.Family == 10 {
		addr = "[" + a.IP + "]:" + strconv.Itoa(port)
	} else {
		addr = a.IP + ":" + strconv.Itoa(port)
	}
	lc, err := net.Listen("tcp", addr)
	if err != nil {
		return nil, err
	}
	return lc, nil
}

func (s *sshConn) cancelTCPForward(bindAddr string, port uint32) bool {
	key := forwardKey(bindAddr, port)
	fl, ok := s.tcpListeners[key]
	if !ok {
		return false
	}
	for _, l := range fl.listeners {
		l.Close()
	}
	delete(s.tcpListeners, key)
	return true
}

func (s *sshConn) acceptForwarded(l net.Listener) {
	for {
		conn, err := l.Accept()
		if err != nil {
			return
		}
		// Build forwarded-tcpip payload: string connected-host,
		// uint32 connected-port, string originator, uint32 originator port.
		local := formatAddr(conn.LocalAddr())
		remote := formatAddr(conn.RemoteAddr())
		lh, lp := splitAddrPort(local)
		rh, rp := splitAddrPort(remote)
		var extra []byte
		extra = appendString(extra, []byte(lh))
		extra = appendUint32(extra, uint32(lp))
		extra = appendString(extra, []byte(rh))
		extra = appendUint32(extra, uint32(rp))
		ch := s.openServerChannel("forwarded-tcpip", extra, conn)
		if ch == nil {
			conn.Close()
		}
	}
}

func splitAddrPort(s string) (string, int) {
	i := strings.LastIndex(s, ":")
	if i < 0 {
		return s, 0
	}
	p, _ := strconv.Atoi(s[i+1:])
	return s[:i], p
}
