import "C"

import "unsafe"

func applyTerminalModes(fd uintptr, modes []byte) {
	if len(modes) == 0 {
		return
	}
	C.apply_modes(C.int(fd), (*C.uchar)(unsafe.Pointer(&modes[0])), C.int(len(modes)))
