func (s *sshConn) sendChannelRequestReply(ch *channel, success bool) {
	var p []byte
	if success {
		p = append(p, 99)
	} else {
		p = append(p, 100)
	}
	p = appendUint32(p, ch.remoteID)
	s.writePacketOrFatal(p)
}

func (s *sshConn) handleChannelRequest(payload []byte) {
	b := newBuffer(payload)
	b.getByte()
	recipient := b.getUint32()
	reqType := b.getStringStr()
	wantReply := b.getBool()
	ch := s.getChannel(recipient)
	if ch == nil || ch.typ != "session" {
		// Dropbear only services requests on session channels; others
		// get a failure reply addressed to the sender's channel id.
		if wantReply {
			var p []byte
			p = append(p, 100)
			p = appendUint32(p, recipient)
			// Note: recipient here is the channel number as understood
			// by the sender; for unknown channels the original also
			// never gets here (it looks up by its own id). Use it.
			s.writePacketOrFatal(p)
		}
		return
	}
	sess := ch.sess
	reply := func(ok bool) {
		if wantReply {
			s.sendChannelRequestReply(ch, ok)
		}
	}

	switch reqType {
	case "pty-req":
		if sess.started || sess.ptyAllocated || s.keyOpts.noPty {
			reply(false)
			return
		}
		term := b.getStringStr()
		cols := b.getUint32()
		rows := b.getUint32()
		wpx := b.getUint32()
		hpx := b.getUint32()
		modes := b.getString()
		master, slave, name, err := openPTY()
		if err != nil {
			reply(false)
			return
		}
		sess.ptyMaster, sess.ptySlave, sess.ptyName = master, slave, name
		sess.term = cstr(term)
		sess.cols, sess.rows, sess.widthPx, sess.heightPx = cols, rows, wpx, hpx
		setWinSize(slave.Fd(), int(cols), int(rows), int(wpx), int(hpx))
		applyTerminalModes(slave.Fd(), modes)
		sess.ptyAllocated = true
		reply(true)
	case "window-change":
		if !sess.ptyAllocated {
			reply(false)
			return
		}
		cols := b.getUint32()
		rows := b.getUint32()
		wpx := b.getUint32()
		hpx := b.getUint32()
		sess.cols, sess.rows, sess.widthPx, sess.heightPx = cols, rows, wpx, hpx
		if sess.ptySlave != nil {
			setWinSize(sess.ptySlave.Fd(), int(cols), int(rows), int(wpx), int(hpx))
		} else if sess.ptyMaster != nil {
			setWinSize(sess.ptyMaster.Fd(), int(cols), int(rows), int(wpx), int(hpx))
		}
		if sess.cmd != nil && sess.cmd.Process != nil {
			// Notify foreground process group of the PTY session.
			syscall.Kill(-sess.cmd.Process.Pid, syscall.SIGWINCH)
		}
		reply(true)
	case "auth-agent-req@openssh.com":
		if s.keyOpts.noAgentForwarding {
			reply(false)
			return
		}
		if s.agentSockLn != nil {
			sess.agentRequested = true
			reply(true)
			return
		}
		if s.setupAgentForwarding() {
			sess.agentRequested = true
			reply(true)
		} else {
			reply(false)
		}
	case "shell":
		if sess.started {
			reply(false)
			return
		}
		ok := s.startSessionProcess(ch, "shell", "")
		reply(ok)
	case "exec":
		if sess.started {
			_ = b.getStringStr()
			reply(false)
			return
		}
		cmdStr := b.getStringStr()
		ok := s.startSessionProcess(ch, "exec", cmdStr)
		reply(ok)
	case "subsystem":
		name := b.getStringStr()
		if sess.started || name != "sftp" {
			reply(false)
			return
		}
		ok := s.startSessionProcess(ch, "subsystem", "/usr/libexec/sftp-server")
		reply(ok)
	case "signal":
		sigName := b.getStringStr()
		sig, ok := sshSignalByName(sigName)
		if !ok || !sess.started || sess.cmd == nil || sess.cmd.Process == nil {
			reply(false)
			return
		}
		if sess.ptyAllocated {
			syscall.Kill(-sess.cmd.Process.Pid, sig)
		} else {
			sess.cmd.Process.Signal(sig)
		}
		reply(true)
	default:
		reply(false)
	}
}

var sshSignalNames = map[string]syscall.Signal{
	"ABRT": syscall.SIGABRT,
	"ALRM": syscall.SIGALRM,
	"BUS":  syscall.SIGBUS,
	"FPE":  syscall.SIGFPE,
	"HUP":  syscall.SIGHUP,
	"ILL":  syscall.SIGILL,
	"INT":  syscall.SIGINT,
	"KILL": syscall.SIGKILL,
	"PIPE": syscall.SIGPIPE,
	"QUIT": syscall.SIGQUIT,
	"SEGV": syscall.SIGSEGV,
	"TERM": syscall.SIGTERM,
	"TRAP": syscall.SIGTRAP,
	"USR1": syscall.SIGUSR1,
	"USR2": syscall.SIGUSR2,
}

func sshSignalByName(name string) (syscall.Signal, bool) {
	s, ok := sshSignalNames[name]
	return s, ok
}

func sshSignalName(sig syscall.Signal) (string, bool) {
	for n, v := range sshSignalNames {
		if v == sig {
			return n, true
		}
	}
	return "", false
}

// --------- env construction ---------

func setEnvEntry(list *[]string, kv string) {
	key := kv[:strings.IndexByte(kv, '=')+1]
	for i, e := range *list {
		if strings.HasPrefix(e, key) {
			(*list)[i] = kv
			return
		}
	}
	*list = append(*list, kv)
}

func (s *sshConn) buildSessionEnv(ch *channel, origCmd string, forced bool) []string {
	var env []string
	if s.opts.passEnv {
		for _, e := range os.Environ() {
			if strings.HasPrefix(e, envReexec+"=") {
				continue
			}
			env = append(env, e)
		}
	}
	set := func(kv string) { setEnvEntry(&env, kv) }
	set("USER=" + s.pw.Name)
	set("LOGNAME=" + s.pw.Name)
	set("HOME=" + s.pw.Home)
	set("SHELL=" + s.shell)
	if s.pw.UID == 0 {
		set("PATH=/usr/sbin:/usr/bin:/sbin:/bin")
	} else {
		set("PATH=/usr/bin:/bin")
	}
	if s.opts.langSet {
		set("LANG=" + s.opts.langVal)
	}
	if ch.sess.ptyAllocated {
		set("TERM=" + ch.sess.term)
		set("SSH_TTY=" + ch.sess.ptyName)
	}
	remoteIP, remotePort := splitAddrPort(s.remoteAddr)
	localIP, localPort := splitAddrPort(s.localAddr)
	set(fmt.Sprintf("SSH_CONNECTION=%s %d %s %d", remoteIP, remotePort, localIP, localPort))
	set(fmt.Sprintf("SSH_CLIENT=%s %d %d", remoteIP, remotePort, localPort))
	if s.hasInfo {
		set("SSH_PUBKEYINFO=" + s.pubkeyInfo)
	}
	if s.agentSockPath != "" && ch.sess.agentRequested {
		set("SSH_AUTH_SOCK=" + s.agentSockPath)
	} else if s.agentSockPath != "" {
		// The environment is set up when the agent is created for
		// the connection; sessions started afterwards see it.
		set("SSH_AUTH_SOCK=" + s.agentSockPath)
	}
	if forced {
		set("SSH_ORIGINAL_COMMAND=" + origCmd)
	}
	return env
}

// --------- session process starting ---------

type sessionParams struct {
	Username     string
	UID, GID     int
	Home         string
	Shell        string
	Kind         string // shell, exec, subsystem
	Command      string // command to run with -c (ignored for plain shell)
	Pty          bool
	PtyName      string
	NoMotd       bool
	RemoteAddr   string
}

func (s *sshConn) startSessionProcess(ch *channel, kind string, command string) bool {
	sess := ch.sess
	original := ""
	if kind == "exec" || kind == "subsystem" {
		original = command
	}
	runCommand := command
	forced := false
	if s.opts.forcedCmd != nil {
		runCommand = *s.opts.forcedCmd
		forced = true
	} else if s.keyOpts != nil && s.keyOpts.forcedCmd != nil {
		runCommand = *s.keyOpts.forcedCmd
		forced = true
	}

	params := sessionParams{
		Username:   s.pw.Name,
		UID:        s.pw.UID,
		GID:        s.pw.GID,
		Home:       s.pw.Home,
		Shell:      s.shell,
		Kind:       kind,
		Command:    runCommand,
		Pty:        sess.ptyAllocated,
		PtyName:    sess.ptyName,
		NoMotd:     s.opts.noMotd,
		RemoteAddr: s.remoteAddr,
	}
	env := s.buildSessionEnv(ch, original, forced)

	paramR, paramW, err := os.Pipe()
	if err != nil {
		return false
	}

	cmd := exec.Command(selfExe(), os.Args[1:]...)
	cmd.Args[0] = os.Args[0]
	cmd.Env = append(append([]string{}, env...), envReexec+"=session")

	var stdinW, stdoutR, stderrR *os.File
	if sess.ptyAllocated {
		cmd.Stdin = sess.ptySlave
		cmd.Stdout = sess.ptySlave
		cmd.Stderr = sess.ptySlave
		cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	} else {
		inR, inW, _ := os.Pipe()
		outR, outW, _ := os.Pipe()
		errR, errW, _ := os.Pipe()
		cmd.Stdin = inR
		cmd.Stdout = outW
		cmd.Stderr = errW
		stdinW, stdoutR, stderrR = inW, outR, errR
		defer inR.Close()
		defer outW.Close()
		defer errW.Close()
	}
	// ExtraFiles: fd3 = params read, fd4 = log (server stderr).
	cmd.ExtraFiles = []*os.File{paramR, os.Stderr}

	if err := cmd.Start(); err != nil {
		paramR.Close()
		paramW.Close()
		if stdinW != nil {
			stdinW.Close()
			stdoutR.Close()
			stderrR.Close()
		}
		return false
	}
	paramR.Close()
	// Write params.
	go func() {
		gob.NewEncoder(paramW).Encode(params)
		paramW.Close()
	}()

	sess.cmd = cmd
	sess.started = true
	sess.startedKind = kind
	sess.procDone = make(chan struct{})

	if sess.ptyAllocated {
		// Inbound data goes to the pty master.
		ch.inbound = newInboundWriter(ch, sess.ptyMaster, nil, true)
		sess.outDone.Add(1)
		go func() {
			defer sess.outDone.Done()
			buf := make([]byte, 32768)
			for {
				n, err := sess.ptyMaster.Read(buf)
				if n > 0 {
					ch.sendData(false, buf[:n])
				}
				if err != nil {
					return
				}
			}
		}()
	} else {
		ch.inbound = newInboundWriter(ch, stdinW, func() { stdinW.Close() }, true)
		sess.outDone.Add(2)
		go s.pipeReader(ch, stdoutR, false)
		go s.pipeReader(ch, stderrR, true)
	}
	go s.manageSession(ch)
	return true
}

func (s *sshConn) pipeReader(ch *channel, r *os.File, ext bool) {
	defer ch.sess.outDone.Done()
	defer r.Close()
	buf := make([]byte, 32768)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			ch.sendData(ext, buf[:n])
		}
		if err != nil {
			return
		}
	}
}

func (s *sshConn) manageSession(ch *channel) {
	sess := ch.sess
	err := sess.cmd.Wait()
	// Login-record logout + pty teardown.
	if sess.ptyAllocated {
		s.performLogout(sess.ptyName)
		if sess.ptySlave != nil {
			sess.ptySlave.Close()
			sess.ptySlave = nil
		}
	}
	sess.outDone.Wait()
	if sess.ptyAllocated && sess.ptyMaster != nil {
		sess.ptyMaster.Close()
	}
	close(sess.procDone)

	// If the client already closed the channel, nothing more to send.
	ch.mu.Lock()
	alreadyClosed := ch.sentClose
	ch.mu.Unlock()
	if alreadyClosed {
		s.removeChannel(ch.localID)
		return
	}
	ch.sendEOF()
	// Exit status / signal.
	if sess.cmd.ProcessState != nil {
		ws, _ := sess.cmd.ProcessState.Sys().(syscall.WaitStatus)
		if sess.cmd.ProcessState.Exited() {
			var p []byte
			p = append(p, 98)
			p = appendUint32(p, ch.remoteID)
			p = appendString(p, []byte("exit-status"))
			p = append(p, 0)
			p = appendUint32(p, uint32(sess.cmd.ProcessState.ExitCode()))
			s.pc.writePacket(p)
		} else if ws.Signaled() {
			if name, ok := sshSignalName(ws.Signal()); ok {
				var p []byte
				p = append(p, 98)
				p = appendUint32(p, ch.remoteID)
				p = appendString(p, []byte("exit-signal"))
				p = append(p, 0)
				p = appendString(p, []byte(name))
				if ws.CoreDump() {
					p = append(p, 1)
				} else {
					p = append(p, 0)
				}
				p = appendString(p, []byte{})
				p = appendString(p, []byte{})
				s.pc.writePacket(p)
			}
		}
	}
	_ = err
	ch.sendClose()
	s.removeChannel(ch.localID)
}

func (s *sshConn) performLogout(ptyName string) {
	line := strings.TrimPrefix(ptyName, "/dev/")
	r := utmpLogout(line)
	if r <= 0 {
		errno := 0
		if r < 0 {
			errno = -r
		}
		dbLog("syslogin_perform_logout: logout(%s) returned an error: %s", line, errnoString(errno))
	}
}

// releasePtyIfUnused is called when a channel that allocated a pty is
// closed before a process was started.
func (s *sshConn) releasePtyIfUnused(ch *channel) {
	sess := ch.sess
	if sess == nil || !sess.ptyAllocated || sess.started {
		return
	}
	s.performLogout(sess.ptyName)
	if err := os.Chown(sess.ptyName, 0, 0); err != nil {
		dbLog("chown %s 0 0 failed: %s", sess.ptyName, strerror(err))
	}
	os.Chmod(sess.ptyName, 0666)
	if sess.ptySlave != nil {
		sess.ptySlave.Close()
	}
	if sess.ptyMaster != nil {
		sess.ptyMaster.Close()
	}
}

// ---------- agent forwarding ----------

func (s *sshConn) setupAgentForwarding() bool {
	// Create /tmp/dropbear-XXXXXXXX/auth-XXXXXXXX-N
	for attempts := 0; attempts < 16; attempts++ {
		var rb [4]byte
		rand.Read(rb[:])
		dir := fmt.Sprintf("/tmp/dropbear-%x", rb)
		if err := os.Mkdir(dir, 0700); err != nil {
			continue
		}
		var rb2 [4]byte
		rand.Read(rb2[:])
		// Suffix after the final dash matches the rough shape of the
		// reference implementation (a small integer).
		fdNum := 6
		path := filepath.Join(dir, fmt.Sprintf("auth-%x-%d", rb2, fdNum))
		ln, err := net.Listen("unix", path)
		if err != nil {
			os.RemoveAll(dir)
			return false
		}
		s.agentDir = dir
		s.agentSockLn = ln
		s.agentSockPath = path
		// Set env for sessions started later.
		go s.acceptAgentConns(ln)
		return true
	}
	return false
}

func (s *sshConn) acceptAgentConns(ln net.Listener) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		ch := s.openServerChannel("auth-agent@openssh.com", nil, conn)
		if ch == nil {
			conn.Close()
		}
	}
}

