package main

import (
	"encoding/gob"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

func sessionRunnerMain() int {
	paramFile := os.NewFile(3, "params")
	logFile := os.NewFile(4, "log")
	if logFile != nil {
		logOut = logFile
	}
	var params sessionParams
	if err := gob.NewDecoder(paramFile).Decode(&params); err != nil {
		return 1
	}
	paramFile.Close()

	remoteIP, _ := splitAddrPort(params.RemoteAddr)

	// Regain root effective uid for setup if we are a root-launched
	// server (real uid 0, effective switched to the user after auth).
	if syscall.Getuid() == 0 {
		syscall.Seteuid(0)
		syscall.Setegid(0)
	}

	if params.Pty {
		if !setupControllingTTY(params) {
			recordLogin(params, remoteIP)
			return 1
		}
		// Set pty ownership/mode best-effort.
		ttyGID := 5
		if g := lookupGroup("tty"); g != nil {
			ttyGID = g.GID
		}
		os.Chown(params.PtyName, params.UID, ttyGID)
		os.Chmod(params.PtyName, 0620)
		recordLogin(params, remoteIP)
	}

	// Drop privileges permanently where applicable.
	dropPrivileges(params)

	// Change directory to the user's home.
	if err := os.Chdir(params.Home); err != nil {
		fmt.Fprintf(os.Stderr, "Failed chdir '%s': %s\n", params.Home, strerror(err))
		os.Chdir("/")
	}

	// Print the motd for interactive shell sessions.
	if params.Pty && params.Kind == "shell" && !params.NoMotd {
		if _, err := os.Stat(filepath.Join(params.Home, ".hushlogin")); err != nil {
			if f, err := os.Open("/etc/motd"); err == nil {
				io.Copy(os.Stdout, f)
				f.Close()
			}
		}
	}

	// Close every fd above stderr.
	closeExtraFDs()
	resetSignalsForExec()

	shell := params.Shell
	if shell == "" {
		shell = "/bin/sh"
	}
	base := filepath.Base(shell)
	var argv []string
	if params.PlainShell {
		argv = []string{"-" + base}
	} else {
		argv = []string{base, "-c", params.Command}
	}
	err := syscall.Exec(shell, argv, os.Environ())
	if err != nil {
		now := time.Now()
		fmt.Fprintf(os.Stderr, "[%d] %s Exit (%s) from <%s>: Child failed\n", os.Getpid(), now.Format("Jan 02 15:04:05"), params.Username, params.RemoteAddr)
		return 1
	}
	return 0
}

func setupControllingTTY(params sessionParams) bool {
	// We are a session leader (Setsid by the parent). Open the slave
	// by name, which makes it our controlling terminal.
	f, err := os.OpenFile(params.PtyName, os.O_RDWR, 0)
	if err != nil {
		dbLog("%s: %s", params.PtyName, strerror(err))
		if tty, err2 := os.OpenFile("/dev/tty", os.O_RDWR, 0); err2 != nil {
			dbLog("open /dev/tty failed - could not set controlling tty: %s", strerror(err2))
		} else {
			tty.Close()
		}
		return false
	}
	// If /dev/tty doesn't work yet, try TIOCSCTTY explicitly.
	if tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0); err != nil {
		if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), ioctlTIOCSCTTY, 0); errno != 0 {
			dbLog("ioctl(TIOCSCTTY): %s", errnoString(int(errno)))
			dbLog("open /dev/tty failed - could not set controlling tty: %s", strerror(err))
			f.Close()
			return false
		}
	} else {
		tty.Close()
	}
	// Dup the slave onto 0,1,2.
	for _, fd := range []int{0, 1, 2} {
		syscall.Syscall(syscall.SYS_DUP3, f.Fd(), uintptr(fd), 0)
	}
	if f.Fd() > 2 {
		f.Close()
	}
	return true
}

func recordLogin(params sessionParams, remoteIP string) {
	line := strings.TrimPrefix(params.PtyName, "/dev/")
	// lastlog
	f, err := os.OpenFile("/var/log/lastlog", os.O_RDWR, 0)
	if err != nil {
		dbLog("lastlog_openseek: Couldn't open /var/log/lastlog: %s", strerror(err))
	} else {
		const recSize = 292
		rec := make([]byte, recSize)
		t := uint32(time.Now().Unix())
		rec[0] = byte(t)
		rec[1] = byte(t >> 8)
		rec[2] = byte(t >> 16)
		rec[3] = byte(t >> 24)
		copy(rec[4:36], line)
		copy(rec[36:292], remoteIP)
		f.WriteAt(rec, int64(params.UID)*recSize)
		f.Close()
	}
	utmpLogin(line, remoteIP, params.Username, os.Getpid())
}

func dropPrivileges(params sessionParams) {
	if syscall.Getuid() == 0 {
		groups := userGroupList(params.Username, params.GID)
		syscall.Setgroups(groups)
		syscall.Setgid(params.GID)
		syscall.Setuid(params.UID)
	} else {
		groups := userGroupList(params.Username, params.GID)
		// Best effort: a non-root process may only set groups it
		// already has; ignore errors.
		syscall.Setgroups(groups)
	}
}

func closeExtraFDs() {
	entries, err := os.ReadDir("/proc/self/fd")
	if err != nil {
		return
	}
	for _, e := range entries {
		var fd int
		if _, err := fmt.Sscanf(e.Name(), "%d", &fd); err == nil && fd > 2 {
			syscall.Close(fd)
		}
	}
}

