package main

import (
	"crypto/rand"
	"crypto/sha512"
	"math/big"
	mrand "math/rand"
	"sort"
)

// Streamlined NTRU Prime sntrup761 encapsulation, implemented from
// the algorithm description (polynomial arithmetic in
// (Z/4591)[x]/(x^761-x-1), mixed-radix encodings).

const (
	snP = 761
	snQ = 4591
	snW = 286
)

func snEncode(vals []int, radix int) []byte {
	// Little-endian mixed-radix integer: vals[0] least significant.
	x := big.NewInt(0)
	r := big.NewInt(int64(radix))
	for i := len(vals) - 1; i >= 0; i-- {
		x.Mul(x, r)
		x.Add(x, big.NewInt(int64(vals[i])))
	}
	// Number of bytes needed: ceil(log_256(radix^len))
	// Compute as size of radix^len in bytes.
	total := new(big.Int).Exp(r, big.NewInt(int64(len(vals))), nil)
	nbytes := (total.BitLen() + 7) / 8
	b := x.Bytes() // big endian
	out := make([]byte, nbytes)
	for i := 0; i < len(b); i++ {
		out[i] = b[len(b)-1-i]
	}
	return out
}

func snDecode(data []byte, n int, radix int) []int {
	// Reverse little endian bytes to a big integer.
	rev := make([]byte, len(data))
	for i, v := range data {
		rev[len(data)-1-i] = v
	}
	x := new(big.Int).SetBytes(rev)
	r := big.NewInt(int64(radix))
	vals := make([]int, n)
	mod := new(big.Int)
	for i := 0; i < n; i++ {
		x.QuoRem(x, r, mod)
		vals[i] = int(mod.Int64())
	}
	return vals
}

func snBalance(vals []int) []int {
	out := make([]int, len(vals))
	for i, v := range vals {
		v %= snQ
		if v < 0 {
			v += snQ
		}
		if v > (snQ-1)/2 {
			v -= snQ
		}
		out[i] = v
	}
	return out
}

func snRqDecode(data []byte) []int {
	vals := snDecode(data, snP, snQ)
	return snBalance(vals)
}

func snRqEncode(coeffs []int) []byte {
	vals := make([]int, len(coeffs))
	for i, v := range coeffs {
		v %= snQ
		if v < 0 {
			v += snQ
		}
		vals[i] = v
	}
	return snEncode(vals, snQ)
}

func snRoundedEncode(coeffs []int) []byte {
	vals := make([]int, len(coeffs))
	for i, v := range coeffs {
		vals[i] = v/3 + 765
	}
	return snEncode(vals, 1531)
}

func snSmallEncode(coeffs []int) []byte {
	vals := make([]int, len(coeffs))
	for i, v := range coeffs {
		vals[i] = v + 1
	}
	return snEncode(vals, 3)
}

func snMult(a, b []int) []int {
	// Convolution.
	tmp := make([]int64, 2*snP-1)
	for i := 0; i < snP; i++ {
		if a[i] == 0 {
			continue
		}
		for j := 0; j < snP; j++ {
			tmp[i+j] += int64(a[i]) * int64(b[j])
		}
	}
	// Reduce mod x^p - x - 1: x^p = x + 1.
	for d := 2*snP - 2; d >= snP; d-- {
		tmp[d-snP+1] += tmp[d]
		tmp[d-snP] += tmp[d]
	}
	out := make([]int, snP)
	for i := 0; i < snP; i++ {
		v := int(tmp[i] % snQ)
		out[i] = v
	}
	return snBalance(out)
