func snRound(coeffs []int) []int {
	out := make([]int, len(coeffs))
	for i, v := range coeffs {
		// Round to nearest multiple of 3.
		r := ((v % 3) + 3) % 3
		switch r {
		case 0:
			out[i] = v
		case 1:
			out[i] = v - 1
		case 2:
			out[i] = v + 1
		}
	}
	return out
}

func snHash(prefix byte, parts ...[]byte) []byte {
	h := sha512.New()
	h.Write([]byte{prefix})
	for _, p := range parts {
		h.Write(p)
	}
	return h.Sum(nil)[:32]
}

func snRandomSmall() []int {
