	var seed int64
	var sb [8]byte
	rand.Read(sb[:])
	for i, v := range sb {
		seed |= int64(v) << (8 * i)
	}
	rng := mrand.New(mrand.NewSource(seed))
	rng.Shuffle(snP, func(i, j int) { idx[i], idx[j] = idx[j], idx[i] })
