	signs := make([]int, snW)
	for i := 0; i < snW/2; i++ {
		signs[i] = 1
		signs[snW/2+i] = -1
	}
	rng.Shuffle(snW, func(i, j int) { signs[i], signs[j] = signs[j], signs[i] })
