		r[idx[i]] = signs[i]
	}
	_ = sort.Ints
	return r
}

func sntrupEncapsulate(pub []byte) (secret, ciphertext []byte, ok bool) {
	defer func() {
		if recover() != nil {
			secret, ciphertext, ok = nil, nil, false
		}
	}()
	if len(pub) != 1158 {
		return nil, nil, false
	}
	h := snRqDecode(pub)
	r := snRandomSmall()
	hr := snMult(h, r)
	c := snRound(hr)
	ctPoly := snRoundedEncode(c)
	if len(ctPoly) != 1007 {
		return nil, nil, false
	}
	rEnc := snSmallEncode(r)
	pkHash := snHash(4, pub)
	confirm := snHash(3, rEnc, pkHash)
	ciphertext = append(append([]byte(nil), ctPoly...), confirm...)
	secret = snHash(1, rEnc, ciphertext)
	return secret, ciphertext, true
}
