import pickle, collections, math
ct=pickle.load(open('/tmp/ct_zero_h.pkl','rb')); poly=ct[:1007]
def decode_giant_segment(data,n,radix):
 x=int.from_bytes(data,'little'); vals=[]
 for i in range(n): vals.append(x%radix);x//=radix
 return vals,x
def report(name,vals):
 # vals are digits 0..1530 representing c/3+765
 coeffs=[v-765 for v in vals]
 print(name,'distinct coeffs',len(set(coeffs)),'nonzero',sum(c!=0 for c in coeffs),'top',collections.Counter(coeffs).most_common(8))
for a,b,la,lb in [(380,381,503,504),(381,380,504,503),(380,381,504,503),(381,380,503,504)]:
 v1,r1=decode_giant_segment(poly[:la],a,1531);v2,r2=decode_giant_segment(poly[la:],b,1531);report(f'split {a}/{la}+{b}/{lb} rem{r1},{r2}',v1+v2)
# recursive split decode: define encode length for n as sum of halves ceil when n>1 stopping at n==1 (2 bytes each) won't match length. Try recursive where a segment is decoded as giant if its byte length supplied by external recursion: decode(data,n): if n==1 return [int...]; else split n and bytes proportionally ceil for first half.
def enc_len(n,radix):
 if n==0:return 0
 if n==1:return (radix-1).bit_length()+7>>3  # ceil log256(radix) maybe
 a=n//2; return enc_len(a,radix)+enc_len(n-a,radix)
print('recursive len to single',enc_len(761,1531))
# recursive where base case n<=16 giant
def dec_rec(data,n,radix,base):
 if n<=base:
  vals,r=decode_giant_segment(data,n,radix); return vals
 a=n//2; la=math.ceil(a*math.log(radix,256)); return dec_rec(data[:la],a,radix,base)+dec_rec(data[la:],n-a,radix,base)
for base in [761,381,128,64,32,16,8]:
 try:
  vals=dec_rec(poly,761,1531,base); report(f'rec base{base}',vals)
 except Exception as e:print(base,e)
PY"}

