 return struct.pack('>I',len(p)+pad+1)+bytes([pad])+p+b'\x00'*pad
def ss(b):return struct.pack('>I',len(b))+b
def kexinit():
 p=bytes([20])+b'\x11'*16
 for l in [b'curve25519-sha256',b'ssh-ed25519',b'aes128-ctr',b'aes128-ctr',b'hmac-sha2-256',b'hmac-sha2-256',b'none',b'none',b'',b'']:p+=ss(l)
