import math
def total_len(n,radix,threshold_bits):
 # recursive split into ceil/floor halves until group bits <= threshold, then encode group in ceil(bits/8) bytes
 def rec(m):
  bits=m*math.log2(radix)
  if bits<=threshold_bits or m==1:
   return math.ceil(bits/8)
  a=m//2
  return rec(a)+rec(m-a)
 return rec(n)
